--
-- Name: comun_relata_unlink_collective_membership(uuid, text); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_relata_unlink_collective_membership(p_case_id uuid, p_end_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_collective_id uuid;
  v_count integer;
begin
  if p_end_reason is null or p_end_reason !~ '^RELATA_[A-Z0-9_]{3,80}$' then
    raise exception using errcode='22023', message='COMUN_RELATA_MATCH_END_REASON_INVALID';
  end if;
  for v_collective_id in
    select distinct m.collective_case_id
      from public.comun_relata_case_memberships m
     where m.individual_case_id=p_case_id
       and m.active
  loop
    update public.comun_relata_case_memberships
       set active=false, ended_at=pg_catalog.now(), end_reason=p_end_reason
     where individual_case_id=p_case_id
       and collective_case_id=v_collective_id
       and active;
    update private.comun_relata_case_match_keys
       set active=false, ended_at=pg_catalog.now()
     where individual_case_id=p_case_id
       and collective_case_id=v_collective_id
       and active;
    select count(*)::integer into v_count
      from public.comun_relata_case_memberships
     where collective_case_id=v_collective_id and active;
    update public.comun_relata_collective_cases
       set active_members_count=v_count,
           state=case when v_count=0 then 'inactive' else 'active' end,
           updated_at=pg_catalog.now()
     where id=v_collective_id;
  end loop;
end;
$_$;


ALTER FUNCTION private.comun_relata_unlink_collective_membership(p_case_id uuid, p_end_reason text) OWNER TO supabase_admin;

--
-- Name: comun_require_solidarity_economic_access(uuid, uuid); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_require_solidarity_economic_access(p_organization_territory_id uuid, p_member_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_access_id uuid;
begin
  select access.id into v_access_id
  from private.comun_solidarity_organization_access access
  where access.organization_territory_id = p_organization_territory_id
    and access.member_user_id = p_member_user_id
    and access.state = 'active'
    and access.role in ('editor','facilitator')
  for key share;
  if v_access_id is null then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_ACCESS_FORBIDDEN';
  end if;

  perform 1
  from public.comun_territorial_organizations organization
  join public.comun_hub_territories territory on territory.id = organization.territory_id
  where organization.territory_id = p_organization_territory_id
    and organization.status in ('active','forming')
    and organization.verification_status in ('source_checked','verified')
    and territory.visibility = 'public'
    and territory.status in ('active','monitoring')
    and territory.verification_status in ('source_checked','verified')
  for key share of organization, territory;
  if not found then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_ORGANIZATION_INELIGIBLE';
  end if;
  return v_access_id;
end;
$$;


ALTER FUNCTION private.comun_require_solidarity_economic_access(p_organization_territory_id uuid, p_member_user_id uuid) OWNER TO supabase_admin;

--
-- Name: comun_sidewalk_sync_relata_withdrawal(); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_sidewalk_sync_relata_withdrawal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_record_id uuid;
begin
  if old.state <> 'withdrawn' and new.state = 'withdrawn' then
    update private.comun_sidewalk_relata_intakes
      set review_state = 'withdrawn', reviewed_at = coalesce(reviewed_at, now()), updated_at = now()
      where case_id = new.id and review_state <> 'withdrawn'
      returning published_record_id into v_record_id;

    if v_record_id is not null then
      update public.comun_sidewalk_records
        set status = 'withdrawn', visibility = 'archived',
            public_geometry_geojson = null, updated_at = now()
        where id = v_record_id;
    end if;

    update private.comun_participation_wallet_items
      set presentation_state = 'Retirado', action_required = null,
          withdrawn_at = coalesce(withdrawn_at, now()), updated_at = now(),
          metadata = metadata || jsonb_build_object(
            'sidewalkIntake', true,
            'sidewalkReviewState', 'withdrawn'
          )
      where item_type = 'relata_report' and subject_ref = new.id::text;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.comun_sidewalk_sync_relata_withdrawal() OWNER TO supabase_admin;

--
-- Name: comun_sidewalk_validate_text_array(text[], text[], integer); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_sidewalk_validate_text_array(p_values text[], p_allowed text[], p_maximum integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(cardinality(p_values) between 1 and p_maximum, false)
    and p_values <@ p_allowed
    and cardinality(p_values) = cardinality(array(select distinct unnest(p_values)));
$$;


ALTER FUNCTION private.comun_sidewalk_validate_text_array(p_values text[], p_allowed text[], p_maximum integer) OWNER TO supabase_admin;

--
-- Name: comun_solidarity_economic_content_is_safe(text); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_solidarity_economic_content_is_safe(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select
    coalesce(p_text, '') !~* '[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}'
    and coalesce(p_text, '') !~ '\m[0-9]{3}[. -]?[0-9]{3}[. -]?[0-9]{3}[-. ]?[0-9]{2}\M'
    and coalesce(p_text, '') !~* '(\+?55[[:space:]]*)?(\(?[0-9]{2}\)?[[:space:]]*)?(9[[:space:]]*)?[0-9]{4}[-[:space:]]?[0-9]{4}'
    and coalesce(p_text, '') !~* '(localhost|127\.0\.0\.1|[?&](token|key|secret|password)=|bearer[[:space:]]+[a-z0-9._~\-]+|eyJ[a-zA-Z0-9_\-]{12,}\.)'
    and coalesce(p_text, '') !~* '\m(arma|armas|munição|munições|explosivo|explosivos|cocaína|crack|droga ilícita|drogas ilícitas|medicamento controlado|medicamentos controlados|receita falsa|documento falso|tráfico de pessoas)\M'
    and coalesce(p_text, '') !~* '((abuso|exploração)[[:space:]]+(sexual[[:space:]]+)?(de[[:space:]]+)?(criança|crianças|menor|menores))'
$$;


ALTER FUNCTION private.comun_solidarity_economic_content_is_safe(p_text text) OWNER TO supabase_admin;

--
-- Name: comun_solidarity_onboarding_assert_admin(uuid); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_solidarity_onboarding_assert_admin(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if not exists (
    select 1 from public.comun_admin_users admin_user
    where admin_user.user_id = p_actor_user_id
      and admin_user.is_active = true
      and admin_user.role = 'admin'
  ) then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_ADMIN_FORBIDDEN';
  end if;
end;
$$;


ALTER FUNCTION private.comun_solidarity_onboarding_assert_admin(p_actor_user_id uuid) OWNER TO supabase_admin;

--
-- Name: comun_solidarity_public_contact_is_safe(text); Type: FUNCTION; Schema: private; Owner: supabase_admin
--

CREATE FUNCTION private.comun_solidarity_public_contact_is_safe(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select
    coalesce(p_text, '') !~* '(^|[^[:alnum:]_])(cpf|rg|documento|senha|password|token|secret|chave[[:space:]]+privada|private[[:space:]]+key)([^[:alnum:]_]|$)'
    and coalesce(p_text, '') !~ '[0-9]{3}\.[0-9]{3}\.[0-9]{3}-[0-9]{2}'
    and coalesce(p_text, '') !~* '(endereço[[:space:]]+residencial|rua[[:space:]]+.+(casa|apto|apartamento|n[ºo]?\.?[[:space:]]*[0-9]+))'
    and coalesce(p_text, '') !~* '(localhost|127\.0\.0\.1|[?&](token|key|secret|password)=|bearer[[:space:]]+[a-z0-9._~\-]+|eyJ[a-zA-Z0-9_\-]{12,}\.)'
$_$;


ALTER FUNCTION private.comun_solidarity_public_contact_is_safe(p_text text) OWNER TO supabase_admin;

