--
-- Name: comun_archive_processing_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.comun_archive_processing_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_type text NOT NULL,
    archive_item_id uuid,
    archive_asset_id uuid,
    status text DEFAULT 'queued'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    idempotency_key text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 4 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    failed_at timestamp with time zone,
    last_error_code text,
    last_error_summary text,
    result_summary jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    external_link_id uuid,
    CONSTRAINT comun_archive_processing_job_target_check CHECK ((((job_type = ANY (ARRAY['historical_photo_derivatives'::text, 'territorial_artwork_derivatives'::text, 'community_radio_audio'::text])) AND (archive_asset_id IS NOT NULL)) OR ((job_type = 'music_external_link_check'::text) AND (external_link_id IS NOT NULL)))),
    CONSTRAINT comun_archive_processing_jobs_job_type_check CHECK ((job_type = ANY (ARRAY['historical_photo_derivatives'::text, 'music_external_link_check'::text, 'territorial_artwork_derivatives'::text, 'community_radio_audio'::text]))),
    CONSTRAINT comun_archive_processing_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'retry_scheduled'::text, 'completed'::text, 'failed'::text, 'dead_letter'::text, 'cancel_requested'::text, 'cancelled'::text])))
);


ALTER TABLE public.comun_archive_processing_jobs OWNER TO postgres;

--
-- Name: claim_next_archive_processing_job(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_next_archive_processing_job(p_worker_id text) RETURNS SETOF public.comun_archive_processing_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_id uuid;
begin
 select id into v_id from public.comun_archive_processing_jobs
 where status in ('queued','retry_scheduled') and available_at<=now()
 order by priority asc, created_at asc for update skip locked limit 1;
 if v_id is null then return; end if;
 update public.comun_archive_processing_jobs set status='processing', locked_at=now(), locked_by=left(p_worker_id,100), started_at=coalesce(started_at,now()), attempt_count=attempt_count+1, updated_at=now() where id=v_id;
 return query select * from public.comun_archive_processing_jobs where id=v_id;
end $$;


ALTER FUNCTION public.claim_next_archive_processing_job(p_worker_id text) OWNER TO postgres;

--
-- Name: comun_approve_solidarity_organization_onboarding_v1(uuid, uuid, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_approve_solidarity_organization_onboarding_v1(p_request_id uuid, p_onboarding_id uuid, p_actor_user_id uuid, p_confirmed_organization_type text, p_source_kind text, p_source_title text, p_source_url_public text DEFAULT NULL::text, p_source_summary_public text DEFAULT NULL::text, p_source_note_private text DEFAULT NULL::text) RETURNS TABLE(onboarding_id uuid, state text, territory_id uuid, organization_slug text, access_id uuid, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_onboarding private.comun_solidarity_organization_onboarding%rowtype;
  v_existing_territory_id uuid;
  v_territory_id uuid := gen_random_uuid();
  v_access_id uuid := gen_random_uuid();
  v_source_id uuid;
  v_slug text;
  v_slug_base text;
  v_source_title text;
  v_source_url text;
  v_source_summary text;
  v_source_note text;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  perform private.comun_solidarity_onboarding_assert_admin(p_actor_user_id);
  if p_request_id is null then raise exception 'COMUN_SOLIDARITY_ONBOARDING_REQUEST_ID_REQUIRED'; end if;
  if p_confirmed_organization_type not in ('cooperative','association','collective','informal_group','solidarity_enterprise','network','other') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_TYPE_INVALID';
  end if;
  if p_source_kind not in ('public_url','platform_review','operational_confirmation') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_SOURCE_KIND_INVALID';
  end if;
  v_source_title := pg_catalog.btrim(coalesce(p_source_title, ''));
  v_source_url := nullif(pg_catalog.btrim(coalesce(p_source_url_public, '')), '');
  v_source_summary := pg_catalog.btrim(coalesce(p_source_summary_public, ''));
  v_source_note := nullif(pg_catalog.btrim(coalesce(p_source_note_private, '')), '');
  if pg_catalog.char_length(v_source_title) not between 3 and 200
    or pg_catalog.char_length(v_source_summary) not between 10 and 600
    or (v_source_url is not null and (pg_catalog.char_length(v_source_url) > 1000 or v_source_url !~* '^https://'))
    or (p_source_kind = 'public_url' and v_source_url is null)
    or (v_source_note is not null and pg_catalog.char_length(v_source_note) > 600) then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_SOURCE_INVALID';
  end if;

  select onboarding.* into v_onboarding
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.id = p_onboarding_id
  for update;
  if not found then raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_FOUND'; end if;
  if v_onboarding.last_mutation_request_id = p_request_id and v_onboarding.state = 'approved' then
    select territory.slug into v_slug from public.comun_hub_territories territory where territory.id = v_onboarding.approved_territory_id;
    return query select v_onboarding.id, v_onboarding.state, v_onboarding.approved_territory_id,
      v_slug, v_onboarding.approved_access_id, true;
    return;
  end if;
  if v_onboarding.state <> 'submitted' then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_SUBMITTED';
  end if;
  if v_onboarding.organization_type_candidate is null
    or v_onboarding.presentation_candidate is null
    or v_onboarding.participation_note_private is null then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_INCOMPLETE';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-solidarity-name:' || v_onboarding.normalized_name_candidate, 0));
  select organization.territory_id into v_existing_territory_id
  from public.comun_territorial_organizations organization
  join public.comun_hub_territories territory on territory.id = organization.territory_id
  where private.comun_normalize_solidarity_organization_name(organization.public_name) = v_onboarding.normalized_name_candidate
    and organization.status in ('active','forming')
    and territory.status in ('active','monitoring')
  limit 1;
  if v_existing_territory_id is not null then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_EXISTING_ORGANIZATION';
  end if;

  v_slug_base := pg_catalog.btrim(
    pg_catalog.regexp_replace(
      pg_catalog.lower(v_onboarding.organization_name_candidate), '[^a-z0-9]+', '-', 'g'
    ),
    '-'
  );
  if pg_catalog.char_length(v_slug_base) < 3 then v_slug_base := 'organizacao-solidaria'; end if;
  v_slug_base := pg_catalog.left(v_slug_base, 70);
  v_slug := v_slug_base;
  if exists(select 1 from public.comun_hub_territories territory where territory.slug = v_slug) then
    v_slug := v_slug_base || '-' || pg_catalog.left(v_territory_id::text, 8);
  end if;

  insert into public.comun_hub_territories(
    id, slug, name, territory_type, municipality, public_summary, status,
    geometry_type, location_precision, visibility, verification_status,
    source_summary_public, source_url_public, last_reviewed_at
  ) values (
    v_territory_id, v_slug, v_onboarding.organization_name_candidate,
    case when p_confirmed_organization_type = 'cooperative' then 'cooperative' else 'solidarity_collective' end,
    'Volta Redonda', v_onboarding.presentation_candidate, 'monitoring',
    'point', 'hidden', 'public', 'source_checked',
    v_source_summary, v_source_url, v_now
  );

  insert into public.comun_territorial_organizations(
    territory_id, public_name, organization_type, status, service_territory_public,
    presentation_public, services_public, public_contact_authorized, private_contact,
    verification_status, last_verified_at, internal_notes
  ) values (
    v_territory_id, v_onboarding.organization_name_candidate, p_confirmed_organization_type,
    'forming', v_onboarding.service_territory_candidate, v_onboarding.presentation_candidate,
    array[]::text[],
    case when v_onboarding.public_contact_publication_authorized then v_onboarding.public_contact_candidate else null end,
    null, 'source_checked', v_now, null
  );

  insert into public.comun_territorial_sources(
    territory_id, title, source_type, source_url_public, source_date,
    public_excerpt_summary, confidence_level, review_status, public_note, internal_note
  ) values (
    v_territory_id, v_source_title, 'solidarity_organization_' || p_source_kind,
    v_source_url, v_now::date, v_source_summary, 'medium', 'reviewed',
    'Fonte revisada para exibição da organização no diretório.', v_source_note
  ) returning id into v_source_id;

  insert into private.comun_solidarity_organization_access(
    id, organization_territory_id, member_user_id, requested_role, role, state,
    review_scope, request_note_private, reviewed_by_user_id, review_note_private,
    transition_history_private, requested_at, reviewed_at, activated_at
  ) values (
    v_access_id, v_territory_id, v_onboarding.applicant_user_id, 'facilitator', 'facilitator', 'active',
    'platform', v_onboarding.participation_note_private, p_actor_user_id,
    'Acesso inicial ativado atomicamente após a verificação do onboarding.',
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'event', 'approved_from_organization_onboarding',
      'actorUserId', p_actor_user_id, 'at', v_now
    )), v_now, v_now, v_now
  );

  update private.comun_solidarity_organization_onboarding onboarding set
    organization_type_candidate = p_confirmed_organization_type,
    state = 'approved', reviewed_by_user_id = p_actor_user_id,
    review_message_private = 'Organização verificada para exibição no diretório.',
    reviewed_at = v_now, approved_at = v_now,
    approved_territory_id = v_territory_id, approved_access_id = v_access_id,
    approved_source_id = v_source_id, last_mutation_request_id = p_request_id,
    transition_history_private = onboarding.transition_history_private || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('event', 'approved', 'actorUserId', p_actor_user_id, 'at', v_now)
    )
  where onboarding.id = v_onboarding.id;

  onboarding_id := v_onboarding.id;
  state := 'approved';
  territory_id := v_territory_id;
  organization_slug := v_slug;
  access_id := v_access_id;
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_approve_solidarity_organization_onboarding_v1(p_request_id uuid, p_onboarding_id uuid, p_actor_user_id uuid, p_confirmed_organization_type text, p_source_kind text, p_source_title text, p_source_url_public text, p_source_summary_public text, p_source_note_private text) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_declare_sent(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_declare_sent(p_token_hash_hex text, p_attempt_id uuid, p_sent boolean) RETURNS TABLE(attempt_id uuid, attempt_state text, due_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_wallet uuid;
  v_attempt private.comun_forwarding_attempts%rowtype;
  v_source_domain text;
  v_state text;
  v_due timestamptz;
begin
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;
  select a.* into v_attempt
  from private.comun_forwarding_attempts a
  join private.comun_forwarding_packages p on p.id=a.package_id
  where a.id=p_attempt_id and p.wallet_id=v_wallet and p.withdrawn_at is null
  for update of a;
  if not found or v_attempt.state<>'prepared' then return; end if;
  select source_domain into v_source_domain
  from private.comun_forwarding_packages where id=v_attempt.package_id;
  v_state:=case when p_sent then 'person_declared_sent' else 'abandoned' end;
  v_due:=case when p_sent and v_source_domain='bus' then now()+interval '72 hours' else null end;
  update private.comun_forwarding_attempts set
    state=v_state,declared_at=now(),due_at=v_due,updated_at=now()
  where id=p_attempt_id;
  update private.comun_forwarding_packages set
    state=case when p_sent then 'waiting_response' else 'ready_for_forwarding' end,
    updated_at=now() where id=v_attempt.package_id;
  update private.comun_bus_relata_intakes b set
    state=case when p_sent then 'waiting_response' else 'forwarding_prepared' end,
    updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=v_attempt.package_id and p.source_domain='bus' and b.id=p.bus_intake_id;
  update private.comun_participation_wallet_items wi set
    presentation_state=case when p_sent then 'Aguardando retorno' else 'Pronto para encaminhar' end,
    action_required=case when p_sent then 'Acompanhar retorno' else 'Preparar encaminhamento' end,
    updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=v_attempt.package_id and wi.wallet_id=p.wallet_id
    and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report'
    and wi.archived_at is null;
  insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code)
    values(v_attempt.package_id,p_attempt_id,
      case when p_sent then 'person_declared_sent' else 'not_sent' end,
      case when p_sent then 'FORWARDING_PERSON_DECLARED_SENT' else 'FORWARDING_PERSON_DID_NOT_SEND' end);
  return query select p_attempt_id,v_state,v_due;
end;
$$;


ALTER FUNCTION public.comun_assisted_forwarding_declare_sent(p_token_hash_hex text, p_attempt_id uuid, p_sent boolean) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_list(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_list(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(package_id uuid, state text, source_domain text, category text, subject text, institutional_text text, response_expectation text, attempts jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select p.id,p.state,p.source_domain,c.category,p.subject,p.institutional_text,p.response_expectation,
    coalesce((select jsonb_agg(jsonb_build_object(
      'attemptId',a.id,'sequence',a.sequence_no,'channel',a.channel,
      'institutionalChannelId',a.institutional_channel_id,'state',a.state,
      'openedAt',a.opened_at,'declaredAt',a.declared_at,'dueAt',a.due_at,
      'officialProtocolMasked',case when a.official_protocol is null then null else left(a.official_protocol,3)||'••••' end,
      'respondedAt',a.responded_at,'resolutionOutcome',a.resolution_outcome
    ) order by a.sequence_no) from private.comun_forwarding_attempts a where a.package_id=p.id),'[]'::jsonb)
  from private.comun_forwarding_packages p
  join public.comun_relata_cases c on c.id=p.relata_case_id
  join private.comun_participation_wallet_items wi
    on wi.wallet_id=p.wallet_id and wi.subject_ref=p.relata_case_id::text
    and wi.item_type='relata_report' and wi.archived_at is null
  where p.wallet_id=private.comun_assisted_wallet_id(p_token_hash_hex)
    and wi.id=p_wallet_item_id and p.withdrawn_at is null;
$$;


ALTER FUNCTION public.comun_assisted_forwarding_list(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_open(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_open(p_token_hash_hex text, p_package_id uuid, p_channel text) RETURNS TABLE(attempt_id uuid, attempt_state text, channel text, sequence_no integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select o.attempt_id,o.attempt_state,o.channel,o.sequence_no
  from public.comun_assisted_forwarding_open(p_token_hash_hex,p_package_id,p_channel,null) o;
$$;


ALTER FUNCTION public.comun_assisted_forwarding_open(p_token_hash_hex text, p_package_id uuid, p_channel text) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_open(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_open(p_token_hash_hex text, p_package_id uuid, p_channel text, p_institutional_channel_id text) RETURNS TABLE(attempt_id uuid, attempt_state text, channel text, institutional_channel_id text, sequence_no integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_wallet uuid;
  v_attempt private.comun_forwarding_attempts%rowtype;
  v_sequence integer;
  v_channel_id text:=nullif(lower(trim(p_institutional_channel_id)),'');
begin
  if p_channel not in ('whatsapp','email','phone','in_person','web') then return; end if;
  if v_channel_id is not null and v_channel_id !~ '^[a-z0-9][a-z0-9._-]{0,159}$' then return; end if;
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;
  perform 1 from private.comun_forwarding_packages
    where id=p_package_id and wallet_id=v_wallet and withdrawn_at is null for update;
  if not found then return; end if;
  select a.* into v_attempt from private.comun_forwarding_attempts a
    where a.package_id=p_package_id and a.state='prepared'
      and (
        (v_channel_id is not null and a.institutional_channel_id=v_channel_id)
        or (v_channel_id is null and a.institutional_channel_id is null and a.channel=p_channel)
      );
  if not found then
    select coalesce(max(a.sequence_no),0)+1 into v_sequence
      from private.comun_forwarding_attempts a where a.package_id=p_package_id;
    insert into private.comun_forwarding_attempts(package_id,sequence_no,channel,institutional_channel_id,state)
      values(p_package_id,v_sequence,p_channel,v_channel_id,'prepared') returning * into v_attempt;
    insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code)
      values(p_package_id,v_attempt.id,'channel_opened','FORWARDING_CHANNEL_PREPARED_BY_PERSON');
  end if;
  update private.comun_forwarding_packages set state='forwarding_prepared',updated_at=now()
    where id=p_package_id;
  update private.comun_participation_wallet_items wi set
    presentation_state='Encaminhamento preparado',action_required='Confirmar se conseguiu enviar',updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=p_package_id and wi.wallet_id=p.wallet_id
    and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report' and wi.archived_at is null;
  return query select v_attempt.id,v_attempt.state,v_attempt.channel,v_attempt.institutional_channel_id,v_attempt.sequence_no;
end;
$_$;


ALTER FUNCTION public.comun_assisted_forwarding_open(p_token_hash_hex text, p_package_id uuid, p_channel text, p_institutional_channel_id text) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_record_response(text, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_note text, p_official_protocol text, p_resolved boolean) RETURNS TABLE(attempt_id uuid, attempt_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_attempt private.comun_forwarding_attempts%rowtype;
begin
  if char_length(trim(coalesce(p_response_note,''))) not between 1 and 600
    or char_length(coalesce(p_official_protocol,''))>240 then return; end if;
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;
  select a.* into v_attempt from private.comun_forwarding_attempts a
    join private.comun_forwarding_packages p on p.id=a.package_id
    where a.id=p_attempt_id and p.wallet_id=v_wallet
      and p.source_domain in ('bus','essential_service','civic_service')
      and p.withdrawn_at is null
      and a.state in ('person_declared_sent','no_response') for update of a;
  if not found then return; end if;
  update private.comun_forwarding_attempts set
    state='responded',resolution_outcome=case when p_resolved then 'resolved' else 'unresolved' end,
    response_note=trim(p_response_note),
    official_protocol=nullif(trim(p_official_protocol),''),responded_at=now(),updated_at=now()
    where id=p_attempt_id;
  update private.comun_forwarding_packages set state='responded',updated_at=now()
    where id=v_attempt.package_id;
  update private.comun_bus_relata_intakes b set state='responded',updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=v_attempt.package_id and p.source_domain='bus' and b.id=p.bus_intake_id;
  update private.comun_participation_wallet_items wi set
    presentation_state=case when p_resolved then 'Resolvido' else 'Resposta não resolveu' end,
    action_required=case when p_resolved then null else 'Ver próximo passo' end,
    updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=v_attempt.package_id and wi.wallet_id=p.wallet_id
    and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report' and wi.archived_at is null;
  insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code)
    values(v_attempt.package_id,p_attempt_id,'response_recorded',
      case when p_resolved then 'FORWARDING_RESPONSE_RESOLVED' else 'FORWARDING_RESPONSE_NOT_RESOLVED' end);
  return query select p_attempt_id,'responded'::text;
end;
$$;


ALTER FUNCTION public.comun_assisted_forwarding_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_note text, p_official_protocol text, p_resolved boolean) OWNER TO postgres;

--
-- Name: comun_assisted_forwarding_withdraw(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_assisted_forwarding_withdraw(p_token_hash_hex text, p_package_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_package private.comun_forwarding_packages%rowtype;
begin
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return false; end if;
  select * into v_package from private.comun_forwarding_packages
    where id=p_package_id and wallet_id=v_wallet and withdrawn_at is null for update;
  if not found then return false; end if;
  update private.comun_forwarding_attempts set
    state=case when state='prepared' then 'abandoned' else state end,
    official_protocol=case when v_package.source_domain='sensitive_service' then null else official_protocol end,
    response_note=case when v_package.source_domain='sensitive_service' then null else response_note end,
    updated_at=now() where package_id=p_package_id;
  update private.comun_forwarding_packages set
    state='withdrawn',withdrawn_at=now(),
    subject=case when source_domain='sensitive_service' then 'Encaminhamento sensível retirado' else subject end,
    institutional_text=case when source_domain='sensitive_service' then 'Conteúdo retirado pela pessoa.' else institutional_text end,
    disclosure_manifest=case when source_domain='sensitive_service' then jsonb_build_object(
      'policy',policy_identifier,'includeIssueType',false,'includeUnitLabel',false,
      'includeNetworkLabel',false,'includeApproximatePeriod',false,
      'includePersonAuthoredSummary',false,
      'channelOnly',policy_identifier='child_protection_channel_only_v1'
    ) else disclosure_manifest end,
    content_withdrawn_at=case when source_domain='sensitive_service' then now() else content_withdrawn_at end,
    updated_at=now() where id=p_package_id;
  update private.comun_bus_relata_intakes set
    state='withdrawn',withdrawn_at=coalesce(withdrawn_at,now()),updated_at=now()
    where id=v_package.bus_intake_id and v_package.source_domain='bus';
  update private.comun_participation_wallet_items set
    presentation_state='Retirado',action_required=null,updated_at=now()
    where wallet_id=v_wallet and subject_ref=v_package.relata_case_id::text
      and item_type='relata_report' and archived_at is null;
  insert into private.comun_forwarding_events(package_id,event_type,result_code)
    values(p_package_id,'forwarding_withdrawn',case
      when v_package.source_domain='sensitive_service' then 'FORWARDING_SENSITIVE_CONTENT_WITHDRAWN'
      else 'FORWARDING_WITHDRAWN_BY_PERSON' end);
  return true;
end;
$$;


ALTER FUNCTION public.comun_assisted_forwarding_withdraw(p_token_hash_hex text, p_package_id uuid) OWNER TO postgres;

