--
-- Name: comun_bus_intake_create(text, text, text, text, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_bus_intake_create(p_protocol text, p_receipt_secret text, p_issue_type text, p_line_label text, p_direction text, p_vehicle_order text, p_observed_at timestamp with time zone, p_wait_minutes integer) RETURNS TABLE(intake_id uuid, case_id uuid, intake_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_context record; v_intake private.comun_bus_relata_intakes%rowtype;
begin
  select * into v_context from private.comun_relata_authorized_context(p_protocol,p_receipt_secret);
  if not found or v_context.category <> 'public_transport' or v_context.case_state='withdrawn'
    or p_issue_type not in ('delay_or_not_passed','overcrowding','accessibility','vehicle_condition','stop_or_shelter','conduct_or_service','timetable_information','other')
    or p_observed_at is null or p_observed_at > now()+interval '5 minutes'
    or char_length(coalesce(p_line_label,''))>80 or char_length(coalesce(p_direction,''))>80
    or char_length(coalesce(p_vehicle_order,''))>80 or coalesce(p_wait_minutes,0) not between 0 and 720 then return; end if;
  insert into private.comun_bus_relata_intakes as current(report_id,case_id,issue_type,line_label,direction,vehicle_order,observed_at,wait_minutes,state)
  values(v_context.report_id,v_context.case_id,p_issue_type,nullif(trim(p_line_label),''),nullif(trim(p_direction),''),nullif(trim(p_vehicle_order),''),p_observed_at,p_wait_minutes,'ready_for_forwarding')
  on conflict(report_id) do update set updated_at=current.updated_at returning * into v_intake;
  update private.comun_participation_wallet_items set
    title_template='Relato de ônibus', presentation_state='Pronto para encaminhar', action_required='Preparar encaminhamento STMU',
    metadata=metadata||jsonb_strip_nulls(jsonb_build_object('relatedDomain','bus','issueType',v_intake.issue_type,'line',v_intake.line_label,'direction',v_intake.direction,'observedAt',v_intake.observed_at)), updated_at=now()
  where item_type='relata_report' and subject_ref=v_context.case_id::text and archived_at is null;
  return query select v_intake.id,v_intake.case_id,v_intake.state;
end; $$;


ALTER FUNCTION public.comun_bus_intake_create(p_protocol text, p_receipt_secret text, p_issue_type text, p_line_label text, p_direction text, p_vehicle_order text, p_observed_at timestamp with time zone, p_wait_minutes integer) OWNER TO postgres;

--
-- Name: comun_bus_intake_withdraw(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_bus_intake_withdraw(p_protocol text, p_receipt_secret text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_context record;
begin
  select * into v_context from private.comun_relata_authorized_context(p_protocol,p_receipt_secret);
  if not found or v_context.category<>'public_transport' then return false; end if;
  update private.comun_bus_relata_intakes set state='withdrawn',withdrawn_at=coalesce(withdrawn_at,now()),updated_at=now() where report_id=v_context.report_id;
  return found;
end; $$;


ALTER FUNCTION public.comun_bus_intake_withdraw(p_protocol text, p_receipt_secret text) OWNER TO postgres;

--
-- Name: comun_civic_assisted_prepare(text, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_civic_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid, p_public_reference text, p_person_authored_summary text, p_preview_confirmed boolean) RETURNS TABLE(package_id uuid, state text, category text, subject text, institutional_text text, response_expectation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_wallet uuid;
  v_case public.comun_relata_cases%rowtype;
  v_package private.comun_forwarding_packages%rowtype;
  v_reference text:=nullif(trim(coalesce(p_public_reference,'')), '');
  v_summary text:=nullif(trim(coalesce(p_person_authored_summary,'')), '');
  v_subject text;
  v_label text;
  v_body text;
begin
  if p_preview_confirmed is not true
    or char_length(coalesce(v_reference,'')) not between 3 and 160
    or char_length(coalesce(v_summary,'')) not between 8 and 1000
    or position('@' in coalesce(v_reference,''))>0
    or position('@' in coalesce(v_summary,''))>0
    or coalesce(v_reference,'') ~ '[0-9]{8,}'
    or coalesce(v_summary,'') ~ '[0-9]{8,}'
  then return; end if;

  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;

  select c.* into v_case
  from private.comun_participation_wallet_items wi
  join public.comun_relata_cases c on c.id=wi.subject_ref::uuid
  where wi.id=p_wallet_item_id
    and wi.wallet_id=v_wallet
    and wi.item_type='relata_report'
    and wi.archived_at is null
    and c.state<>'withdrawn'
    and c.category in (
      'waste_or_debris','smoke_or_environmental_trace',
      'environmental_pollution','stormwater_drainage',
      'urban_flooding','tree_hazard'
    )
    and c.urgency not in ('urgent','emergency')
    and coalesce((c.routing_decision->>'immediateDanger') in ('true','sim'),false)=false
    and coalesce((c.routing_decision->>'smokeActive') in ('true','sim'),false)=false
    and coalesce((c.routing_decision->>'floodActiveRisk') in ('true','sim'),false)=false
    and coalesce(c.routing_decision->>'treeFallState','')<>'falling';
  if not found then return; end if;

  v_label:=case v_case.category
    when 'waste_or_debris' then 'Lixo ou entulho em área pública'
    when 'smoke_or_environmental_trace' then 'Vestígio ambiental ou fumaça não ativa'
    when 'environmental_pollution' then 'Poluição ambiental'
    when 'stormwater_drainage' then 'Drenagem ou bueiro'
    when 'urban_flooding' then 'Alagamento sem risco imediato'
    when 'tree_hazard' then 'Avaliação de árvore ou galho'
    else null end;
  if v_label is null then return; end if;
  v_subject:=v_label;
  v_body:='Protocolo COMUN: '||v_case.protocol||E'\n\n'
    ||'Natureza: '||v_label||E'\n'
    ||'Referência pública aproximada: '||v_reference||E'\n'
    ||'Mensagem escrita para este encaminhamento: '||v_summary||E'\n\n'
    ||'Esta mensagem foi conferida pela pessoa. O COMUN não envia automaticamente.';

  perform pg_advisory_xact_lock(hashtextextended(v_case.id::text,4816));
  select * into v_package
  from private.comun_forwarding_packages
  where wallet_id=v_wallet and relata_case_id=v_case.id and withdrawn_at is null
  for update;
  if found then
    if v_package.source_domain<>'civic_service'
      or v_package.subject<>v_subject
      or v_package.institutional_text<>v_body
    then return; end if;
    return query select v_package.id,v_package.state,v_case.category,
      v_package.subject,v_package.institutional_text,v_package.response_expectation;
    return;
  end if;

  insert into private.comun_forwarding_packages(
    wallet_id,relata_case_id,bus_intake_id,source_domain,state,subject,
    institutional_text,response_expectation
  ) values (
    v_wallet,v_case.id,null,'civic_service','ready_for_forwarding',v_subject,
    v_body,'O canal oficial não informa prazo de resposta no catálogo do COMUN.'
  ) returning * into v_package;

  update private.comun_participation_wallet_items set
    presentation_state='Encaminhamento preparado',
    action_required='Conferir e abrir o canal oficial',updated_at=now()
  where id=p_wallet_item_id and wallet_id=v_wallet;
  insert into private.comun_forwarding_events(package_id,event_type,result_code)
    values(v_package.id,'package_prepared','FORWARDING_CIVIC_PACKAGE_PREPARED');
  return query select v_package.id,v_package.state,v_case.category,
    v_package.subject,v_package.institutional_text,v_package.response_expectation;
end;
$$;


ALTER FUNCTION public.comun_civic_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid, p_public_reference text, p_person_authored_summary text, p_preview_confirmed boolean) OWNER TO postgres;

--
-- Name: comun_civic_wallet_item_context(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_civic_wallet_item_context(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(category text, urgency text, immediate_danger boolean, smoke_active boolean, flood_active_risk boolean, tree_fall_state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select
    c.category,
    c.urgency,
    coalesce((c.routing_decision->>'immediateDanger') in ('true','sim'),false),
    coalesce((c.routing_decision->>'smokeActive') in ('true','sim'),false),
    coalesce((c.routing_decision->>'floodActiveRisk') in ('true','sim'),false),
    nullif(c.routing_decision->>'treeFallState','')
  from private.comun_participation_wallet_items wi
  join public.comun_relata_cases c on c.id=wi.subject_ref::uuid
  where wi.id=p_wallet_item_id
    and wi.wallet_id=private.comun_assisted_wallet_id(p_token_hash_hex)
    and wi.item_type='relata_report'
    and wi.archived_at is null
    and c.state<>'withdrawn'
    and c.category in (
      'waste_or_debris','smoke_or_environmental_trace',
      'environmental_pollution','stormwater_drainage',
      'urban_flooding','tree_hazard'
    )
    and c.urgency not in ('urgent','emergency')
    and coalesce((c.routing_decision->>'immediateDanger') in ('true','sim'),false)=false
    and coalesce((c.routing_decision->>'smokeActive') in ('true','sim'),false)=false
    and coalesce((c.routing_decision->>'floodActiveRisk') in ('true','sim'),false)=false
    and coalesce(c.routing_decision->>'treeFallState','')<>'falling';
$$;


ALTER FUNCTION public.comun_civic_wallet_item_context(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_claim_search_embedding_jobs(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_claim_search_embedding_jobs(p_limit integer DEFAULT 8) RETURNS TABLE(job_id bigint, section_id uuid, content_checksum text, public_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'COMUN_SEARCH_SERVER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  return query
  with claimed as (
    select j.id
    from public.comun_search_embedding_jobs j
    where j.state in ('pending', 'failed') and j.available_at <= now() and j.attempts < 5
    order by j.available_at, j.id
    for update skip locked
    limit least(greatest(coalesce(p_limit, 8), 1), 16)
  ), updated as (
    update public.comun_search_embedding_jobs j
    set state = 'processing', attempts = attempts + 1, locked_at = now(), failure_code = null
    from claimed c where j.id = c.id
    returning j.id, j.section_id, j.content_checksum
  )
  select u.id, u.section_id, u.content_checksum, s.public_text
  from updated u join public.comun_search_sections s on s.id = u.section_id;
end
$$;


ALTER FUNCTION public.comun_claim_search_embedding_jobs(p_limit integer) OWNER TO postgres;

--
-- Name: comun_collective_action_member_journey_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_collective_action_member_journey_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.status = 'withdrew' and old.status is distinct from 'withdrew' and exists (
    select 1
    from public.comun_collective_action_task_assignments assignment
    join public.comun_collective_action_tasks task on task.id = assignment.task_id
    where task.action_id = new.action_id
      and assignment.member_user_id = new.member_user_id
      and assignment.status = 'active'
  ) then
    raise exception 'COMUN_COLLECTIVE_RELEASE_TASKS_BEFORE_LEAVING';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.comun_collective_action_member_journey_guard() OWNER TO postgres;

--
-- Name: comun_collective_action_task_capacity_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_collective_action_task_capacity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  capacity integer;
  current_count integer;
  task_state text;
  task_due_at timestamptz;
begin
  if new.status <> 'active' or (tg_op = 'UPDATE' and old.status = 'active') then
    return new;
  end if;

  select desired_count, state, due_at into capacity, task_state, task_due_at
  from public.comun_collective_action_tasks
  where id = new.task_id
  for update;

  if task_state is null or task_state not in ('open', 'in_progress') or (task_due_at is not null and task_due_at < now()) then
    raise exception 'COMUN_COLLECTIVE_TASK_NOT_AVAILABLE';
  end if;

  select count(*) into current_count
  from public.comun_collective_action_task_assignments
  where task_id = new.task_id and status = 'active' and id is distinct from new.id;

  if current_count >= capacity then
    raise exception 'COMUN_COLLECTIVE_TASK_CAPACITY_REACHED';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.comun_collective_action_task_capacity_guard() OWNER TO postgres;

--
-- Name: comun_complete_search_embedding_job(bigint, text, text, text, extensions.vector); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_complete_search_embedding_job(p_job_id bigint, p_content_checksum text, p_model text, p_version text, p_embedding extensions.vector) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_section_id uuid;
  v_document_id uuid;
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'COMUN_SEARCH_SERVER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  select j.section_id into v_section_id
  from public.comun_search_embedding_jobs j
  where j.id = p_job_id and j.state = 'processing' and j.content_checksum = p_content_checksum
  for update;
  if v_section_id is null then return false; end if;

  update public.comun_search_sections s set
    embedding = p_embedding, embedding_model = left(p_model, 80), embedding_version = left(p_version, 80),
    embedding_dimensions = 384, indexing_state = 'ready', embedded_at = now()
  where s.id = v_section_id and s.content_checksum = p_content_checksum
  returning s.document_id into v_document_id;
  if v_document_id is null then return false; end if;

  update public.comun_search_embedding_jobs set state = 'completed', completed_at = now(), locked_at = null
  where id = p_job_id;
  update public.comun_search_documents d set
    indexing_state = case when exists (
      select 1 from public.comun_search_sections s where s.document_id = d.id and s.indexing_state <> 'ready'
    ) then 'embedding_pending' else 'ready' end,
    embedding_model = left(p_model, 80), embedding_version = left(p_version, 80), embedding_dimensions = 384,
    embedded_at = case when not exists (
      select 1 from public.comun_search_sections s where s.document_id = d.id and s.indexing_state <> 'ready'
    ) then now() else d.embedded_at end
  where d.id = v_document_id;
  return true;
end
$$;


ALTER FUNCTION public.comun_complete_search_embedding_job(p_job_id bigint, p_content_checksum text, p_model text, p_version text, p_embedding extensions.vector) OWNER TO postgres;

--
-- Name: comun_create_cultural_contribution_intake_v1(text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_cultural_contribution_intake_v1(p_intent_text_private text, p_source_surface text, p_request_id uuid, p_resume_token_hash text DEFAULT NULL::text, p_member_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(intake_id uuid, public_protocol text, status text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'extensions'
    AS $$
declare
  v_id uuid;
  v_protocol text;
begin
  if p_intent_text_private is null or char_length(trim(p_intent_text_private)) not between 1 and 10000 then
    raise exception 'invalid_intent';
  end if;
  if p_source_surface is null or char_length(trim(p_source_surface)) not between 1 and 80 then
    raise exception 'invalid_source';
  end if;

  select i.id, i.public_protocol into v_id, v_protocol
    from private.comun_cultural_contribution_intakes as i
   where i.request_id = p_request_id;
  if v_id is not null then
    return query
      select v_id, v_protocol, i.status
        from private.comun_cultural_contribution_intakes as i
       where i.id = v_id;
    return;
  end if;

  if p_resume_token_hash is not null and (
    select count(*)
      from private.comun_cultural_contribution_intakes as i
     where i.resume_token_hash = p_resume_token_hash
       and i.created_at > now() - interval '1 hour'
  ) >= 5 then
    raise exception 'rate_limited';
  end if;

  v_id := gen_random_uuid();
  v_protocol := 'ACERVO-' || upper(substr(replace(v_id::text, '-', ''), 1, 12));
  insert into private.comun_cultural_contribution_intakes(
    id, public_protocol, member_user_id, intent_text_private, source_surface,
    request_id, resume_token_hash
  ) values (
    v_id, v_protocol, p_member_user_id, trim(p_intent_text_private),
    trim(p_source_surface), p_request_id, p_resume_token_hash
  );
  return query select v_id, v_protocol, 'draft'::text;
end
$$;


ALTER FUNCTION public.comun_create_cultural_contribution_intake_v1(p_intent_text_private text, p_source_surface text, p_request_id uuid, p_resume_token_hash text, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: comun_create_pauta_low_friction_v1(uuid, text, text, text, text, text, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_pauta_low_friction_v1(p_actor_user_id uuid, p_question text, p_normalized_question text, p_title text, p_slug_base text, p_request_key text, p_fingerprint_hash text DEFAULT NULL::text, p_allow_duplicate boolean DEFAULT false, p_public_evidence jsonb DEFAULT NULL::jsonb) RETURNS TABLE(result text, pauta_id uuid, pauta_slug text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  normalized text;
  request_digest bytea;
  actor_digest bytea;
  fingerprint_digest bytea;
  question_digest bytea;
  existing_request private.comun_pauta_creation_requests%rowtype;
  duplicate_pauta record;
  new_pauta_id uuid := extensions.gen_random_uuid();
  final_slug text;
  recent_actor_hour integer;
  recent_actor_day integer;
  recent_fingerprint_hour integer := 0;
begin
  normalized := lower(regexp_replace(trim(p_question), '\s+', ' ', 'g'));
  if p_actor_user_id is null
    or char_length(trim(p_question)) not between 12 and 500
    or normalized <> p_normalized_question
    or char_length(trim(p_title)) not between 3 and 120
    or p_slug_base !~ '^[a-z0-9][a-z0-9-]{1,78}[a-z0-9]$'
    or p_request_key !~ '^[0-9a-f]{64}$'
    or (p_fingerprint_hash is not null and p_fingerprint_hash !~ '^[0-9a-f]{64}$')
  then
    raise exception using errcode = '22023', message = 'COMUN_PAUTA_CREATION_INVALID_INPUT';
  end if;

  if p_public_evidence is not null and not (
    (
      jsonb_typeof(p_public_evidence) = 'object'
      and p_public_evidence ->> 'contractVersion' = 'comun.public-evidence-citation.v1'
      and p_public_evidence ->> 'namespace' = 'comun.panorama'
      and p_public_evidence ->> 'refId' like 'panorama:%'
      and p_public_evidence ->> 'versionId' ~ '^sha256:[0-9a-f]{64}$'
      and p_public_evidence ->> 'publicPath' ~ '^/comun/observatorios(?:/|$)'
    )
    or
    (
      jsonb_typeof(p_public_evidence) = 'object'
      and p_public_evidence ->> 'contractVersion' = 'comun.public-evidence-citation.v1'
      and p_public_evidence ->> 'namespace' = 'comun.denuncias'
      and p_public_evidence ->> 'refId' ~ '^denuncias:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      and p_public_evidence ->> 'versionId' ~ '^sha256:[0-9a-f]{64}$'
      and p_public_evidence ->> 'publicPath' ~ '^/comun/denuncias/problemas/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      and p_public_evidence ->> 'claimKind' = 'community_observation'
      and p_public_evidence ->> 'sourceKind' = 'reviewed_community_projection'
      and p_public_evidence ->> 'category' in ('public_lighting', 'power_distribution', 'smoke_or_environmental_trace')
      and p_public_evidence ->> 'policyVersion' = 'relata-public-projection-v1'
      and jsonb_typeof(p_public_evidence -> 'sourceRefs') = 'array'
      and jsonb_array_length(p_public_evidence -> 'sourceRefs') = 0
      and jsonb_typeof(p_public_evidence -> 'limitations') = 'array'
      and jsonb_typeof(p_public_evidence -> 'location') = 'object'
      and (p_public_evidence ->> 'reportCount') ~ '^[0-9]+$'
      and (p_public_evidence ->> 'firstObservedDate') ~ '^\d{4}-\d{2}-\d{2}$'
      and (p_public_evidence ->> 'lastActivityDate') ~ '^\d{4}-\d{2}-\d{2}$'
      and (p_public_evidence #>> '{location, label}') = 'área aproximada'
      and (p_public_evidence #>> '{location, uncertaintyRadiusMeters}') ~ '^[0-9]+(\.[0-9]+)?$'
    )
  ) then
    raise exception using errcode = '22023', message = 'COMUN_PAUTA_CREATION_INVALID_EVIDENCE';
  end if;

  request_digest := extensions.digest('pauta-create-request-v1:' || p_request_key, 'sha256');
  actor_digest := extensions.digest('pauta-create-actor-v1:' || p_actor_user_id::text, 'sha256');
  question_digest := extensions.digest('pauta-create-question-v1:' || normalized, 'sha256');
  if p_fingerprint_hash is not null then
    fingerprint_digest := extensions.digest('pauta-create-fingerprint-v1:' || p_fingerprint_hash, 'sha256');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_key, 0));
  select * into existing_request
  from private.comun_pauta_creation_requests requests
  where requests.request_hash = request_digest;
  if found then
    return query select 'created'::text, existing_request.pauta_id, spaces.slug, true
      from public.comun_pauta_spaces spaces where spaces.id = existing_request.pauta_id;
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(normalized, 1));
  if not p_allow_duplicate then
    select spaces.id, spaces.slug into duplicate_pauta
    from public.comun_pauta_spaces spaces
    where spaces.visibility = 'public'
      and spaces.status <> 'archived'
      and lower(regexp_replace(trim(spaces.problem_public), '\s+', ' ', 'g')) = normalized
    order by spaces.updated_at desc
    limit 1;
    if found then
      return query select 'duplicate_candidate'::text, duplicate_pauta.id, duplicate_pauta.slug, false;
      return;
    end if;
  end if;

  select count(*) filter (where created_at >= now() - interval '1 hour'), count(*)
    into recent_actor_hour, recent_actor_day
  from private.comun_pauta_creation_requests
  where actor_hash = actor_digest and created_at >= now() - interval '1 day';
  if fingerprint_digest is not null then
    select count(*) into recent_fingerprint_hour
    from private.comun_pauta_creation_requests
    where fingerprint_hash = fingerprint_digest and created_at >= now() - interval '1 hour';
  end if;
  if recent_actor_hour >= 3 or recent_actor_day >= 10 or recent_fingerprint_hour >= 5 then
    return query select 'rate_limited'::text, null::uuid, null::text, false;
    return;
  end if;

  final_slug := p_slug_base;
  if exists(select 1 from public.comun_pauta_spaces spaces where spaces.slug = final_slug) then
    final_slug := left(p_slug_base, 70) || '-' || substring(encode(extensions.digest(new_pauta_id::text, 'sha256'), 'hex'), 1, 8);
  end if;

  insert into public.comun_pauta_spaces(
    id, slug, title, summary, category, community, status, visibility,
    public_status, risk_level, problem_public, demand_public,
    proposals_public, participation_public, territory_id
  ) values (
    new_pauta_id, final_slug, trim(p_title), null, null, null, 'observing', 'public',
    'received', 'normal', trim(p_question), null, null, null, null
  );

  insert into public.comun_pauta_memberships(pauta_id, member_user_id, role, status)
  values (new_pauta_id, p_actor_user_id, 'participant', 'active');

  if p_public_evidence is not null then
    insert into public.comun_pauta_evidence_items(
      pauta_id, source_type, source_id, title, summary, evidence_type,
      sensitivity, status, public_note, internal_note,
      public_evidence_ref_id, public_evidence_version, public_evidence_payload
    ) values (
      new_pauta_id, 'public_evidence', null, p_public_evidence ->> 'title',
      p_public_evidence ->> 'referencePeriod', 'dado_agregado',
      'public_safe', 'approved', p_public_evidence #>> '{limitations,0}', null,
      p_public_evidence ->> 'refId', p_public_evidence ->> 'versionId', p_public_evidence
    );
  end if;

  insert into private.comun_pauta_creation_requests(
    request_hash, actor_hash, fingerprint_hash, normalized_question_hash, pauta_id
  ) values (request_digest, actor_digest, fingerprint_digest, question_digest, new_pauta_id);

  return query select 'created'::text, new_pauta_id, final_slug, false;
end;
$_$;


ALTER FUNCTION public.comun_create_pauta_low_friction_v1(p_actor_user_id uuid, p_question text, p_normalized_question text, p_title text, p_slug_base text, p_request_key text, p_fingerprint_hash text, p_allow_duplicate boolean, p_public_evidence jsonb) OWNER TO postgres;

--
-- Name: comun_create_solidarity_need_by_access_v1(uuid, uuid, uuid, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_solidarity_need_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_slug_base text, p_title text, p_public_summary text, p_need_type text DEFAULT 'other'::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(subject_id uuid, subject_slug text, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event private.comun_solidarity_economic_content_events%rowtype;
  v_access_id uuid;
  v_subject_id uuid;
  v_slug text;
  v_now timestamptz := clock_timestamp();
begin
  if p_request_id is null then raise exception 'COMUN_SOLIDARITY_ECONOMIC_REQUEST_ID_REQUIRED'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-economic-request:' || p_request_id::text, 0));
  select event.* into v_event from private.comun_solidarity_economic_content_events event where event.request_id = p_request_id;
  if found then
    if v_event.actor_member_user_id <> p_actor_user_id or v_event.organization_territory_id <> p_organization_territory_id
      or v_event.operation <> 'need.create' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_IDEMPOTENCY_CONFLICT'; end if;
    select need.slug, need.status into v_slug, state from public.comun_territorial_needs need where need.id = v_event.subject_id;
    return query select v_event.subject_id, v_slug, state, true;
    return;
  end if;
  v_access_id := private.comun_require_solidarity_economic_access(p_organization_territory_id, p_actor_user_id);
  if (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id and event.operation in ('offer.create','need.create')
        and event.occurred_at >= v_now - interval '24 hours') >= 20 then raise exception 'COMUN_SOLIDARITY_ECONOMIC_CREATE_RATE_LIMIT'; end if;

  p_title := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_title, ''), '[[:space:]]+', ' ', 'g'));
  p_public_summary := pg_catalog.btrim(coalesce(p_public_summary, ''));
  p_need_type := coalesce(nullif(p_need_type, ''), 'other');
  if pg_catalog.char_length(p_title) not between 3 and 160 or pg_catalog.char_length(p_public_summary) not between 10 and 1200
    or p_need_type not in ('equipment','vehicle','space','input','training','technical_support','partnership','volunteering','donation','hiring','infrastructure','communication','other')
    or (p_due_at is not null and p_due_at <= v_now)
    or not private.comun_solidarity_economic_content_is_safe(p_title || E'\n' || p_public_summary) then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_INVALID';
  end if;
  p_slug_base := pg_catalog.lower(pg_catalog.regexp_replace(coalesce(p_slug_base, ''), '[^a-z0-9]+', '-', 'g'));
  p_slug_base := pg_catalog.btrim(pg_catalog.left(p_slug_base, 72), '-');
  if pg_catalog.char_length(p_slug_base) < 3 then p_slug_base := 'necessidade-solidaria'; end if;
  v_slug := p_slug_base;
  if exists(select 1 from public.comun_territorial_needs need where need.slug = v_slug) then
    v_slug := pg_catalog.left(p_slug_base, 62) || '-' || pg_catalog.left(pg_catalog.replace(gen_random_uuid()::text, '-', ''), 8);
  end if;

  insert into public.comun_territorial_needs(
    slug, title, public_summary, need_type, status, territory_id, organization_territory_id,
    project_id, pauta_id, action_id, task_id, responsible_internal, due_at, visibility, internal_notes
  ) values (v_slug, p_title, p_public_summary, p_need_type, 'open', p_organization_territory_id,
    p_organization_territory_id, null, null, null, null, null, p_due_at, 'public', null)
  returning id into v_subject_id;
  insert into private.comun_solidarity_economic_content_events(
    request_id, organization_territory_id, actor_access_id, actor_member_user_id,
    subject_type, subject_id, operation, from_state, to_state, occurred_at
  ) values (p_request_id, p_organization_territory_id, v_access_id, p_actor_user_id,
    'need', v_subject_id, 'need.create', null, 'open', v_now);
  return query select v_subject_id, v_slug, 'open'::text, false;
end;
$$;


ALTER FUNCTION public.comun_create_solidarity_need_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_slug_base text, p_title text, p_public_summary text, p_need_type text, p_due_at timestamp with time zone) OWNER TO postgres;

--
-- Name: comun_create_solidarity_need_interest_v1(uuid, uuid, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_solidarity_need_interest_v1(p_request_id uuid, p_need_id uuid, p_member_user_id uuid, p_message_private text, p_contact_private text, p_consent_version text, p_consent_to_contact boolean) RETURNS TABLE(interest_id uuid, connection_state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_existing public.comun_territorial_need_interests%rowtype;
  v_need public.comun_territorial_needs%rowtype;
  v_now timestamptz := clock_timestamp();
  v_recent_count integer;
begin
  if p_request_id is null or p_need_id is null or p_member_user_id is null
    or not exists(select 1 from auth.users where id = p_member_user_id) then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_REQUEST_INVALID';
  end if;
  p_message_private := btrim(coalesce(p_message_private, ''));
  p_contact_private := btrim(coalesce(p_contact_private, ''));
  if char_length(p_message_private) not between 10 and 600 then raise exception 'COMUN_SOLIDARITY_CONNECTION_MESSAGE_INVALID'; end if;
  if p_consent_to_contact is not true or p_consent_version <> 'comun.solidarity-contact-consent.v1'
    or char_length(p_contact_private) not between 3 and 200 then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_CONSENT_INVALID';
  end if;
  select * into v_existing from public.comun_territorial_need_interests where create_request_id=p_request_id;
  if found then
    if v_existing.need_id<>p_need_id or v_existing.member_user_id<>p_member_user_id then raise exception 'COMUN_SOLIDARITY_CONNECTION_IDEMPOTENCY_CONFLICT'; end if;
    return query select v_existing.id, v_existing.status, true; return;
  end if;
  select * into v_existing from public.comun_territorial_need_interests where need_id=p_need_id and member_user_id=p_member_user_id and status in ('pending','accepted') order by created_at desc limit 1;
  if found then return query select v_existing.id, v_existing.status, true; return; end if;
  if exists(select 1 from public.comun_territorial_need_interests where need_id=p_need_id and member_user_id=p_member_user_id and status='rejected' and rejected_at>=v_now-interval '24 hours') then raise exception 'COMUN_SOLIDARITY_CONNECTION_COOLDOWN'; end if;
  if (select count(*) from (
    select id from private.comun_solidarity_offer_interests where member_user_id=p_member_user_id and state='pending'
    union all select id from public.comun_territorial_need_interests where member_user_id=p_member_user_id and status='pending'
  ) pending) >= 10 then raise exception 'COMUN_SOLIDARITY_CONNECTION_PENDING_LIMIT'; end if;
  select count(*) into v_recent_count from (
    select id from private.comun_solidarity_offer_interests where member_user_id=p_member_user_id and created_at>=v_now-interval '24 hours'
    union all select id from public.comun_territorial_need_interests where member_user_id=p_member_user_id and created_at>=v_now-interval '24 hours'
  ) recent;
  if v_recent_count>=20 then raise exception 'COMUN_SOLIDARITY_CONNECTION_DAILY_LIMIT'; end if;
  select * into v_need from public.comun_territorial_needs where id=p_need_id;
  if not found or v_need.visibility<>'public' or v_need.status not in ('open','partially_met') or v_need.organization_territory_id is null then raise exception 'COMUN_SOLIDARITY_CONNECTION_SUBJECT_UNAVAILABLE'; end if;
  if not exists(
    select 1 from public.comun_territorial_organizations organization join public.comun_hub_territories territory on territory.id=organization.territory_id
    where organization.territory_id=v_need.organization_territory_id and organization.status in ('active','forming') and organization.verification_status in ('source_checked','verified')
      and territory.visibility='public' and territory.status in ('active','monitoring') and territory.verification_status in ('source_checked','verified')
  ) then raise exception 'COMUN_SOLIDARITY_CONNECTION_ORGANIZATION_INELIGIBLE'; end if;
  insert into public.comun_territorial_need_interests(need_id,public_alias,contact_private,offer_private,consent_to_contact,status,member_user_id,create_request_id,consent_version,consented_at)
    values(p_need_id,null,p_contact_private,p_message_private,true,'pending',p_member_user_id,p_request_id,p_consent_version,v_now)
    returning * into v_existing;
  return query select v_existing.id,v_existing.status,false;
end;
$$;


ALTER FUNCTION public.comun_create_solidarity_need_interest_v1(p_request_id uuid, p_need_id uuid, p_member_user_id uuid, p_message_private text, p_contact_private text, p_consent_version text, p_consent_to_contact boolean) OWNER TO postgres;

--
-- Name: comun_create_solidarity_offer_by_access_v1(uuid, uuid, uuid, text, text, text, text[], text, bigint, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_solidarity_offer_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_slug_base text, p_title text, p_public_summary text, p_modalities text[], p_offer_kind text DEFAULT 'other'::text, p_price_amount_cents bigint DEFAULT NULL::bigint, p_price_note_public text DEFAULT NULL::text, p_availability_public text DEFAULT NULL::text, p_validity_days integer DEFAULT 30) RETURNS TABLE(subject_id uuid, subject_slug text, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event private.comun_solidarity_economic_content_events%rowtype;
  v_access_id uuid;
  v_subject_id uuid;
  v_slug text;
  v_now timestamptz := clock_timestamp();
  v_modalities text[];
begin
  if p_request_id is null then raise exception 'COMUN_SOLIDARITY_ECONOMIC_REQUEST_ID_REQUIRED'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-economic-request:' || p_request_id::text, 0));
  select event.* into v_event from private.comun_solidarity_economic_content_events event where event.request_id = p_request_id;
  if found then
    if v_event.actor_member_user_id <> p_actor_user_id
      or v_event.organization_territory_id <> p_organization_territory_id
      or v_event.operation <> 'offer.create' then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_IDEMPOTENCY_CONFLICT';
    end if;
    select offer.slug, offer.status into v_slug, state
      from public.comun_solidarity_offers offer where offer.id = v_event.subject_id;
    return query select v_event.subject_id, v_slug, state, true;
    return;
  end if;

  v_access_id := private.comun_require_solidarity_economic_access(p_organization_territory_id, p_actor_user_id);
  if (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id
        and event.operation in ('offer.create','need.create')
        and event.occurred_at >= v_now - interval '24 hours') >= 20 then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_CREATE_RATE_LIMIT';
  end if;

  p_title := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_title, ''), '[[:space:]]+', ' ', 'g'));
  p_public_summary := pg_catalog.btrim(coalesce(p_public_summary, ''));
  p_price_note_public := nullif(pg_catalog.btrim(coalesce(p_price_note_public, '')), '');
  p_availability_public := nullif(pg_catalog.btrim(coalesce(p_availability_public, '')), '');
  p_offer_kind := coalesce(nullif(p_offer_kind, ''), 'other');
  select pg_catalog.array_agg(distinct modality order by modality) into v_modalities
    from pg_catalog.unnest(coalesce(p_modalities, array[]::text[])) modality;
  if pg_catalog.char_length(p_title) not between 3 and 140
    or pg_catalog.char_length(p_public_summary) not between 10 and 1200
    or p_offer_kind not in ('good','service','resource','space','skill','support','other')
    or pg_catalog.cardinality(coalesce(v_modalities, array[]::text[])) not between 1 and 8
    or not coalesce(v_modalities, array[]::text[]) <@ array['sale','exchange','donation','loan','cession','mutual_aid','cooperation','other']::text[]
    or (p_price_amount_cents is not null and p_price_amount_cents not between 1 and 9007199254740991)
    or (p_price_note_public is not null and pg_catalog.char_length(p_price_note_public) > 300)
    or (p_availability_public is not null and pg_catalog.char_length(p_availability_public) > 500)
    or p_validity_days not between 1 and 180 then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_INVALID';
  end if;
  if not private.comun_solidarity_economic_content_is_safe(
    p_title || E'\n' || p_public_summary || E'\n' || coalesce(p_price_note_public, '') || E'\n' || coalesce(p_availability_public, '')
  ) then raise exception 'COMUN_SOLIDARITY_ECONOMIC_CONTENT_BLOCKED'; end if;

  p_slug_base := pg_catalog.lower(pg_catalog.regexp_replace(coalesce(p_slug_base, ''), '[^a-z0-9]+', '-', 'g'));
  p_slug_base := pg_catalog.btrim(pg_catalog.left(p_slug_base, 72), '-');
  if pg_catalog.char_length(p_slug_base) < 3 then p_slug_base := 'oferta-solidaria'; end if;
  v_slug := p_slug_base;
  if exists(select 1 from public.comun_solidarity_offers offer where offer.slug = v_slug) then
    v_slug := pg_catalog.left(p_slug_base, 62) || '-' || pg_catalog.left(pg_catalog.replace(gen_random_uuid()::text, '-', ''), 8);
  end if;

  insert into public.comun_solidarity_offers(
    slug, organization_territory_id, title, public_summary, offer_kind, modalities,
    price_amount_cents, price_currency, price_note_public, availability_public,
    status, reviewed_at, published_at, valid_until
  ) values (
    v_slug, p_organization_territory_id, p_title, p_public_summary, p_offer_kind, v_modalities,
    p_price_amount_cents, case when p_price_amount_cents is null then null else 'BRL' end,
    p_price_note_public, p_availability_public, 'published', v_now, v_now,
    v_now + pg_catalog.make_interval(days => p_validity_days)
  ) returning id into v_subject_id;

  insert into private.comun_solidarity_economic_content_events(
    request_id, organization_territory_id, actor_access_id, actor_member_user_id,
    subject_type, subject_id, operation, from_state, to_state, occurred_at
  ) values (p_request_id, p_organization_territory_id, v_access_id, p_actor_user_id,
    'offer', v_subject_id, 'offer.create', null, 'published', v_now);
  return query select v_subject_id, v_slug, 'published'::text, false;
end;
$$;


ALTER FUNCTION public.comun_create_solidarity_offer_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_slug_base text, p_title text, p_public_summary text, p_modalities text[], p_offer_kind text, p_price_amount_cents bigint, p_price_note_public text, p_availability_public text, p_validity_days integer) OWNER TO postgres;

--
-- Name: comun_create_solidarity_offer_interest_v1(uuid, uuid, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_solidarity_offer_interest_v1(p_request_id uuid, p_offer_id uuid, p_member_user_id uuid, p_message_private text, p_contact_private text, p_consent_version text, p_consent_to_contact boolean) RETURNS TABLE(interest_id uuid, connection_state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_existing private.comun_solidarity_offer_interests%rowtype;
  v_offer public.comun_solidarity_offers%rowtype;
  v_now timestamptz := clock_timestamp();
  v_recent_count integer;
begin
  if p_request_id is null or p_offer_id is null or p_member_user_id is null
    or not exists(select 1 from auth.users where id = p_member_user_id) then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_REQUEST_INVALID';
  end if;
  p_message_private := btrim(coalesce(p_message_private, ''));
  p_contact_private := btrim(coalesce(p_contact_private, ''));
  if char_length(p_message_private) not between 10 and 600 then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_MESSAGE_INVALID';
  end if;
  if p_consent_to_contact is not true or p_consent_version <> 'comun.solidarity-contact-consent.v1'
    or char_length(p_contact_private) not between 3 and 200 then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_CONSENT_INVALID';
  end if;

  select * into v_existing from private.comun_solidarity_offer_interests where create_request_id = p_request_id;
  if found then
    if v_existing.offer_id <> p_offer_id or v_existing.member_user_id <> p_member_user_id then
      raise exception 'COMUN_SOLIDARITY_CONNECTION_IDEMPOTENCY_CONFLICT';
    end if;
    return query select v_existing.id, v_existing.state, true;
    return;
  end if;
  select * into v_existing from private.comun_solidarity_offer_interests
    where offer_id = p_offer_id and member_user_id = p_member_user_id and state in ('pending','accepted')
    order by created_at desc limit 1;
  if found then
    return query select v_existing.id, v_existing.state, true;
    return;
  end if;
  if exists(select 1 from private.comun_solidarity_offer_interests where offer_id=p_offer_id and member_user_id=p_member_user_id and state='rejected' and rejected_at >= v_now-interval '24 hours') then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_COOLDOWN';
  end if;
  if (select count(*) from (
    select id from private.comun_solidarity_offer_interests where member_user_id=p_member_user_id and state='pending'
    union all select id from public.comun_territorial_need_interests where member_user_id=p_member_user_id and status='pending'
  ) pending) >= 10 then raise exception 'COMUN_SOLIDARITY_CONNECTION_PENDING_LIMIT'; end if;
  select count(*) into v_recent_count from (
    select id from private.comun_solidarity_offer_interests where member_user_id=p_member_user_id and created_at >= v_now-interval '24 hours'
    union all select id from public.comun_territorial_need_interests where member_user_id=p_member_user_id and created_at >= v_now-interval '24 hours'
  ) recent;
  if v_recent_count >= 20 then raise exception 'COMUN_SOLIDARITY_CONNECTION_DAILY_LIMIT'; end if;

  select * into v_offer from public.comun_solidarity_offers where id=p_offer_id;
  if not found or v_offer.status <> 'published' or v_offer.reviewed_at is null or v_offer.published_at is null or v_offer.valid_until <= v_now then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_SUBJECT_UNAVAILABLE';
  end if;
  if not exists(
    select 1 from public.comun_territorial_organizations organization
    join public.comun_hub_territories territory on territory.id=organization.territory_id
    where organization.territory_id=v_offer.organization_territory_id
      and organization.status in ('active','forming') and organization.verification_status in ('source_checked','verified')
      and territory.visibility='public' and territory.status in ('active','monitoring') and territory.verification_status in ('source_checked','verified')
  ) then raise exception 'COMUN_SOLIDARITY_CONNECTION_ORGANIZATION_INELIGIBLE'; end if;

  insert into private.comun_solidarity_offer_interests(
    offer_id,organization_territory_id,member_user_id,create_request_id,message_private,contact_private,
    consent_to_contact,consent_version,consented_at,state
  ) values(
    p_offer_id,v_offer.organization_territory_id,p_member_user_id,p_request_id,p_message_private,p_contact_private,
    true,p_consent_version,v_now,'pending'
  ) returning * into v_existing;
  return query select v_existing.id, v_existing.state, false;
end;
$$;


ALTER FUNCTION public.comun_create_solidarity_offer_interest_v1(p_request_id uuid, p_offer_id uuid, p_member_user_id uuid, p_message_private text, p_contact_private text, p_consent_version text, p_consent_to_contact boolean) OWNER TO postgres;

--
-- Name: comun_create_solidarity_organization_onboarding_draft_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_create_solidarity_organization_onboarding_draft_v1(p_request_id uuid, p_applicant_user_id uuid, p_organization_name_candidate text) RETURNS TABLE(onboarding_id uuid, continuation_token uuid, state text, idempotent boolean, existing_organization_territory_id uuid, existing_organization_slug text, existing_organization_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_existing private.comun_solidarity_organization_onboarding%rowtype;
  v_normalized_name text;
  v_name text;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_request_id is null then raise exception 'COMUN_SOLIDARITY_ONBOARDING_REQUEST_ID_REQUIRED'; end if;
  if p_applicant_user_id is null or not exists(select 1 from auth.users u where u.id = p_applicant_user_id) then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_AUTH_REQUIRED';
  end if;
  v_name := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_organization_name_candidate, ''), '[[:space:]]+', ' ', 'g'));
  if pg_catalog.char_length(v_name) not between 3 and 160 then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NAME_INVALID';
  end if;
  v_normalized_name := private.comun_normalize_solidarity_organization_name(v_name);

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-solidarity-onboarding-request:' || p_request_id::text, 0));
  select onboarding.* into v_existing
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.create_request_id = p_request_id;
  if found then
    if v_existing.applicant_user_id <> p_applicant_user_id
      or v_existing.normalized_name_candidate <> v_normalized_name then
      raise exception 'COMUN_SOLIDARITY_ONBOARDING_IDEMPOTENCY_CONFLICT';
    end if;
    return query select v_existing.id, v_existing.continuation_token, v_existing.state, true,
      null::uuid, null::text, null::text;
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-solidarity-name:' || v_normalized_name, 0));
  return query
  select null::uuid, null::uuid, 'existing_organization'::text, true,
    organization.territory_id, territory.slug, organization.public_name
  from public.comun_territorial_organizations organization
  join public.comun_hub_territories territory on territory.id = organization.territory_id
  where private.comun_normalize_solidarity_organization_name(organization.public_name) = v_normalized_name
    and organization.status in ('active','forming')
    and organization.verification_status in ('source_checked','verified')
    and territory.visibility = 'public'
    and territory.status in ('active','monitoring')
    and territory.verification_status in ('source_checked','verified')
  order by organization.updated_at desc
  limit 1;
  if found then return; end if;

  if (select pg_catalog.count(*) from private.comun_solidarity_organization_onboarding onboarding
      where onboarding.applicant_user_id = p_applicant_user_id
        and onboarding.state in ('draft','submitted','needs_changes')) >= 5 then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_ACTIVE_LIMIT';
  end if;
  if (select pg_catalog.count(*) from private.comun_solidarity_organization_onboarding onboarding
      where onboarding.applicant_user_id = p_applicant_user_id
        and onboarding.created_at >= v_now - interval '24 hours') >= 10 then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_RATE_LIMIT';
  end if;

  insert into private.comun_solidarity_organization_onboarding as created_onboarding(
    create_request_id, applicant_user_id, organization_name_candidate,
    normalized_name_candidate, transition_history_private
  ) values (
    p_request_id, p_applicant_user_id, v_name, v_normalized_name,
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'event', 'draft_saved', 'actorUserId', p_applicant_user_id, 'at', v_now
    ))
  ) returning created_onboarding.id, created_onboarding.continuation_token
    into onboarding_id, continuation_token;
  state := 'draft';
  idempotent := false;
  existing_organization_territory_id := null;
  existing_organization_slug := null;
  existing_organization_name := null;
  return next;
end;
$$;


ALTER FUNCTION public.comun_create_solidarity_organization_onboarding_draft_v1(p_request_id uuid, p_applicant_user_id uuid, p_organization_name_candidate text) OWNER TO postgres;

