--
-- Name: comun_govern_solidarity_organization_access(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_govern_solidarity_organization_access(p_access_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_action text, p_review_note_private text DEFAULT NULL::text) RETURNS TABLE(access_id uuid, organization_territory_id uuid, state text, role text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_target private.comun_solidarity_organization_access%rowtype;
  v_now timestamptz := clock_timestamp();
  v_platform_actor boolean := false;
  v_facilitator_actor boolean := false;
begin
  if p_action not in ('promote','revoke') then
    raise exception 'COMUN_SOLIDARITY_ACCESS_GOVERNANCE_ACTION_INVALID';
  end if;
  p_review_note_private := nullif(btrim(coalesce(p_review_note_private, '')), '');
  if p_review_note_private is not null and char_length(p_review_note_private) > 600 then
    raise exception 'COMUN_SOLIDARITY_ACCESS_REVIEW_NOTE_INVALID';
  end if;

  select access.* into v_target
  from private.comun_solidarity_organization_access access
  where access.id = p_access_id
  for update;
  if not found or v_target.state <> 'active' then
    raise exception 'COMUN_SOLIDARITY_ACCESS_TARGET_NOT_ACTIVE';
  end if;
  if v_target.organization_territory_id <> p_expected_organization_territory_id then
    raise exception 'COMUN_SOLIDARITY_ACCESS_ORGANIZATION_MISMATCH';
  end if;

  select exists(
    select 1 from public.comun_admin_users admin_user
    where admin_user.user_id = p_actor_user_id
      and admin_user.is_active = true
      and admin_user.role in ('admin','editor')
  ) into v_platform_actor;
  select exists(
    select 1 from private.comun_solidarity_organization_access actor_access
    where actor_access.organization_territory_id = v_target.organization_territory_id
      and actor_access.member_user_id = p_actor_user_id
      and actor_access.state = 'active'
      and actor_access.role = 'facilitator'
  ) into v_facilitator_actor;

  if p_action = 'promote' then
    if not v_facilitator_actor or v_target.role <> 'editor' or v_target.member_user_id = p_actor_user_id then
      raise exception 'COMUN_SOLIDARITY_ACCESS_PROMOTION_FORBIDDEN';
    end if;
    update private.comun_solidarity_organization_access access
    set role = 'facilitator',
        reviewed_by_user_id = p_actor_user_id,
        reviewed_at = v_now,
        review_note_private = p_review_note_private,
        transition_history_private = access.transition_history_private || jsonb_build_array(jsonb_build_object(
          'event', 'promoted_to_facilitator', 'actorUserId', p_actor_user_id, 'at', v_now
        ))
    where access.id = p_access_id;
  else
    if not v_platform_actor and (
      not v_facilitator_actor or v_target.role <> 'editor' or v_target.member_user_id = p_actor_user_id
    ) then
      raise exception 'COMUN_SOLIDARITY_ACCESS_REVOCATION_FORBIDDEN';
    end if;
    update private.comun_solidarity_organization_access access
    set state = 'revoked',
        revoked_at = v_now,
        reviewed_by_user_id = p_actor_user_id,
        reviewed_at = v_now,
        review_note_private = p_review_note_private,
        transition_history_private = access.transition_history_private || jsonb_build_array(jsonb_build_object(
          'event', 'revoked', 'actorUserId', p_actor_user_id, 'at', v_now
        ))
    where access.id = p_access_id;
  end if;

  select access.id, access.organization_territory_id, access.state, access.role
  into access_id, organization_territory_id, state, role
  from private.comun_solidarity_organization_access access where access.id = p_access_id;
  return next;
end;
$$;


ALTER FUNCTION public.comun_govern_solidarity_organization_access(p_access_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_action text, p_review_note_private text) OWNER TO postgres;

--
-- Name: comun_guard_artwork_submission_private_root_provenance_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_guard_artwork_submission_private_root_provenance_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE'
    and old.archive_item_id is not null
    and new.archive_item_id is distinct from old.archive_item_id then
    raise exception 'artwork submission private-root provenance is immutable'
      using errcode = '23514';
  end if;

  if new.archive_item_id is null then
    return new;
  end if;

  if not exists (
    select 1
      from public.comun_archive_items item
      join public.comun_archive_artworks artwork
        on artwork.archive_item_id = item.id
      where item.id = new.archive_item_id
        and item.item_type = 'territorial_artwork'
        and item.status = 'draft'
        and item.visibility = 'private'
  ) then
    raise exception 'artwork submission requires a territorial-artwork private root'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.comun_guard_artwork_submission_private_root_provenance_v1() OWNER TO postgres;

--
-- Name: comun_guard_circle_contribution_round(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_guard_circle_contribution_round() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  round_circle_id uuid;
  round_status text;
begin
  select circle_id, status into round_circle_id, round_status
  from public.comun_construction_circle_rounds
  where id = new.round_id;
  if round_circle_id is null or round_circle_id <> new.circle_id then
    raise exception 'round_id must belong to circle_id';
  end if;
  if round_status <> 'open' then
    raise exception 'contributions require an open round';
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.comun_guard_circle_contribution_round() OWNER TO postgres;

