--
-- Name: comun_link_radio_contribution_private_root_v1(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_link_radio_contribution_private_root_v1(p_contribution_id uuid, p_private_root_kind text, p_private_root_archive_item_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_contribution public.comun_radio_contributions%rowtype;
begin
  if p_private_root_kind not in ('program', 'episode') or p_private_root_archive_item_id is null then
    raise exception 'radio private-root kind and target are required'
      using errcode = '22023';
  end if;

  select * into v_contribution
    from public.comun_radio_contributions
    where id = p_contribution_id
    for update;

  if not found then
    raise exception 'radio contribution not found' using errcode = 'P0002';
  end if;
  if v_contribution.status in ('rejected', 'published', 'withdrawn', 'archived') then
    raise exception 'radio contribution cannot be linked from its current status'
      using errcode = '23514';
  end if;
  if v_contribution.private_root_archive_item_id is not null then
    if v_contribution.private_root_kind = p_private_root_kind
      and v_contribution.private_root_archive_item_id = p_private_root_archive_item_id then
      return v_contribution.private_root_archive_item_id;
    end if;
    raise exception 'radio contribution already has immutable private-root provenance'
      using errcode = '23514';
  end if;

  if (v_contribution.contribution_type = 'program_proposal' and p_private_root_kind <> 'program')
    or (v_contribution.contribution_type in ('community_audio', 'authorized_testimony') and p_private_root_kind <> 'episode')
    or v_contribution.contribution_type in ('pauta_proposal', 'own_music', 'agenda') then
    raise exception 'radio contribution type requires an explicit specialized editorial route'
      using errcode = '23514';
  end if;

  update public.comun_radio_contributions
    set private_root_kind = p_private_root_kind,
        private_root_archive_item_id = p_private_root_archive_item_id,
        updated_at = now()
    where id = v_contribution.id;
  return p_private_root_archive_item_id;
end;
$$;


ALTER FUNCTION public.comun_link_radio_contribution_private_root_v1(p_contribution_id uuid, p_private_root_kind text, p_private_root_archive_item_id uuid) OWNER TO postgres;

--
-- Name: comun_list_my_solidarity_connections_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_list_my_solidarity_connections_v1(p_member_user_id uuid) RETURNS TABLE(interest_id uuid, subject_kind text, subject_id uuid, subject_slug text, subject_title text, organization_slug text, organization_name text, connection_state text, created_at timestamp with time zone, updated_at timestamp with time zone, reviewed_at timestamp with time zone, accepted_at timestamp with time zone, withdrawn_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select * from (
    select interest.id,'offer',offer.id,offer.slug,offer.title,territory.slug,organization.public_name,interest.state,interest.created_at,interest.updated_at,interest.reviewed_at,interest.accepted_at,interest.withdrawn_at
    from private.comun_solidarity_offer_interests interest join public.comun_solidarity_offers offer on offer.id=interest.offer_id
    join public.comun_territorial_organizations organization on organization.territory_id=interest.organization_territory_id join public.comun_hub_territories territory on territory.id=organization.territory_id
    where interest.member_user_id=p_member_user_id
    union all
    select interest.id,'need',need.id,need.slug,need.title,territory.slug,organization.public_name,interest.status,interest.created_at,interest.updated_at,interest.reviewed_at,interest.accepted_at,interest.withdrawn_at
    from public.comun_territorial_need_interests interest join public.comun_territorial_needs need on need.id=interest.need_id
    join public.comun_territorial_organizations organization on organization.territory_id=need.organization_territory_id join public.comun_hub_territories territory on territory.id=organization.territory_id
    where interest.member_user_id=p_member_user_id
  ) connection
  order by connection.updated_at desc limit 100
$$;


ALTER FUNCTION public.comun_list_my_solidarity_connections_v1(p_member_user_id uuid) OWNER TO postgres;

