--
-- Name: comun_list_platform_solidarity_organization_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_list_platform_solidarity_organization_access(p_actor_user_id uuid) RETURNS TABLE(access_id uuid, organization_territory_id uuid, organization_name text, member_label text, request_note_private text, requested_role text, role text, state text, review_scope text, requested_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if not exists (
    select 1 from public.comun_admin_users admin_user
    where admin_user.user_id = p_actor_user_id
      and admin_user.is_active = true
      and admin_user.role in ('admin','editor')
  ) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_PLATFORM_QUEUE_FORBIDDEN';
  end if;
  return query
  select access.id, access.organization_territory_id, organization.public_name,
    case when profile.status = 'active' and char_length(btrim(profile.display_name)) between 1 and 80
      then btrim(profile.display_name) else 'Pessoa autenticada' end,
    access.request_note_private, access.requested_role, access.role, access.state, access.review_scope,
    access.requested_at
  from private.comun_solidarity_organization_access access
  join public.comun_territorial_organizations organization
    on organization.territory_id = access.organization_territory_id
  left join public.comun_member_profiles profile on profile.user_id = access.member_user_id
  where (access.state = 'pending' and access.review_scope = 'platform') or access.state = 'active'
  order by case when access.state = 'pending' then 0 else 1 end, access.requested_at
  limit 100;
end;
$$;


ALTER FUNCTION public.comun_list_platform_solidarity_organization_access(p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: comun_list_solidarity_organization_connections_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_list_solidarity_organization_connections_v1(p_organization_territory_id uuid, p_actor_user_id uuid) RETURNS TABLE(interest_id uuid, subject_kind text, subject_id uuid, subject_slug text, subject_title text, member_label text, message_private text, contact_private text, connection_state text, subject_is_public boolean, created_at timestamp with time zone, updated_at timestamp with time zone, reviewed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if not exists(select 1 from private.comun_solidarity_organization_access where organization_territory_id=p_organization_territory_id and member_user_id=p_actor_user_id and state='active' and role in ('editor','facilitator')) then
    raise exception 'COMUN_SOLIDARITY_CONNECTION_READ_FORBIDDEN';
  end if;
  return query select connection.* from (
    select interest.id,'offer',offer.id,offer.slug,offer.title,
      case when profile.status='active' and char_length(btrim(profile.display_name)) between 1 and 80 then btrim(profile.display_name) else 'Pessoa autenticada' end,
      interest.message_private,case when interest.state='accepted' then interest.contact_private else null end,interest.state,
      (offer.status='published' and offer.valid_until>now()),interest.created_at,interest.updated_at,interest.reviewed_at
    from private.comun_solidarity_offer_interests interest join public.comun_solidarity_offers offer on offer.id=interest.offer_id
    left join public.comun_member_profiles profile on profile.user_id=interest.member_user_id
    where interest.organization_territory_id=p_organization_territory_id and interest.state in ('pending','accepted')
    union all
    select interest.id,'need',need.id,need.slug,need.title,
      case when profile.status='active' and char_length(btrim(profile.display_name)) between 1 and 80 then btrim(profile.display_name) else 'Pessoa autenticada' end,
      interest.offer_private,case when interest.status='accepted' then interest.contact_private else null end,interest.status,
      (need.visibility='public' and need.status in ('open','partially_met')),interest.created_at,interest.updated_at,interest.reviewed_at
    from public.comun_territorial_need_interests interest join public.comun_territorial_needs need on need.id=interest.need_id
    left join public.comun_member_profiles profile on profile.user_id=interest.member_user_id
    where need.organization_territory_id=p_organization_territory_id and interest.member_user_id is not null and interest.status in ('pending','contacted','accepted')
  ) connection
  order by connection.created_at desc limit 100;
end;
$$;


ALTER FUNCTION public.comun_list_solidarity_organization_connections_v1(p_organization_territory_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: comun_list_solidarity_organization_governance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_list_solidarity_organization_governance(p_organization_territory_id uuid, p_actor_user_id uuid) RETURNS TABLE(access_id uuid, member_label text, request_note_private text, requested_role text, role text, state text, review_scope text, requested_at timestamp with time zone, activated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if not exists (
    select 1 from private.comun_solidarity_organization_access actor_access
    where actor_access.organization_territory_id = p_organization_territory_id
      and actor_access.member_user_id = p_actor_user_id
      and actor_access.state = 'active'
      and actor_access.role = 'facilitator'
  ) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_GOVERNANCE_FORBIDDEN';
  end if;
  return query
  select access.id,
    case when profile.status = 'active' and char_length(btrim(profile.display_name)) between 1 and 80
      then btrim(profile.display_name) else 'Pessoa autenticada' end,
    access.request_note_private, access.requested_role, access.role, access.state, access.review_scope,
    access.requested_at, access.activated_at
  from private.comun_solidarity_organization_access access
  left join public.comun_member_profiles profile on profile.user_id = access.member_user_id
  where access.organization_territory_id = p_organization_territory_id
    and (access.state = 'active' or (access.state = 'pending' and access.review_scope = 'organization'))
  order by case when access.state = 'pending' then 0 else 1 end, access.requested_at;
end;
$$;


ALTER FUNCTION public.comun_list_solidarity_organization_governance(p_organization_territory_id uuid, p_actor_user_id uuid) OWNER TO postgres;

