end;
$_$;


ALTER FUNCTION public.comun_materialize_oral_history_suggestion_private_root_v1(p_suggestion_id uuid, p_title text, p_slug text) OWNER TO postgres;

--
-- Name: comun_materialize_radio_contribution_private_root_v1(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_materialize_radio_contribution_private_root_v1(p_contribution_id uuid, p_private_root_kind text, p_title text, p_slug text, p_program_item_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_contribution public.comun_radio_contributions%rowtype;
  v_item_id uuid;
begin
  if btrim(coalesce(p_title, '')) = '' or p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    raise exception 'radio private root requires title and canonical slug'
      using errcode = '22023';
  end if;

  select * into v_contribution
    from public.comun_radio_contributions
    where id = p_contribution_id
    for update;

  if not found then
    raise exception 'radio contribution not found' using errcode = 'P0002';
  end if;
  if v_contribution.status in ('rejected', 'published', 'withdrawn', 'archived') then
    raise exception 'radio contribution cannot be materialized from its current status'
      using errcode = '23514';
  end if;
  if v_contribution.private_root_archive_item_id is not null then
    if v_contribution.private_root_kind = p_private_root_kind then
      return v_contribution.private_root_archive_item_id;
    end if;
    raise exception 'radio contribution already has immutable private-root provenance'
      using errcode = '23514';
  end if;

  if v_contribution.contribution_type = 'program_proposal' and p_private_root_kind = 'program' then
    insert into public.comun_archive_items(slug, item_type, title, rights_status, status, visibility, editorial_notes)
      values (p_slug, 'community_radio_program', p_title, 'unknown', 'draft', 'private',
        'Raiz privada materializada de proposta de programa; nenhuma grade, episódio ou publicação foi criada.')
      returning id into v_item_id;
    insert into public.comun_radio_programs(archive_item_id, title_public, slug_public, description_public, format_type)
      values (v_item_id, p_title, p_slug, v_contribution.context_suggestion, 'mixed');
  elsif v_contribution.contribution_type in ('community_audio', 'authorized_testimony')
    and p_private_root_kind = 'episode' then
    if p_program_item_id is null
      or not exists (
        select 1 from public.comun_radio_programs program
        join public.comun_archive_items item on item.id = program.archive_item_id
        where program.archive_item_id = p_program_item_id
          and item.item_type = 'community_radio_program'
      ) then
      raise exception 'radio episode private root requires an explicit canonical program'
        using errcode = '23514';
    end if;
    insert into public.comun_archive_items(slug, item_type, title, rights_status, status, visibility, editorial_notes)
      values (p_slug, 'community_radio_episode', p_title, 'unknown', 'draft', 'private',
        'Raiz privada materializada de contribuição de rádio; voz, música, safety e publicação permanecem separados.')
      returning id into v_item_id;
    insert into public.comun_radio_episodes(
      archive_item_id, program_item_id, title_public, slug_public, summary_public, publication_status, transcript_status
    ) values (
      v_item_id, p_program_item_id, p_title, p_slug, v_contribution.context_suggestion, 'draft', 'unavailable'
    );
  else
    raise exception 'radio contribution type and explicit destination do not permit private-root materialization'
      using errcode = '23514';
  end if;

  return public.comun_link_radio_contribution_private_root_v1(
    v_contribution.id, p_private_root_kind, v_item_id
  );
end;
$_$;


ALTER FUNCTION public.comun_materialize_radio_contribution_private_root_v1(p_contribution_id uuid, p_private_root_kind text, p_title text, p_slug text, p_program_item_id uuid) OWNER TO postgres;

--
-- Name: comun_mutate_solidarity_need_by_access_v1(uuid, uuid, uuid, uuid, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_mutate_solidarity_need_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_need_id uuid, p_operation text, p_title text DEFAULT NULL::text, p_public_summary text DEFAULT NULL::text, p_need_type text DEFAULT NULL::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(subject_id uuid, subject_slug text, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event private.comun_solidarity_economic_content_events%rowtype;
  v_access_id uuid;
  v_need public.comun_territorial_needs%rowtype;
  v_now timestamptz := clock_timestamp();
  v_operation text;
  v_to_state text;
begin
  if p_request_id is null or p_need_id is null then raise exception 'COMUN_SOLIDARITY_ECONOMIC_REQUEST_INVALID'; end if;
  v_operation := 'need.' || coalesce(p_operation, '');
  if v_operation not in ('need.edit','need.partially_met','need.met','need.cancel','need.reopen') then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_OPERATION_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-economic-request:' || p_request_id::text, 0));
  select event.* into v_event from private.comun_solidarity_economic_content_events event where event.request_id = p_request_id;
  if found then
    if v_event.actor_member_user_id <> p_actor_user_id or v_event.organization_territory_id <> p_organization_territory_id
      or v_event.operation <> v_operation or v_event.subject_id <> p_need_id then raise exception 'COMUN_SOLIDARITY_ECONOMIC_IDEMPOTENCY_CONFLICT'; end if;
    select need.slug, need.status into subject_slug, state from public.comun_territorial_needs need where need.id = p_need_id;
    return query select p_need_id, subject_slug, state, true;
    return;
  end if;
  v_access_id := private.comun_require_solidarity_economic_access(p_organization_territory_id, p_actor_user_id);
  if (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id and event.operation not in ('offer.create','need.create')
        and event.occurred_at >= v_now - interval '1 hour') >= 100 then raise exception 'COMUN_SOLIDARITY_ECONOMIC_MUTATION_RATE_LIMIT'; end if;
  select need.* into v_need from public.comun_territorial_needs need where need.id = p_need_id for update;
  if not found or v_need.organization_territory_id <> p_organization_territory_id then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_NOT_FOUND';
  end if;

  if p_operation = 'edit' then
    if v_need.status = 'archived' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_ARCHIVED'; end if;
    p_title := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_title, ''), '[[:space:]]+', ' ', 'g'));
    p_public_summary := pg_catalog.btrim(coalesce(p_public_summary, ''));
    p_need_type := coalesce(nullif(p_need_type, ''), 'other');
    if pg_catalog.char_length(p_title) not between 3 and 160 or pg_catalog.char_length(p_public_summary) not between 10 and 1200
      or p_need_type not in ('equipment','vehicle','space','input','training','technical_support','partnership','volunteering','donation','hiring','infrastructure','communication','other')
      or (p_due_at is not null and p_due_at <= v_now)
      or not private.comun_solidarity_economic_content_is_safe(p_title || E'\n' || p_public_summary) then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_INVALID';
    end if;
    update public.comun_territorial_needs need set title = p_title, public_summary = p_public_summary,
      need_type = p_need_type, due_at = p_due_at where need.id = p_need_id;
    v_to_state := v_need.status;
  elsif p_operation = 'partially_met' then
    if v_need.status <> 'open' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_TRANSITION_INVALID'; end if;
    update public.comun_territorial_needs need set status = 'partially_met' where need.id = p_need_id;
    v_to_state := 'partially_met';
  elsif p_operation = 'met' then
    if v_need.status not in ('open','partially_met') then raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_TRANSITION_INVALID'; end if;
    update public.comun_territorial_needs need set status = 'met' where need.id = p_need_id;
    v_to_state := 'met';
  elsif p_operation = 'cancel' then
    if v_need.status not in ('open','partially_met') then raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_TRANSITION_INVALID'; end if;
    update public.comun_territorial_needs need set status = 'cancelled' where need.id = p_need_id;
    v_to_state := 'cancelled';
  else
    if v_need.status not in ('met','cancelled') then raise exception 'COMUN_SOLIDARITY_ECONOMIC_NEED_TRANSITION_INVALID'; end if;
    update public.comun_territorial_needs need set status = 'open' where need.id = p_need_id;
    v_to_state := 'open';
  end if;

  insert into private.comun_solidarity_economic_content_events(
    request_id, organization_territory_id, actor_access_id, actor_member_user_id,
    subject_type, subject_id, operation, from_state, to_state, occurred_at
  ) values (p_request_id, p_organization_territory_id, v_access_id, p_actor_user_id,
    'need', p_need_id, v_operation, v_need.status, v_to_state, v_now);
  return query select p_need_id, v_need.slug, v_to_state, false;
end;
$$;


ALTER FUNCTION public.comun_mutate_solidarity_need_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_need_id uuid, p_operation text, p_title text, p_public_summary text, p_need_type text, p_due_at timestamp with time zone) OWNER TO postgres;

--
-- Name: comun_mutate_solidarity_offer_by_access_v1(uuid, uuid, uuid, uuid, text, text, text, text[], text, bigint, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_mutate_solidarity_offer_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_offer_id uuid, p_operation text, p_title text DEFAULT NULL::text, p_public_summary text DEFAULT NULL::text, p_modalities text[] DEFAULT NULL::text[], p_offer_kind text DEFAULT NULL::text, p_price_amount_cents bigint DEFAULT NULL::bigint, p_price_note_public text DEFAULT NULL::text, p_availability_public text DEFAULT NULL::text, p_validity_days integer DEFAULT NULL::integer) RETURNS TABLE(subject_id uuid, subject_slug text, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event private.comun_solidarity_economic_content_events%rowtype;
  v_access_id uuid;
  v_offer public.comun_solidarity_offers%rowtype;
  v_now timestamptz := clock_timestamp();
  v_modalities text[];
  v_operation text;
  v_to_state text;
begin
  if p_request_id is null or p_offer_id is null then raise exception 'COMUN_SOLIDARITY_ECONOMIC_REQUEST_INVALID'; end if;
  v_operation := 'offer.' || coalesce(p_operation, '');
  if v_operation not in ('offer.edit','offer.pause','offer.resume','offer.renew','offer.archive') then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_OPERATION_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('comun-economic-request:' || p_request_id::text, 0));
  select event.* into v_event from private.comun_solidarity_economic_content_events event where event.request_id = p_request_id;
  if found then
    if v_event.actor_member_user_id <> p_actor_user_id or v_event.organization_territory_id <> p_organization_territory_id
      or v_event.operation <> v_operation or v_event.subject_id <> p_offer_id then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_IDEMPOTENCY_CONFLICT';
    end if;
    select offer.slug, offer.status into subject_slug, state from public.comun_solidarity_offers offer where offer.id = p_offer_id;
    return query select p_offer_id, subject_slug, state, true;
    return;
  end if;

  v_access_id := private.comun_require_solidarity_economic_access(p_organization_territory_id, p_actor_user_id);
  if (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id and event.operation not in ('offer.create','need.create')
        and event.occurred_at >= v_now - interval '1 hour') >= 100 then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_MUTATION_RATE_LIMIT';
  end if;
  select offer.* into v_offer from public.comun_solidarity_offers offer where offer.id = p_offer_id for update;
  if not found or v_offer.organization_territory_id <> p_organization_territory_id then
    raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_NOT_FOUND';
  end if;

  if p_operation = 'edit' then
    if v_offer.status = 'archived' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_ARCHIVED'; end if;
    p_title := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_title, ''), '[[:space:]]+', ' ', 'g'));
    p_public_summary := pg_catalog.btrim(coalesce(p_public_summary, ''));
    p_price_note_public := nullif(pg_catalog.btrim(coalesce(p_price_note_public, '')), '');
    p_availability_public := nullif(pg_catalog.btrim(coalesce(p_availability_public, '')), '');
    p_offer_kind := coalesce(nullif(p_offer_kind, ''), 'other');
    select pg_catalog.array_agg(distinct modality order by modality) into v_modalities
      from pg_catalog.unnest(coalesce(p_modalities, array[]::text[])) modality;
    if pg_catalog.char_length(p_title) not between 3 and 140
      or pg_catalog.char_length(p_public_summary) not between 10 and 1200
      or p_offer_kind not in ('good','service','resource','space','skill','support','other')
      or pg_catalog.cardinality(coalesce(v_modalities, array[]::text[])) not between 1 and 8
      or not coalesce(v_modalities, array[]::text[]) <@ array['sale','exchange','donation','loan','cession','mutual_aid','cooperation','other']::text[]
      or (p_price_amount_cents is not null and p_price_amount_cents not between 1 and 9007199254740991)
      or (p_price_note_public is not null and pg_catalog.char_length(p_price_note_public) > 300)
      or (p_availability_public is not null and pg_catalog.char_length(p_availability_public) > 500)
      or not private.comun_solidarity_economic_content_is_safe(p_title || E'\n' || p_public_summary || E'\n' || coalesce(p_price_note_public, '') || E'\n' || coalesce(p_availability_public, '')) then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_INVALID';
    end if;
    update public.comun_solidarity_offers offer set title = p_title, public_summary = p_public_summary,
      offer_kind = p_offer_kind, modalities = v_modalities, price_amount_cents = p_price_amount_cents,
      price_currency = case when p_price_amount_cents is null then null else 'BRL' end,
      price_note_public = p_price_note_public, availability_public = p_availability_public, reviewed_at = v_now
      where offer.id = p_offer_id;
    v_to_state := v_offer.status;
  elsif p_operation = 'pause' then
    if v_offer.status <> 'published' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_TRANSITION_INVALID'; end if;
    update public.comun_solidarity_offers offer set status = 'paused' where offer.id = p_offer_id;
    v_to_state := 'paused';
  elsif p_operation = 'resume' then
    if v_offer.status <> 'paused' or v_offer.valid_until <= v_now
      or not private.comun_solidarity_economic_content_is_safe(v_offer.title || E'\n' || v_offer.public_summary || E'\n' || coalesce(v_offer.price_note_public, '') || E'\n' || coalesce(v_offer.availability_public, '')) then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_TRANSITION_INVALID';
    end if;
    update public.comun_solidarity_offers offer set status = 'published', reviewed_at = v_now where offer.id = p_offer_id;
    v_to_state := 'published';
  elsif p_operation = 'renew' then
    if v_offer.status = 'archived' or coalesce(p_validity_days, 30) not between 1 and 180
      or not private.comun_solidarity_economic_content_is_safe(v_offer.title || E'\n' || v_offer.public_summary || E'\n' || coalesce(v_offer.price_note_public, '') || E'\n' || coalesce(v_offer.availability_public, '')) then
      raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_TRANSITION_INVALID';
    end if;
    update public.comun_solidarity_offers offer set status = 'published', reviewed_at = v_now,
      published_at = coalesce(offer.published_at, v_now), valid_until = v_now + pg_catalog.make_interval(days => coalesce(p_validity_days, 30))
      where offer.id = p_offer_id;
    v_to_state := 'published';
  else
    if v_offer.status = 'archived' then raise exception 'COMUN_SOLIDARITY_ECONOMIC_OFFER_TRANSITION_INVALID'; end if;
    update public.comun_solidarity_offers offer set status = 'archived' where offer.id = p_offer_id;
    v_to_state := 'archived';
  end if;

  insert into private.comun_solidarity_economic_content_events(
    request_id, organization_territory_id, actor_access_id, actor_member_user_id,
    subject_type, subject_id, operation, from_state, to_state, occurred_at
  ) values (p_request_id, p_organization_territory_id, v_access_id, p_actor_user_id,
    'offer', p_offer_id, v_operation, v_offer.status, v_to_state, v_now);
  return query select p_offer_id, v_offer.slug, v_to_state, false;
end;
$$;


ALTER FUNCTION public.comun_mutate_solidarity_offer_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_offer_id uuid, p_operation text, p_title text, p_public_summary text, p_modalities text[], p_offer_kind text, p_price_amount_cents bigint, p_price_note_public text, p_availability_public text, p_validity_days integer) OWNER TO postgres;

--
-- Name: comun_participation_wallet_attach_relata(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_attach_relata(p_token_hash_hex text, p_protocol text, p_receipt_secret text) RETURNS TABLE(item_id uuid, recovery_needed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  w uuid;
  c public.comun_relata_cases%rowtype;
  r private.comun_relata_reports%rowtype;
  i uuid;
  safe_metadata jsonb := '{}'::jsonb;
  education_issue_type text;
begin
  select id into w from private.comun_participation_wallets
    where token_hash=decode(p_token_hash_hex,'hex') and status='active';
  select * into c from public.comun_relata_cases where protocol=p_protocol;
  select * into r from private.comun_relata_reports
    where id=c.report_id
      and receipt_hash=extensions.digest('relata-receipt-v1:'||p_receipt_secret,'sha256');
  if w is null or c.id is null or r.id is null then return; end if;

  if c.category='public_education'
    and c.routing_decision->>'routingVersion'='comun-education-service-routing-v1'
  then
    education_issue_type := nullif(c.routing_decision->>'educationIssueType','');
    if education_issue_type in (
      'staff_or_service_availability','infrastructure_or_climate','school_meals_or_supplies',
      'school_transport_or_access','accessibility_or_inclusion','enrollment_or_attendance',
      'discrimination_or_bullying','information_or_management','other_education_service'
    ) then
      safe_metadata := jsonb_build_object(
        'educationIssueType',education_issue_type,
        'childSafetySignal',coalesce((c.routing_decision->>'childSafetySignal')::boolean,false)
      );
    end if;
  elsif c.category='child_protection'
    and c.routing_decision->>'routingVersion'='comun-child-protection-routing-v1'
  then
    safe_metadata := jsonb_build_object(
      'immediateDanger',coalesce((c.routing_decision->>'immediateDanger')::boolean,false)
    );
  end if;

  insert into private.comun_participation_wallet_items(
    wallet_id,item_type,subject_ref,subject_hash,title_template,category,
    presentation_state,action_required,protocol_masked,source_domain,metadata
  ) values(
    w,'relata_report',c.id::text,
    extensions.digest('wallet-subject-v1:'||p_protocol,'sha256'),
    'Relato COMUN',c.category,
    case when c.category='child_protection' then 'Guardado com proteção reforçada' else 'Guardado' end,
    case when c.category='child_protection' then null else 'Precisa de informação' end,
    left(p_protocol,12)||'••••','relata',safe_metadata
  )
  on conflict(wallet_id,item_type,subject_hash) do update set
    archived_at=null,metadata=excluded.metadata,updated_at=now()
  returning id into i;
  insert into private.comun_participation_wallet_events(
    wallet_id,item_id,event_type,result_code
  ) values(w,i,'item_added','WALLET_RELATA_ATTACHED');
  return query select i,false;
end;
$$;


ALTER FUNCTION public.comun_participation_wallet_attach_relata(p_token_hash_hex text, p_protocol text, p_receipt_secret text) OWNER TO postgres;

--
-- Name: comun_participation_wallet_claim_bus(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_claim_bus(p_token_hash_hex text, p_observation_id text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(item_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare w uuid;i uuid; begin select id into w from private.comun_participation_wallets where token_hash=decode(p_token_hash_hex,'hex') and status='active'; if w is null then return; end if; insert into private.comun_participation_wallet_items(wallet_id,item_type,subject_ref,subject_hash,title_template,category,presentation_state,source_domain,metadata) values(w,'bus_observation',p_observation_id,extensions.digest('wallet-subject-v1:'||p_observation_id,'sha256'),'Observação de ônibus','public_transport','Observação registrada','onibus',coalesce(p_metadata,'{}'::jsonb)) on conflict(wallet_id,item_type,subject_hash) do update set archived_at=null,updated_at=now(),metadata=excluded.metadata returning id into i; return query select i; end; $$;


ALTER FUNCTION public.comun_participation_wallet_claim_bus(p_token_hash_hex text, p_observation_id text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: comun_participation_wallet_create(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_create(p_token_hash_hex text, p_recovery_hash_hex text) RETURNS TABLE(wallet_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$ declare w uuid; begin if p_token_hash_hex !~ '^[0-9a-f]{64}$' or p_recovery_hash_hex !~ '^[0-9a-f]{64}$' then return; end if; insert into private.comun_participation_wallets(token_hash) values(decode(p_token_hash_hex,'hex')) on conflict(token_hash) do update set rotated_at=private.comun_participation_wallets.rotated_at returning id into w; insert into private.comun_participation_wallet_recovery_credentials(wallet_id,recovery_hash) values(w,decode(p_recovery_hash_hex,'hex')) on conflict(recovery_hash) do nothing; return query select w; end; $_$;


ALTER FUNCTION public.comun_participation_wallet_create(p_token_hash_hex text, p_recovery_hash_hex text) OWNER TO postgres;

--
-- Name: comun_participation_wallet_follow_case(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_follow_case(p_token_hash_hex text, p_public_case_id text, p_category text DEFAULT NULL::text) RETURNS TABLE(item_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare w uuid;i uuid; begin select id into w from private.comun_participation_wallets where token_hash=decode(p_token_hash_hex,'hex') and status='active'; if w is null then return; end if; insert into private.comun_participation_wallet_items(wallet_id,item_type,subject_ref,subject_hash,title_template,category,presentation_state,source_domain) values(w,'collective_case_follow',p_public_case_id,extensions.digest('wallet-subject-v1:'||p_public_case_id,'sha256'),'Caso coletivo acompanhado',p_category,'Acompanhando','collective_case') on conflict(wallet_id,item_type,subject_hash) do update set archived_at=null,updated_at=now() returning id into i; return query select i; end; $$;


ALTER FUNCTION public.comun_participation_wallet_follow_case(p_token_hash_hex text, p_public_case_id text, p_category text) OWNER TO postgres;

