CREATE FUNCTION public.comun_participation_wallet_follow_legacy(p_token_hash_hex text, p_protocol text) RETURNS TABLE(item_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare w uuid;i uuid; begin select id into w from private.comun_participation_wallets where token_hash=decode(p_token_hash_hex,'hex') and status='active'; if w is null then return; end if; insert into private.comun_participation_wallet_items(wallet_id,item_type,subject_ref,subject_hash,title_template,presentation_state,protocol_masked,source_domain) values(w,'legacy_report_follow',p_protocol,extensions.digest('wallet-subject-v1:'||p_protocol,'sha256'),'Protocolo acompanhado','Acompanhando',left(p_protocol,12)||'••••','legacy') on conflict(wallet_id,item_type,subject_hash) do update set archived_at=null,updated_at=now() returning id into i; return query select i; end; $$;


ALTER FUNCTION public.comun_participation_wallet_follow_legacy(p_token_hash_hex text, p_protocol text) OWNER TO postgres;

--
-- Name: comun_participation_wallet_link_account(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_link_account(p_token_hash_hex text, p_user_id uuid, p_link_method text) RETURNS TABLE(wallet_id uuid, linked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_wallet_id uuid;
begin
  if p_link_method not in (
    'explicit_account_link',
    'recovery_claim'
  ) then
    return;
  end if;

  if p_user_id is null
    or p_token_hash_hex !~ '^[0-9a-f]{64}$'
  then
    return;
  end if;

  select wallets.id
    into v_wallet_id
    from private.comun_participation_wallets as wallets
    where wallets.token_hash = decode(p_token_hash_hex, 'hex')
      and wallets.status = 'active';

  if v_wallet_id is null then
    return;
  end if;

  insert into private.comun_participation_wallet_account_links as account_links (
    wallet_id,
    user_id,
    link_method
  )
  values (
    v_wallet_id,
    p_user_id,
    p_link_method
  )
  on conflict on constraint
    comun_participation_wallet_account_links_wallet_id_user_id_key
  do update set
    revoked_at = null,
    link_method = excluded.link_method;

  insert into private.comun_participation_wallet_events (
    wallet_id,
    event_type,
    result_code
  )
  values (
    v_wallet_id,
    'item_updated',
    'WALLET_ACCOUNT_LINKED'
  );

  return query
  select v_wallet_id, true;
end;
$_$;


ALTER FUNCTION public.comun_participation_wallet_link_account(p_token_hash_hex text, p_user_id uuid, p_link_method text) OWNER TO postgres;

--
-- Name: comun_participation_wallet_list(text); Type: FUNCTION; Schema: public; Owner: postgres
