CREATE FUNCTION public.comun_participation_wallet_list(p_token_hash_hex text) RETURNS TABLE(item_id uuid, item_type text, title_template text, category text, presentation_state text, action_required text, protocol_masked text, source_domain text, metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ select i.id,i.item_type,i.title_template,i.category,i.presentation_state,i.action_required,i.protocol_masked,i.source_domain,i.metadata,i.created_at,i.updated_at from private.comun_participation_wallets w join private.comun_participation_wallet_items i on i.wallet_id=w.id where w.token_hash=decode(p_token_hash_hex,'hex') and w.status='active' and i.archived_at is null order by (i.action_required is not null) desc,i.updated_at desc; $$;


