-- Name: comun_participation_wallet_redeem(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_participation_wallet_redeem(p_recovery_code_hash_hex text, p_new_token_hash_hex text) RETURNS TABLE(wallet_id uuid, recovery_ok boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare c private.comun_participation_wallet_recovery_credentials%rowtype; begin select * into c from private.comun_participation_wallet_recovery_credentials where recovery_hash=decode(p_recovery_code_hash_hex,'hex') and active=true and revoked_at is null and used_at is null; if not found then return query select null::uuid,false; return; end if; update private.comun_participation_wallets set token_hash=decode(p_new_token_hash_hex,'hex'),rotated_at=now() where id=c.wallet_id; update private.comun_participation_wallet_recovery_credentials set active=false,used_at=now() where id=c.id; return query select c.wallet_id,true; end; $$;


