CREATE FUNCTION public.comun_participation_wallet_revoke_account(p_token_hash_hex text, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare w uuid; begin select id into w from private.comun_participation_wallets where token_hash=decode(p_token_hash_hex,'hex') and status='active'; if w is null then return false; end if; update private.comun_participation_wallet_account_links set revoked_at=coalesce(revoked_at,now()) where wallet_id=w and user_id=p_user_id and revoked_at is null; if found then insert into private.comun_participation_wallet_events(wallet_id,event_type,result_code) values(w,'item_updated','WALLET_ACCOUNT_LINK_REVOKED'); end if; return found; end; $$;


