    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare w uuid; begin select wallets.id into w from private.comun_participation_wallets wallets where wallets.token_hash=decode(p_token_hash_hex,'hex') and wallets.status='active'; if w is null then return; end if; update private.comun_participation_wallets wallets set token_hash=decode(p_new_token_hash_hex,'hex'),rotated_at=now() where wallets.id=w; update private.comun_participation_wallet_recovery_credentials credentials set active=false,revoked_at=now() where credentials.wallet_id=w and credentials.active=true; insert into private.comun_participation_wallet_recovery_credentials(wallet_id,recovery_hash) values(w,decode(p_new_recovery_hash_hex,'hex')); return query select w,true; end; $$;


