--
-- Name: comun_prepare_cultural_contribution_handoff_v1(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_prepare_cultural_contribution_handoff_v1(p_public_protocol text, p_resume_token_hash text DEFAULT NULL::text, p_member_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(public_protocol text, status text, route_kind text, handoff_state text, target_kind text, target_created boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'extensions'
    AS $$
declare
  v private.comun_cultural_contribution_intakes%rowtype;
  v_target_id uuid;
  v_target_kind text;
  v_submitter_hash text := coalesce(nullif(p_resume_token_hash,''),encode(digest('member:'||coalesce(p_member_user_id::text,'anonymous'),'sha256'),'hex'));
begin
  select i.* into v from private.comun_cultural_contribution_intakes i
   where i.public_protocol=p_public_protocol
     and ((p_resume_token_hash is not null and i.resume_token_hash=p_resume_token_hash)
       or (p_member_user_id is not null and i.member_user_id=p_member_user_id))
   limit 1 for update;
  if v.id is null then return; end if;
  if v.target_id is not null and v.target_kind is not null then
    return query select v.public_protocol,v.status,v.route_kind,'handed_off'::text,v.target_kind,true;
    return;
  end if;
  if v.route_kind is null or v.route_kind='unknown' then
    update private.comun_cultural_contribution_intakes set status=case when v.route_kind='unknown' then 'routing' else 'handoff_pending' end,updated_at=now() where id=v.id returning * into v;
    return query select v.public_protocol,v.status,v.route_kind,'handoff_pending'::text,null::text,false;
    return;
  end if;
  if v.route_kind='photo_or_document' then
    v_target_kind:='comun_archive_submissions';
    insert into public.comun_archive_submissions(submission_type,status,contributor_credit_preference,relationship_to_material,title_suggestion,description_suggestion,rights_declaration,permission_confirmed,risk_level,submitter_hash)
    values('historical_photo','draft','anonymous','to_be_confirmed','Memória guardada pelo Acervo Vivo',v.intent_text_private,'pending_specialized_confirmation',false,'normal',v_submitter_hash) returning id into v_target_id;
  elsif v.route_kind='art' then
    v_target_kind:='comun_archive_artwork_submissions';
    insert into public.comun_archive_artwork_submissions(public_protocol,submission_kind,title_suggestion,artwork_type,context_suggestion,creator_credit_suggestion,status,is_author_or_authorized,information_true_declared,moderation_understood,correction_withdrawal_understood,submitter_hash)
    values('ARTE-'||upper(substr(replace(v.id::text,'-',''),1,12)),'unknown_authorship','Contribuição de arte em preparação','other',v.intent_text_private,'A confirmar pela pessoa autora ou autorizada','pending',false,false,false,false,v_submitter_hash) returning id into v_target_id;
  elsif v.route_kind='oral_history' then
    v_target_kind:='comun_archive_oral_history_suggestions';
    insert into public.comun_archive_oral_history_suggestions(suggested_person_or_theme,story_summary,status,submitter_hash)
    values('Memória para triagem de História Oral',v.intent_text_private,'pending',v_submitter_hash) returning id into v_target_id;
  elsif v.route_kind='radio' then
    v_target_kind:='comun_radio_contributions';
    insert into public.comun_radio_contributions(public_protocol,contribution_type,title_suggestion,context_suggestion,status,next_action_public)
    values('RADIO-'||upper(substr(replace(v.id::text,'-',''),1,12)),'program_proposal','Contribuição de pauta em preparação',v.intent_text_private,'pending','Aguardar triagem editorial; nenhuma publicação foi feita.') returning id into v_target_id;
  else
    update private.comun_cultural_contribution_intakes set status='handoff_pending',updated_at=now() where id=v.id returning * into v;
    return query select v.public_protocol,v.status,v.route_kind,'handoff_pending'::text,null::text,false;
    return;
  end if;
  update private.comun_cultural_contribution_intakes set status='handed_off',target_kind=v_target_kind,target_id=v_target_id,updated_at=now() where id=v.id returning * into v;
  return query select v.public_protocol,v.status,v.route_kind,'handed_off'::text,v.target_kind,true;
end $$;


ALTER FUNCTION public.comun_prepare_cultural_contribution_handoff_v1(p_public_protocol text, p_resume_token_hash text, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: comun_public_search_hybrid(text, text, uuid, uuid, extensions.vector, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_public_search_hybrid(p_query text, p_type text DEFAULT NULL::text, p_pauta_id uuid DEFAULT NULL::uuid, p_territory_id uuid DEFAULT NULL::uuid, p_query_embedding extensions.vector DEFAULT NULL::extensions.vector, p_limit integer DEFAULT 20) RETURNS TABLE(type text, title text, summary text, href text, origin text, updated_at timestamp with time zone, match_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with input as (
    select left(trim(coalesce(p_query, '')), 120) q,
      lower(extensions.unaccent(left(trim(coalesce(p_query, '')), 120))) normalized,
      websearch_to_tsquery('public.comun_portuguese_unaccent', left(trim(coalesce(p_query, '')), 120)) tsq,
      least(greatest(coalesce(p_limit, 20), 1), 50) lim
  ), candidates as (
    select d.*,
      lower(extensions.unaccent(d.title)) = i.normalized as exact_match,
      lower(extensions.unaccent(d.title)) like i.normalized || '%' as prefix_match,
      d.search_vector @@ i.tsq as fts_match,
      ts_rank_cd(d.search_vector, i.tsq, 32) as lexical_rank,
      extensions.similarity(lower(extensions.unaccent(d.title)), i.normalized) as typo_rank,
      case when p_query_embedding is null then null else (
        select min(s.embedding OPERATOR(extensions.<=>) p_query_embedding)
        from public.comun_search_sections s where s.document_id = d.id and s.embedding is not null
      ) end as semantic_distance
    from public.comun_search_documents d cross join input i
    where d.visibility = 'public_projection' and d.permission_scope = 'public'
      and (p_type is null or d.source_type = p_type)
      and (p_pauta_id is null or d.pauta_id = p_pauta_id)
      and (p_territory_id is null or d.territory_id = p_territory_id)
      and (i.q <> '' and (
        d.search_vector @@ i.tsq
        or lower(extensions.unaccent(d.title)) like '%' || i.normalized || '%'
        or extensions.similarity(lower(extensions.unaccent(d.title)), i.normalized) >= 0.28
        or (p_query_embedding is not null and exists (
          select 1 from public.comun_search_sections s
          where s.document_id = d.id and s.embedding is not null and s.embedding OPERATOR(extensions.<=>) p_query_embedding < 0.38
        ))
      ))
  ), ranked as (
    select c.*,
      row_number() over (order by exact_match desc, prefix_match desc, lexical_rank desc, typo_rank desc, source_date desc nulls last) lexical_position,
      case when semantic_distance is null then null else row_number() over (order by semantic_distance asc nulls last) end semantic_position
    from candidates c
  )
  select r.source_type, r.title, r.summary, r.canonical_route, initcap(r.domain), r.source_date,
    case
      when r.exact_match then 'correspondência exata'
      when r.prefix_match then 'título correspondente'
      when p_pauta_id is not null and r.pauta_id = p_pauta_id then 'mesma pauta'
      when p_territory_id is not null and r.territory_id = p_territory_id then 'mesmo território'
      when r.fts_match then 'termos relacionados'
      when r.semantic_distance is not null then 'relacionado pelo significado'
      else 'grafia aproximada'
    end
  from ranked r cross join input i
  order by
    r.exact_match desc,
    (1.0 / (60 + r.lexical_position) + coalesce(1.0 / (60 + r.semantic_position), 0)) desc,
    r.source_date desc nulls last, r.title
  limit (select lim from input)
$$;


ALTER FUNCTION public.comun_public_search_hybrid(p_query text, p_type text, p_pauta_id uuid, p_territory_id uuid, p_query_embedding extensions.vector, p_limit integer) OWNER TO postgres;

--
-- Name: comun_record_quality_metric(text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_record_quality_metric(p_metric_name text, p_route_class text, p_device_class text, p_app_version text, p_value_bucket integer, p_rating text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'COMUN_QUALITY_SERVER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  if p_metric_name not in ('LCP', 'INP', 'CLS', 'FCP', 'TTFB')
    or p_route_class not in ('home', 'discovery', 'search', 'process', 'territory', 'community', 'action', 'result', 'sidewalks', 'culture', 'help_security', 'auth', 'personal', 'admin', 'offline', 'other')
    or p_device_class not in ('mobile', 'desktop')
    or p_rating not in ('good', 'needs-improvement', 'poor')
    or p_app_version !~ '^[A-Za-z0-9._-]{1,40}$'
    or p_value_bucket not between 0 and 120000 then
    raise exception 'COMUN_QUALITY_METRIC_INVALID' using errcode = '22023';
  end if;

  insert into public.comun_quality_metrics_hourly (
    bucket, metric_name, route_class, device_class, app_version, value_bucket, rating, total
  ) values (
    date_trunc('hour', now()), p_metric_name, p_route_class, p_device_class,
    p_app_version, p_value_bucket, p_rating, 1
  )
  on conflict (bucket, metric_name, route_class, device_class, app_version, value_bucket, rating)
  do update set total = public.comun_quality_metrics_hourly.total + 1;
end
$_$;


ALTER FUNCTION public.comun_record_quality_metric(p_metric_name text, p_route_class text, p_device_class text, p_app_version text, p_value_bucket integer, p_rating text) OWNER TO postgres;

--
-- Name: comun_record_search_metric(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_record_search_metric(p_search_kind text, p_outcome text, p_query_size_band text, p_latency_band text, p_confidence_band text DEFAULT 'none'::text, p_model_version text DEFAULT 'lexical'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'COMUN_SEARCH_SERVER_ROLE_REQUIRED' using errcode = '42501';
  end if;
  insert into public.comun_search_metrics_hourly (
    bucket, search_kind, outcome, query_size_band, latency_band, confidence_band, model_version, total
  ) values (
    date_trunc('hour', now()), p_search_kind, p_outcome, p_query_size_band, p_latency_band,
    coalesce(nullif(p_confidence_band, ''), 'none'), left(coalesce(nullif(p_model_version, ''), 'lexical'), 80), 1
  )
  on conflict (bucket, search_kind, outcome, query_size_band, latency_band, confidence_band, model_version)
  do update set total = public.comun_search_metrics_hourly.total + 1;
end
$$;


ALTER FUNCTION public.comun_record_search_metric(p_search_kind text, p_outcome text, p_query_size_band text, p_latency_band text, p_confidence_band text, p_model_version text) OWNER TO postgres;

--
-- Name: comun_relata_add_location(text, text, text, text, timestamp with time zone, bytea, bytea, bytea, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_add_location(p_protocol text, p_receipt_secret text, p_origin text, p_accuracy_class text, p_captured_at timestamp with time zone, p_ciphertext bytea, p_nonce bytea, p_auth_tag bytea, p_key_version text, p_approximate_region text, p_approximation_level text, p_geographic_risk text) RETURNS TABLE(location_state text, grouping_allowed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
begin
  select *
    into v_context
    from private.comun_relata_authorized_context(p_protocol, p_receipt_secret);

  if not found then
    return;
  end if;

  insert into private.comun_relata_private_locations (
    report_id,
    precision,
    encrypted_value,
    origin,
    accuracy_class,
    captured_at,
    nonce,
    auth_tag,
    key_version,
    approximate_region,
    approximation_level,
    geographic_risk
  )
  values (
    v_context.report_id,
    p_origin,
    p_ciphertext,
    p_origin,
    p_accuracy_class,
    p_captured_at,
    p_nonce,
    p_auth_tag,
    p_key_version,
    left(p_approximate_region, 80),
    p_approximation_level,
    p_geographic_risk
  )
  on conflict (report_id) do update set
    precision = excluded.precision,
    encrypted_value = excluded.encrypted_value,
    origin = excluded.origin,
    accuracy_class = excluded.accuracy_class,
    captured_at = excluded.captured_at,
    nonce = excluded.nonce,
    auth_tag = excluded.auth_tag,
    key_version = excluded.key_version,
    evidence_state = 'added_private',
    approximate_region = excluded.approximate_region,
    approximation_level = excluded.approximation_level,
    geographic_risk = excluded.geographic_risk,
    review_required = true,
    withdrawn_at = null;

  return query select 'added_private'::text, true;
end;
$$;


ALTER FUNCTION public.comun_relata_add_location(p_protocol text, p_receipt_secret text, p_origin text, p_accuracy_class text, p_captured_at timestamp with time zone, p_ciphertext bytea, p_nonce bytea, p_auth_tag bytea, p_key_version text, p_approximate_region text, p_approximation_level text, p_geographic_risk text) OWNER TO postgres;

--
-- Name: comun_relata_associate_collective_for_wallet(text, uuid, text, bytea[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_associate_collective_for_wallet(p_token_hash_hex text, p_wallet_item_id uuid, p_requested_decision text, p_spatial_keys bytea[], p_window_start timestamp with time zone) RETURNS TABLE(grouping_state text, confidence_level text, active_members_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_context record;
  v_now timestamptz:=pg_catalog.now();
  v_previous uuid;
  v_target uuid;
  v_membership_role text;
  v_existing_method text;
  v_existing_confidence numeric(4,3);
  v_count integer;
  v_key bytea;
  v_window interval;
begin
  if p_token_hash_hex is null
     or p_token_hash_hex !~ '^[0-9a-f]{64}$'
     or p_wallet_item_id is null then
    return;
  end if;
  select
    w.id as wallet_id, wi.id as wallet_item_id, c.id as case_id,
    c.report_id, c.protocol, c.category, c.urgency, c.state as case_state,
    r.withdrawn_at as report_withdrawn_at, r.privacy_class,
    (l.id is not null and l.evidence_state='added_private'
      and l.withdrawn_at is null
      and l.approximation_level in ('neighborhood','region')
      and l.geographic_risk in ('unreviewed','low','medium')) as location_ready
    into v_context
    from private.comun_participation_wallets w
    join private.comun_participation_wallet_items wi
      on wi.wallet_id=w.id and wi.id=p_wallet_item_id
     and wi.item_type='relata_report' and wi.archived_at is null
    join public.comun_relata_cases c on c.id::text=wi.subject_ref
    join private.comun_relata_reports r on r.id=c.report_id
    left join private.comun_relata_private_locations l on l.report_id=r.id
   where w.token_hash=pg_catalog.decode(p_token_hash_hex,'hex')
     and w.status='active';
  if not found then return; end if;

  if v_context.category not in ('public_lighting','power_distribution','smoke_or_environmental_trace')
     or v_context.case_state='withdrawn'
     or v_context.report_withdrawn_at is not null
     or v_context.urgency='emergency'
     or v_context.privacy_class not in ('public_safe','public_after_sanitization')
     or not coalesce(v_context.location_ready,false)
     or p_requested_decision<>'auto_link_high_confidence'
     or coalesce(pg_catalog.array_length(p_spatial_keys,1),0)<>9
     or p_window_start is null
     or p_window_start>v_now then
    return;
  end if;
  v_window:=case v_context.category
    when 'public_lighting' then interval '21 days'
    when 'power_distribution' then interval '12 hours'
    else interval '24 hours' end;
  if p_window_start < v_now-v_window then return; end if;
  if exists(
    select 1 from pg_catalog.unnest(p_spatial_keys) as keys(key_hash)
     where pg_catalog.octet_length(keys.key_hash)<>32
  ) then
    raise exception using errcode='22023', message='COMUN_RELATA_MATCH_INVALID_KEY_SHAPE';
  end if;
  if not exists(
    select 1 from private.comun_relata_public_projection_consents consent
     where consent.case_id=v_context.case_id
       and consent.active
       and consent.consent_version='relata-public-projection-v1'
       and consent.scope='collective_projection'
  ) then
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('relata-case:'||v_context.case_id::text,4862)
  );
  -- Lock every candidate key in lexical order so overlapping neighbour cells
  -- serialize even when two different cases arrive concurrently.
  for v_key in
    select key_hash from pg_catalog.unnest(p_spatial_keys) as keys(key_hash)
    order by pg_catalog.encode(key_hash,'hex')
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('relata-match:'||pg_catalog.encode(v_key,'hex'),4863)
    );
  end loop;

  select m.collective_case_id, m.association_method, m.confidence
    into v_previous, v_existing_method, v_existing_confidence
    from public.comun_relata_case_memberships m
   where m.individual_case_id=v_context.case_id and m.active
   order by m.created_at desc
   limit 1
   for update;
  if v_previous is not null then
    perform 1 from public.comun_relata_collective_cases where id=v_previous for update;
  end if;

  select collective.id into v_target
    from private.comun_relata_case_match_keys match_key
    join public.comun_relata_collective_cases collective
      on collective.id=match_key.collective_case_id
   where match_key.active
     and match_key.created_at>=p_window_start
     and match_key.key_hash=any(p_spatial_keys)
     and collective.category=v_context.category
     and collective.state='active'
     and (v_previous is null or collective.id<>v_previous)
   group by collective.id, collective.active_members_count, collective.created_at
   order by collective.active_members_count desc, collective.created_at asc
   limit 1;
  if v_target is not null then
    perform 1 from public.comun_relata_collective_cases where id=v_target for update;
  end if;

  if v_target is null then
    v_target:=v_previous;
    if v_target is null then
      insert into public.comun_relata_collective_cases(
        category,collective_urgency,state,match_rule,match_rule_version,
        active_members_count,first_report_at,last_report_at,confidence_level,
        future_map_eligibility,review_state
      ) values(
        v_context.category,v_context.urgency,'active','explicit_opt_in_seed',
        'relata-match-v1',0,v_now,v_now,'low',false,'not_requested'
      ) returning id into v_target;
      insert into public.comun_relata_case_memberships(
        collective_case_id,individual_case_id,membership_role,
        association_method,confidence,match_rule_version
      ) values(v_target,v_context.case_id,'seed','new_collective_case',.250,'relata-match-v1');
      v_existing_method:='new_collective_case';
      v_existing_confidence:=.250;
    end if;
    insert into private.comun_relata_case_match_keys(
      individual_case_id,collective_case_id,key_hash,match_rule_version
    )
    select distinct v_context.case_id,v_target,keys.key_hash,'relata-match-v1'
      from pg_catalog.unnest(p_spatial_keys) as keys(key_hash)
     where not exists(
       select 1 from private.comun_relata_case_match_keys existing
        where existing.individual_case_id=v_context.case_id
          and existing.collective_case_id=v_target
          and existing.key_hash=keys.key_hash
          and existing.active
     );
    select count(*)::integer into v_count
      from public.comun_relata_case_memberships
     where collective_case_id=v_target and active;
    update public.comun_relata_collective_cases
       set active_members_count=v_count, last_report_at=greatest(last_report_at,v_now), updated_at=v_now
     where id=v_target;
    if v_existing_method is null then
      select m.association_method,m.confidence into v_existing_method,v_existing_confidence
        from public.comun_relata_case_memberships m
       where m.individual_case_id=v_context.case_id and m.active;
    end if;
    return query select v_existing_method,case when v_existing_confidence>=.900 then 'high' else 'low' end,v_count;
    return;
  end if;

  -- A B1 seed is replaced only by a high-confidence match. The old seed is
  -- retained in history and becomes inactive; no second active membership is
  -- possible because the canonical partial unique index remains in force.
  if v_previous is not null and v_previous<>v_target then
    update public.comun_relata_case_memberships
       set active=false,ended_at=v_now,end_reason='RELATA_MATCH_RECALCULATED'
     where individual_case_id=v_context.case_id and active;
    update private.comun_relata_case_match_keys
       set active=false,ended_at=v_now
     where individual_case_id=v_context.case_id and active;
    select count(*)::integer into v_count
      from public.comun_relata_case_memberships
     where collective_case_id=v_previous and active;
    update public.comun_relata_collective_cases
       set active_members_count=v_count,
           state=case when v_count=0 then 'inactive' else 'active' end,
           updated_at=v_now
     where id=v_previous;
  end if;

  select case when exists(
    select 1 from public.comun_relata_case_memberships
     where collective_case_id=v_target and active
  ) then 'report' else 'seed' end into v_membership_role;
  insert into public.comun_relata_case_memberships(
    collective_case_id,individual_case_id,membership_role,
    association_method,confidence,match_rule_version
  ) values(v_target,v_context.case_id,v_membership_role,
    'auto_link_high_confidence',.950,'relata-match-v1');
  insert into private.comun_relata_case_match_keys(
    individual_case_id,collective_case_id,key_hash,match_rule_version
  )
  select distinct v_context.case_id,v_target,keys.key_hash,'relata-match-v1'
    from pg_catalog.unnest(p_spatial_keys) as keys(key_hash);
  select count(*)::integer into v_count
    from public.comun_relata_case_memberships
   where collective_case_id=v_target and active;
  update public.comun_relata_collective_cases
     set active_members_count=v_count,last_report_at=greatest(last_report_at,v_now),
         confidence_level='high',state='active',updated_at=v_now
   where id=v_target;
  insert into public.comun_relata_case_match_events(
    individual_case_id,previous_collective_case_id,collective_case_id,
    decision,confidence_level,match_rule_version,result_code
  ) values(v_context.case_id,v_previous,v_target,'auto_link_high_confidence',
    'high','relata-match-v1','RELATA_COLLECTIVE_ASSOCIATION_RECORDED');
  if not exists(
    select 1 from public.comun_relata_evidence_consents
     where case_id=v_context.case_id and consent_kind='collective_grouping' and active
  ) then
    insert into public.comun_relata_evidence_consents(
      case_id,consent_kind,consent_version,active,result_code
    ) values(v_context.case_id,'collective_grouping','relata-collective-grouping-v1',true,
      'RELATA_COLLECTIVE_GROUPING_ALLOWED');
  end if;
  return query select 'auto_link_high_confidence','high',v_count;
end;
$_$;


ALTER FUNCTION public.comun_relata_associate_collective_for_wallet(p_token_hash_hex text, p_wallet_item_id uuid, p_requested_decision text, p_spatial_keys bytea[], p_window_start timestamp with time zone) OWNER TO postgres;

--
-- Name: comun_relata_authorize_attachment_read(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_authorize_attachment_read(p_protocol text, p_receipt_secret text, p_attachment_id uuid) RETURNS TABLE(attachment_id uuid, label_index smallint, attachment_state text, object_key text, derivative_object_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ select a.id,a.label_index,a.state,a.object_key,a.derivative_object_key from private.comun_relata_attachments a where a.id=p_attachment_id and a.report_id=(select report_id from private.comun_relata_authorized_context(p_protocol,p_receipt_secret)) and a.state='sealed_private'; $$;


ALTER FUNCTION public.comun_relata_authorize_attachment_read(p_protocol text, p_receipt_secret text, p_attachment_id uuid) OWNER TO postgres;

--
-- Name: comun_relata_begin_attachment(text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_begin_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_declared_mime_type text, p_declared_size_bucket text) RETURNS TABLE(attachment_id uuid, label_index smallint, attachment_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_label_index smallint;
begin
  select *
    into v_context
    from private.comun_relata_authorized_context(
      p_protocol,
      p_receipt_secret
    );

  if not found
    or p_declared_mime_type not in (
      'image/jpeg',
      'image/png',
      'image/webp'
    )
  then
    return;
  end if;

  perform 1
    from private.comun_relata_reports as r
    where r.id = v_context.report_id
    for update;

  select (coalesce(max(a.label_index), 0) + 1)::smallint
    into v_label_index
    from private.comun_relata_attachments as a
    where a.report_id = v_context.report_id;

  if v_label_index > 3 then
    raise exception using
      errcode = '23514',
      message = 'COMUN_RELATA_ATTACHMENT_LIMIT';
  end if;

  insert into private.comun_relata_attachments (
    id,
    report_id,
    label_index,
    object_key,
    derivative_object_key,
    declared_mime_type,
    declared_size_bucket
  )
  values (
    p_attachment_id,
    v_context.report_id,
    v_label_index,
    'quarantine/' || p_attachment_id::text || '.bin',
    'sealed/' || p_attachment_id::text || '.webp',
    p_declared_mime_type,
    p_declared_size_bucket
  )
  on conflict (id) do nothing;

  return query
  select
    p_attachment_id,
    v_label_index,
    'quarantine'::text;
end;
$$;


ALTER FUNCTION public.comun_relata_begin_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_declared_mime_type text, p_declared_size_bucket text) OWNER TO postgres;

--
-- Name: comun_relata_classification_transition(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_classification_transition(p_protocol text, p_receipt_secret text, p_original_text text, p_category text, p_decision jsonb) RETURNS TABLE(report_id uuid, case_id uuid, protocol text, category text, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_report private.comun_relata_reports%rowtype;
  v_decision jsonb;
  v_urgency text;
  v_routing_version text;
  v_health_issue_type text;
  v_education_issue_type text;
  v_child_safety_signal boolean;
  v_child_protection_issue_type text;
  v_immediate_danger boolean;
  v_privacy_class text;
  v_previous_text_absent boolean;
begin
  v_urgency := case when p_decision->>'urgency' in ('routine','attention','urgent','emergency') then p_decision->>'urgency' else null end;
  v_routing_version := coalesce(nullif(p_decision->>'routingVersion',''),'relata-routing-v1');
  v_health_issue_type := nullif(p_decision->>'healthIssueType','');
  v_education_issue_type := nullif(p_decision->>'educationIssueType','');
  v_child_safety_signal := coalesce((p_decision->>'childSafetySignal')::boolean,false);
  v_child_protection_issue_type := nullif(p_decision->>'childProtectionIssueType','');
  v_immediate_danger := case
    when p_decision->'immediateDanger' = 'true'::jsonb then true
    when p_decision->'immediateDanger' = 'false'::jsonb then false
    else null
  end;
  v_privacy_class := nullif(p_decision->>'privacyClass','');
  select * into v_context from private.comun_relata_authorized_context(p_protocol,p_receipt_secret);
  if not found or v_context.case_state='withdrawn'
    or v_context.category not in ('other','public_education')
    or (v_context.category='public_education' and p_category<>'child_protection')
    or p_category not in (
      'water_supply','power_distribution','public_lighting','active_fire',
      'smoke_or_environmental_trace','environmental_pollution','waste_or_debris',
      'urban_flooding','stormwater_drainage','tree_hazard','public_health',
      'public_education','child_protection'
    )
    or v_urgency is null
    or v_routing_version not in (
      'relata-routing-v1','relata-routing-v2-environmental',
      'relata-routing-v3-urban-incidents','comun-health-service-routing-v1',
      'comun-education-service-routing-v1','comun-child-protection-routing-v1'
    )
    or (p_category='public_health' and (
      v_routing_version<>'comun-health-service-routing-v1'
      or v_health_issue_type is null
      or v_health_issue_type not in (
        'access_or_waiting','exam_or_procedure','medicine_or_supply',
        'staff_or_service_availability','facility_or_accessibility','care_conduct',
        'transfer_or_health_transport','information_or_followup','other_health_service'
      )
      or v_privacy_class not in ('sensitive','high_risk')
      or p_decision->>'publication' is distinct from 'never_automatic'
    ))
    or (p_category<>'public_health' and (
      v_routing_version='comun-health-service-routing-v1'
      or v_health_issue_type is not null
    ))
    or (p_category='public_education' and (
      v_routing_version<>'comun-education-service-routing-v1'
      or v_education_issue_type is null
      or v_education_issue_type not in (
        'staff_or_service_availability','infrastructure_or_climate','school_meals_or_supplies',
        'school_transport_or_access','accessibility_or_inclusion','enrollment_or_attendance',
        'discrimination_or_bullying','information_or_management','other_education_service'
      )
      or v_privacy_class not in ('restricted','sensitive','high_risk')
      or p_decision->>'publication' is distinct from 'never_automatic'
      or p_decision->'requiresHumanReview' is distinct from 'true'::jsonb
    ))
    or (p_category<>'public_education' and (
      v_routing_version='comun-education-service-routing-v1'
      or v_education_issue_type is not null
      or p_decision ? 'childSafetySignal'
    ))
    or (p_category='child_protection' and (
      v_routing_version<>'comun-child-protection-routing-v1'
      or v_child_protection_issue_type not in (
        'immediate_danger','violence_or_abuse_concern',
        'neglect_or_abandonment_concern','exploitation_or_rights_violation',
        'institutional_protection_failure','other_child_protection'
      )
      or not (p_decision ? 'immediateDanger')
      or v_privacy_class<>'high_risk'
      or p_decision->>'publication' is distinct from 'never_automatic'
      or p_decision->'requiresHumanReview' is distinct from 'true'::jsonb
      or (v_immediate_danger is true and v_urgency<>'emergency')
      or (v_immediate_danger is not true and v_urgency not in ('urgent','emergency'))
    ))
    or (p_category<>'child_protection' and (
      v_routing_version='comun-child-protection-routing-v1'
      or v_child_protection_issue_type is not null
      or p_decision ? 'immediateDanger'
    ))
    or coalesce(p_decision,'{}'::jsonb) ? 'matchedSignals'
    or char_length(trim(coalesce(p_original_text,''))) not between 8 and 600
    or jsonb_typeof(coalesce(p_decision,'{}'::jsonb))<>'object'
    or octet_length(convert_to(coalesce(p_decision,'{}'::jsonb)::text,'utf8'))>4096
  then return; end if;

  select * into v_report from private.comun_relata_reports
    where id=v_context.report_id and withdrawn_at is null for update;
  if not found then return; end if;
  v_previous_text_absent := v_report.original_text is null;

  v_decision:=jsonb_build_object(
    'category',p_category,'urgency',v_urgency,'ruleVersion','relata-routing-v1',
    'routingVersion',v_routing_version,'source','person_added_semantic_context',
    'requiresHumanReview',coalesce((p_decision->>'requiresHumanReview')::boolean,false),
    'confidence',case when p_decision->>'confidence' in ('high','medium','low') then p_decision->>'confidence' else 'low' end,
    'publication','never_automatic','automaticForwarding',false
  ) || case when p_category='public_health'
    then jsonb_build_object('healthIssueType',v_health_issue_type)
    else '{}'::jsonb
  end || case when p_category='public_education'
    then jsonb_build_object(
      'educationIssueType',v_education_issue_type,
      'childSafetySignal',v_child_safety_signal
    )
    else '{}'::jsonb
  end || case when p_category='child_protection'
    then jsonb_build_object(
      'childProtectionIssueType',v_child_protection_issue_type,
      'immediateDanger',to_jsonb(v_immediate_danger)
    )
    else '{}'::jsonb
  end;
  update private.comun_relata_reports set
    original_text=case
      when original_text is null then trim(p_original_text)
      else original_text||E'\n\nContexto adicional: '||trim(p_original_text)
    end,
    routing_decision=v_decision,routing_rule_version='relata-routing-v1',
    urgency=v_urgency,
    privacy_class=case when p_category in ('public_health','public_education','child_protection') then v_privacy_class else privacy_class end,
    retention_class=case when p_category in ('public_health','public_education','child_protection') then 'sensitive' else retention_class end,
    review_after=case when p_category in ('public_health','public_education','child_protection') then now()+interval '30 days' else review_after end,
    updated_at=now()
  where id=v_context.report_id;
  update public.comun_relata_cases set
    category=p_category,urgency=v_urgency,routing_decision=v_decision,
    routing_rule_version='relata-routing-v1',updated_at=now()
  where id=v_context.case_id;
  update private.comun_participation_wallet_items set
    category=p_category,
    title_template=case
      when p_category in ('water_supply','power_distribution','public_lighting') then 'Relato de serviço essencial'
      else 'Relato COMUN'
    end,
    presentation_state=case
      when p_category in ('water_supply','power_distribution','public_lighting') then 'Pronto para encaminhar'
      when p_category='child_protection' then 'Guardado com proteção reforçada'
      else 'Guardado'
    end,
    action_required=case
      when p_category in ('water_supply','power_distribution','public_lighting') then 'Preparar encaminhamento'
      else null
    end,
    metadata=case
      when p_category='public_education' then jsonb_build_object(
        'educationIssueType',v_education_issue_type,
        'childSafetySignal',v_child_safety_signal
      )
      when p_category='child_protection' then jsonb_build_object(
        'immediateDanger',coalesce(v_immediate_danger,false)
      )
      else metadata
    end,
    updated_at=now()
  where item_type='relata_report' and subject_ref=v_context.case_id::text and archived_at is null;
  insert into private.comun_relata_classification_events(
    report_id,case_id,previous_category,next_category,event_type,previous_text_absent,actor
  ) values(
    v_context.report_id,v_context.case_id,v_context.category,p_category,
    'person_added_semantic_context',v_previous_text_absent,'person'
  );
  return query select v_context.report_id,v_context.case_id,p_protocol,p_category,v_context.case_state;
end;
$$;


ALTER FUNCTION public.comun_relata_classification_transition(p_protocol text, p_receipt_secret text, p_original_text text, p_category text, p_decision jsonb) OWNER TO postgres;

--
-- Name: comun_relata_collective_connection_for_wallet(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_collective_connection_for_wallet(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(connection text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  select case when collective.active_members_count>1
    or membership.association_method='auto_link_high_confidence'
    then 'matched' else 'waiting' end
    from private.comun_participation_wallets w
    join private.comun_participation_wallet_items wi
      on wi.wallet_id=w.id and wi.id=p_wallet_item_id
     and wi.item_type='relata_report' and wi.archived_at is null
    join public.comun_relata_cases c on c.id::text=wi.subject_ref
    join private.comun_relata_public_projection_consents consent
      on consent.case_id=c.id and consent.active
     and consent.consent_version='relata-public-projection-v1'
     and consent.scope='collective_projection'
    join public.comun_relata_case_memberships membership
      on membership.individual_case_id=c.id and membership.active
    join public.comun_relata_collective_cases collective
      on collective.id=membership.collective_case_id and collective.state='active'
   where p_token_hash_hex ~ '^[0-9a-f]{64}$'
     and w.token_hash=pg_catalog.decode(p_token_hash_hex,'hex')
     and w.status='active'
     and c.state<>'withdrawn';
$_$;


ALTER FUNCTION public.comun_relata_collective_connection_for_wallet(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_relata_create(text, text, text, jsonb, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_create(p_idempotency_key text, p_receipt_secret text, p_original_text text, p_answers jsonb, p_category text, p_urgency text, p_rule_version text, p_decision jsonb, p_privacy_class text, p_consent_version text) RETURNS TABLE(protocol text, state text, category text, urgency text, rule_version text, created_at timestamp with time zone, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  ih bytea;
  rh bytea;
  ph bytea;
  rid uuid;
  cid uuid;
  proto text;
  existing private.comun_relata_reports%rowtype;
  decision jsonb;
  routing_version text;
  health_issue_type text;
  education_issue_type text;
  child_safety_signal boolean;
  child_protection_issue_type text;
  immediate_danger boolean;
begin
  if p_idempotency_key !~ '^[A-Za-z0-9_-]{32,160}$'
    or p_receipt_secret !~ '^[A-Za-z0-9_-]{32,160}$'
    or (p_original_text is not null and char_length(trim(p_original_text)) not between 8 and 600)
  then
    raise exception using errcode='22023', message='COMUN_RELATA_INVALID_PROOF';
  end if;

  routing_version := coalesce(nullif(p_decision->>'routingVersion',''),p_rule_version);
  health_issue_type := nullif(p_decision->>'healthIssueType','');
  education_issue_type := nullif(p_decision->>'educationIssueType','');
  child_safety_signal := coalesce((p_decision->>'childSafetySignal')::boolean,false);
  child_protection_issue_type := nullif(p_decision->>'childProtectionIssueType','');
  immediate_danger := case
    when p_decision->'immediateDanger' = 'true'::jsonb then true
    when p_decision->'immediateDanger' = 'false'::jsonb then false
    else null
  end;
  if jsonb_typeof(coalesce(p_answers,'{}'::jsonb)) <> 'object'
    or coalesce(p_answers,'{}'::jsonb)
      - 'homes_power' - 'smoke_active' - 'flood_active_risk' - 'tree_state'
      - 'health_issue_type' - 'education_issue_type' - 'child_immediate_danger'
      - 'blocked' - 'line' - 'direction' - 'unit' - 'school_type' <> '{}'::jsonb
    or (coalesce(p_answers,'{}'::jsonb) ? 'homes_power' and coalesce(p_answers,'{}'::jsonb)->>'homes_power' not in ('sim','nao'))
    or (coalesce(p_answers,'{}'::jsonb) ? 'smoke_active' and coalesce(p_answers,'{}'::jsonb)->>'smoke_active' not in ('sim','nao','nao_sei'))
    or (coalesce(p_answers,'{}'::jsonb) ? 'flood_active_risk' and coalesce(p_answers,'{}'::jsonb)->>'flood_active_risk' not in ('sim','nao','nao_sei'))
    or (coalesce(p_answers,'{}'::jsonb) ? 'tree_state' and coalesce(p_answers,'{}'::jsonb)->>'tree_state' not in ('caiu','em_pe','nao_sei'))
    or (coalesce(p_answers,'{}'::jsonb) ? 'child_immediate_danger' and coalesce(p_answers,'{}'::jsonb)->>'child_immediate_danger' not in ('sim','nao','nao_sei'))
    or (coalesce(p_answers,'{}'::jsonb) ? 'health_issue_type' and coalesce(p_answers,'{}'::jsonb)->>'health_issue_type' not in (
      'access_or_waiting','exam_or_procedure','medicine_or_supply',
      'staff_or_service_availability','facility_or_accessibility','care_conduct',
      'transfer_or_health_transport','information_or_followup','other_health_service'
    ))
    or (coalesce(p_answers,'{}'::jsonb) ? 'education_issue_type' and coalesce(p_answers,'{}'::jsonb)->>'education_issue_type' not in (
      'staff_or_service_availability','infrastructure_or_climate','school_meals_or_supplies',
      'school_transport_or_access','accessibility_or_inclusion','enrollment_or_attendance',
      'discrimination_or_bullying','information_or_management','other_education_service'
    ))
    or jsonb_typeof(coalesce(p_decision,'{}'::jsonb)) <> 'object'
    or coalesce(p_decision,'{}'::jsonb) ? 'matchedSignals'
    or routing_version not in (
      'relata-routing-v1','relata-routing-v2-environmental',
      'relata-routing-v3-urban-incidents','comun-health-service-routing-v1',
      'comun-education-service-routing-v1','comun-child-protection-routing-v1'
    )
    or octet_length(convert_to(coalesce(p_decision,'{}'::jsonb)::text,'utf8')) > 4096
  then
    raise exception using errcode='22023', message='COMUN_RELATA_INVALID_TRIAGE';
  end if;

  if p_category not in (
      'public_lighting','power_distribution','water_supply','electrical_hazard',
      'active_fire','smoke_or_environmental_trace','sidewalk_accessibility',
      'waste_or_debris','public_transport','public_health','public_education',
      'child_protection','workplace','environmental_pollution','urban_flooding',
      'stormwater_drainage','tree_hazard','other'
    )
    or p_urgency not in ('routine','attention','urgent','emergency')
    or p_rule_version <> 'relata-routing-v1'
    or p_privacy_class not in ('public_safe','public_after_sanitization','restricted','sensitive','high_risk')
    or p_consent_version <> 'relata-consent-v1'
    or (p_category='public_health' and (
      routing_version <> 'comun-health-service-routing-v1'
      or health_issue_type is null
      or health_issue_type not in (
        'access_or_waiting','exam_or_procedure','medicine_or_supply',
        'staff_or_service_availability','facility_or_accessibility','care_conduct',
        'transfer_or_health_transport','information_or_followup','other_health_service'
      )
      or p_privacy_class not in ('sensitive','high_risk')
      or p_decision->>'publication' is distinct from 'never_automatic'
    ))
    or (p_category<>'public_health' and (
      routing_version='comun-health-service-routing-v1'
      or health_issue_type is not null
    ))
    or (p_category='public_education' and (
      routing_version <> 'comun-education-service-routing-v1'
      or education_issue_type is null
      or education_issue_type not in (
        'staff_or_service_availability','infrastructure_or_climate','school_meals_or_supplies',
        'school_transport_or_access','accessibility_or_inclusion','enrollment_or_attendance',
        'discrimination_or_bullying','information_or_management','other_education_service'
      )
      or p_privacy_class not in ('restricted','sensitive','high_risk')
      or p_decision->>'publication' is distinct from 'never_automatic'
      or p_decision->'requiresHumanReview' is distinct from 'true'::jsonb
    ))
    or (p_category<>'public_education' and (
      routing_version='comun-education-service-routing-v1'
      or education_issue_type is not null
      or p_decision ? 'childSafetySignal'
    ))
    or (p_category='child_protection' and (
      routing_version <> 'comun-child-protection-routing-v1'
      or child_protection_issue_type not in (
        'immediate_danger','violence_or_abuse_concern',
        'neglect_or_abandonment_concern','exploitation_or_rights_violation',
        'institutional_protection_failure','other_child_protection'
      )
      or not (p_decision ? 'immediateDanger')
      or p_privacy_class <> 'high_risk'
      or p_decision->>'publication' is distinct from 'never_automatic'
      or p_decision->'requiresHumanReview' is distinct from 'true'::jsonb
      or (immediate_danger is true and p_urgency <> 'emergency')
      or (immediate_danger is not true and p_urgency not in ('urgent','emergency'))
    ))
    or (p_category<>'child_protection' and (
      routing_version='comun-child-protection-routing-v1'
      or child_protection_issue_type is not null
      or p_decision ? 'immediateDanger'
    ))
  then
    raise exception using errcode='22023', message='COMUN_RELATA_INVALID_CONTRACT';
  end if;

  if p_original_text is null and (
    p_category not in ('other','sidewalk_accessibility')
    or p_privacy_class not in ('sensitive','high_risk')
    or p_decision->>'captureBasis' is distinct from 'photo_only'
    or p_decision->>'semanticTextState' is distinct from 'absent'
    or p_decision->>'captureState' is distinct from 'captured_private'
    or p_decision->'requiresEnrichment' is distinct from 'true'::jsonb
  ) then
    raise exception using errcode='22023', message='COMUN_RELATA_INVALID_PHOTO_ONLY_CONTRACT';
  end if;

  if p_original_text is null then
    decision := jsonb_build_object(
      'category',p_category,'urgency',p_urgency,'ruleVersion',p_rule_version,
      'routingVersion',p_rule_version,'source','photo_first_private_capture',
      'captureBasis','photo_only','semanticTextState','absent',
      'captureState','captured_private','requiresEnrichment',true,
      'requiresHumanReview',true,'confidence','low',
      'agencyKind','community_review','publication','never_automatic',
      'automaticForwarding',false
    );
  else
    decision := jsonb_build_object(
      'category',p_category,'urgency',p_urgency,'ruleVersion',p_rule_version,
      'routingVersion',routing_version,'source','deterministic_server_route',
      'requiresHumanReview',coalesce((p_decision->>'requiresHumanReview')::boolean,false),
      'confidence',case when p_decision->>'confidence' in ('high','medium','low') then p_decision->>'confidence' else 'low' end,
      'publication','never_automatic','automaticForwarding',false
    ) || case when p_category='public_health'
      then jsonb_build_object('healthIssueType',health_issue_type)
      else '{}'::jsonb
    end || case when p_category='public_education'
      then jsonb_build_object(
        'educationIssueType',education_issue_type,
        'childSafetySignal',child_safety_signal
      )
      else '{}'::jsonb
    end || case when p_category='child_protection'
      then jsonb_build_object(
        'childProtectionIssueType',child_protection_issue_type,
        'immediateDanger',to_jsonb(immediate_danger)
      )
      else '{}'::jsonb
    end;
  end if;

  ih := extensions.digest('relata-idempotency-v1:'||p_idempotency_key,'sha256');
  rh := extensions.digest('relata-receipt-v1:'||p_receipt_secret,'sha256');
  ph := extensions.digest(convert_to(jsonb_build_object(
    'text',case when p_original_text is null then 'COMUN_NO_SEMANTIC_TEXT_V1' else trim(p_original_text) end,
    'answers',coalesce(p_answers,'{}'::jsonb),'category',p_category,
    'urgency',p_urgency,'decision',decision
  )::text,'utf8'),'sha256');

  perform pg_advisory_xact_lock(hashtextextended(encode(ih,'hex'),4800));
  select * into existing from private.comun_relata_reports where idempotency_hash=ih;
  if found then
    if existing.payload_hash<>ph or existing.receipt_hash<>rh then
      raise exception using errcode='P0001',message='COMUN_RELATA_IDEMPOTENCY_CONFLICT';
    end if;
    return query select c.protocol,c.state,c.category,c.urgency,c.routing_rule_version,c.created_at,true
      from public.comun_relata_cases c where c.report_id=existing.id;
    return;
  end if;

  insert into private.comun_relata_reports(
    original_text,triage_answers,receipt_hash,actor_hash,idempotency_hash,
    payload_hash,privacy_class,routing_rule_version,routing_decision,urgency,
    consent_version,retention_class,review_after
  ) values(
    case when p_original_text is null then null else trim(p_original_text) end,
    coalesce(p_answers,'{}'::jsonb),rh,
    extensions.digest('relata-actor-v1:'||p_receipt_secret,'sha256'),ih,ph,
    p_privacy_class,p_rule_version,decision,p_urgency,p_consent_version,
    case when p_category in ('public_education','child_protection') or p_privacy_class in ('sensitive','high_risk') then 'sensitive' else 'private_unsubmitted' end,
    now()+case when p_category in ('public_education','child_protection') or p_privacy_class in ('sensitive','high_risk') then interval '30 days' else interval '90 days' end
  ) returning id into rid;

  loop
    proto := 'COMUN-RELATA-'||upper(encode(extensions.gen_random_bytes(8),'hex'));
    exit when not exists(select 1 from public.comun_relata_cases c where c.protocol=proto);
  end loop;

  insert into public.comun_relata_cases(
    report_id,protocol,category,urgency,routing_rule_version,routing_decision,state
  ) values(rid,proto,p_category,p_urgency,p_rule_version,decision,'stored_private')
  returning id into cid;
  insert into public.comun_relata_consents(case_id,consent_version) values(cid,p_consent_version);
  insert into public.comun_relata_status_events(case_id,state,actor,result_code) values
    (cid,'draft','person','RELATA_DRAFT_ACCEPTED'),
    (cid,'triage','system_local','RELATA_TRIAGE_RECORDED'),
    (cid,'routed','system_local','RELATA_ROUTE_CLASSIFIED'),
    (cid,'stored_private','system_local','RELATA_STORED_PRIVATE');
  return query select proto,'stored_private',p_category,p_urgency,p_rule_version,now(),false;
end;
$_$;


ALTER FUNCTION public.comun_relata_create(p_idempotency_key text, p_receipt_secret text, p_original_text text, p_answers jsonb, p_category text, p_urgency text, p_rule_version text, p_decision jsonb, p_privacy_class text, p_consent_version text) OWNER TO postgres;

--
-- Name: comun_relata_finalize_attachment(text, text, uuid, text, bigint, bigint, integer, integer, bytea, bytea); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_finalize_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_actual_mime_type text, p_actual_size_bytes bigint, p_derivative_size_bytes bigint, p_width integer, p_height integer, p_checksum_sha256 bytea, p_derivative_checksum_sha256 bytea) RETURNS TABLE(attachment_id uuid, attachment_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ begin update private.comun_relata_attachments a set state='sealed_private',actual_mime_type=p_actual_mime_type,actual_size_bytes=p_actual_size_bytes,derivative_size_bytes=p_derivative_size_bytes,width=p_width,height=p_height,checksum_sha256=p_checksum_sha256,derivative_checksum_sha256=p_derivative_checksum_sha256,sealed_at=now(),updated_at=now() where a.id=p_attachment_id and a.report_id=(select report_id from private.comun_relata_authorized_context(p_protocol,p_receipt_secret)) and a.state='validating' returning a.id,a.state into attachment_id,attachment_state; return next; end; $$;


ALTER FUNCTION public.comun_relata_finalize_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_actual_mime_type text, p_actual_size_bytes bigint, p_derivative_size_bytes bigint, p_width integer, p_height integer, p_checksum_sha256 bytea, p_derivative_checksum_sha256 bytea) OWNER TO postgres;

--
-- Name: comun_relata_get_evidence_state(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_get_evidence_state(p_protocol text, p_receipt_secret text) RETURNS TABLE(evidence jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare x record; location_state text := 'not_added'; location_approximation text := 'none'; photos jsonb := '[]'::jsonb;
begin
  select * into x from private.comun_relata_authorized_context(p_protocol,p_receipt_secret);
  if not found then return; end if;
  select case when l.evidence_state='withdrawn' then 'withdrawn' when l.approximation_level in ('neighborhood','region') then 'approximate_private' else 'added_private' end,
         case when l.approximation_level in ('neighborhood','region') then l.approximation_level else 'none' end
    into location_state,location_approximation
    from private.comun_relata_private_locations l where l.report_id=x.report_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'label','Foto '||a.label_index,
    'state',a.state,
    'mimeType',a.actual_mime_type,
    'width',a.width,
    'height',a.height,
    'reviewRequiredForPublication',true,
    'accessUrl','/api/comun/relata/evidence/attachments/'||a.id::text
  ) order by a.label_index),'[]'::jsonb) into photos
    from private.comun_relata_attachments a where a.report_id=x.report_id;
  return query select jsonb_build_object(
    'location',location_state,
    'locationApproximation',location_approximation,
    'photos',photos,
    'grouping','case_individual',
    'groupingConfidence','blocked',
    'activeReportsInCollective',0,
    'noOfficialSend',true,
    'nothingPublished',true
  );
end; $$;


ALTER FUNCTION public.comun_relata_get_evidence_state(p_protocol text, p_receipt_secret text) OWNER TO postgres;

--
-- Name: comun_relata_get_receipt(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_get_receipt(p_protocol text, p_receipt_secret text) RETURNS TABLE(protocol text, state text, category text, urgency text, rule_version text, created_at timestamp with time zone, withdrawn_at timestamp with time zone, timeline jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 select c.protocol,c.state,c.category,c.urgency,c.routing_rule_version,c.created_at,c.withdrawn_at,coalesce((select jsonb_agg(jsonb_build_object('state',e.state,'occurredAt',e.occurred_at,'resultCode',e.result_code) order by e.occurred_at,e.id) from public.comun_relata_status_events e where e.case_id=c.id),'[]'::jsonb) from public.comun_relata_cases c join private.comun_relata_reports r on r.id=c.report_id where c.protocol=p_protocol and r.receipt_hash=extensions.digest('relata-receipt-v1:'||p_receipt_secret,'sha256'); $$;


ALTER FUNCTION public.comun_relata_get_receipt(p_protocol text, p_receipt_secret text) OWNER TO postgres;

--
-- Name: comun_relata_mark_attachment_validating(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_mark_attachment_validating(p_protocol text, p_receipt_secret text, p_attachment_id uuid) RETURNS TABLE(attachment_id uuid, attachment_state text, declared_mime_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ begin update private.comun_relata_attachments a set state='validating',updated_at=now() where a.id=p_attachment_id and a.report_id=(select report_id from private.comun_relata_authorized_context(p_protocol,p_receipt_secret)) and a.state='quarantine' returning a.id,a.state,a.declared_mime_type into attachment_id,attachment_state,declared_mime_type; return next; end; $$;


ALTER FUNCTION public.comun_relata_mark_attachment_validating(p_protocol text, p_receipt_secret text, p_attachment_id uuid) OWNER TO postgres;

--
-- Name: comun_relata_public_projection_consent_set(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_public_projection_consent_set(p_token_hash_hex text, p_wallet_item_id uuid, p_active boolean) RETURNS TABLE(available boolean, active boolean, category text, location_ready boolean, grouping_ready boolean, result_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_eligible boolean := false;
  v_collective_id uuid;
  v_now timestamptz := pg_catalog.now();
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(coalesce(p_wallet_item_id::text, ''), 4861)
  );

  select * into v_context
    from private.comun_relata_public_projection_owned_context(
      p_token_hash_hex, p_wallet_item_id
    );

  if not found then
    return query select false, false, null::text, false, false,
      'RELATA_PUBLIC_OPT_IN_NOT_AVAILABLE'::text;
    return;
  end if;

  v_eligible := coalesce((v_context.category in (
    'public_lighting', 'power_distribution', 'smoke_or_environmental_trace'
  )
  and v_context.case_state <> 'withdrawn'
  and v_context.report_withdrawn_at is null
    and v_context.urgency <> 'emergency'
    and v_context.privacy_class in ('public_safe', 'public_after_sanitization')
    and v_context.location_ready), false);

  if not v_eligible and p_active then
    return query select false, false, null::text, false, false,
      'RELATA_PUBLIC_OPT_IN_NOT_AVAILABLE'::text;
    return;
  end if;

  if p_active then
    insert into private.comun_relata_public_projection_consents(
      case_id, consent_version, scope, active, declared_at, withdrawn_at
    ) values (
      v_context.case_id, 'relata-public-projection-v1', 'collective_projection',
      true, v_now, null
    )
    on conflict (case_id) do update set
      consent_version = excluded.consent_version,
      scope = excluded.scope,
      active = true,
      declared_at = coalesce(
        private.comun_relata_public_projection_consents.declared_at,
        excluded.declared_at
      ),
      withdrawn_at = null;

    select m.collective_case_id into v_collective_id
      from public.comun_relata_case_memberships m
     where m.individual_case_id = v_context.case_id
       and m.active
     order by m.created_at desc
     limit 1
     for update;

    if v_collective_id is null then
      insert into public.comun_relata_collective_cases(
        category, collective_urgency, state, match_rule, match_rule_version,
        active_members_count, first_report_at, last_report_at,
        confidence_level, future_map_eligibility, review_state
      ) values (
        v_context.category, v_context.urgency, 'active',
        'explicit_opt_in_seed', 'relata-match-v1', 0, v_now, v_now,
        'low', false, 'not_requested'
      ) returning id into v_collective_id;

      insert into public.comun_relata_case_memberships(
        collective_case_id, individual_case_id, membership_role,
        association_method, confidence, match_rule_version
      ) values (
        v_collective_id, v_context.case_id, 'seed', 'new_collective_case',
        0.250, 'relata-match-v1'
      );

      update public.comun_relata_collective_cases
         set active_members_count = 1,
             updated_at = v_now
       where id = v_collective_id;
    end if;

    insert into private.comun_participation_wallet_events(
      wallet_id, item_id, event_type, result_code
    ) values (
      v_context.wallet_id, p_wallet_item_id, 'item_updated',
      'WALLET_PUBLIC_PROJECTION_CONSENT_GRANTED'
    );
  else
    update private.comun_relata_public_projection_consents
       set active = false,
           withdrawn_at = coalesce(withdrawn_at, v_now)
     where case_id = v_context.case_id;

    select m.collective_case_id into v_collective_id
      from public.comun_relata_case_memberships m
     where m.individual_case_id = v_context.case_id
       and m.active
     order by m.created_at desc
     limit 1;

    if v_collective_id is not null then
      perform 1 from private.comun_relata_public_projection_recompute(v_collective_id);
    end if;

    insert into private.comun_participation_wallet_events(
      wallet_id, item_id, event_type, result_code
    ) values (
      v_context.wallet_id, p_wallet_item_id, 'item_updated',
      'WALLET_PUBLIC_PROJECTION_CONSENT_REVOKED'
    );
  end if;

  return query select * from public.comun_relata_public_projection_consent_status(
    p_token_hash_hex, p_wallet_item_id
  );
end;
$$;


ALTER FUNCTION public.comun_relata_public_projection_consent_set(p_token_hash_hex text, p_wallet_item_id uuid, p_active boolean) OWNER TO postgres;

--
-- Name: comun_relata_public_projection_consent_status(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_public_projection_consent_status(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(available boolean, active boolean, category text, location_ready boolean, grouping_ready boolean, result_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_active boolean := false;
  v_eligible boolean := false;
  v_available boolean := false;
  v_grouping_ready boolean := false;
begin
  select * into v_context
    from private.comun_relata_public_projection_owned_context(
      p_token_hash_hex, p_wallet_item_id
    );

  if not found then
    return query select false, false, null::text, false, false,
      'RELATA_PUBLIC_OPT_IN_NOT_AVAILABLE'::text;
    return;
  end if;

  v_eligible := coalesce((v_context.category in (
    'public_lighting', 'power_distribution', 'smoke_or_environmental_trace'
  )
  and v_context.case_state <> 'withdrawn'
  and v_context.report_withdrawn_at is null
    and v_context.urgency <> 'emergency'
    and v_context.privacy_class in ('public_safe', 'public_after_sanitization')
    and v_context.location_ready), false);

  select c.active into v_active
    from private.comun_relata_public_projection_consents c
    where c.case_id = v_context.case_id;

  -- An active consent remains revocable even if a later withdrawal or
  -- location change makes the report ineligible for future projection.
  v_available := v_eligible or coalesce(v_active, false);

  select exists(
    select 1
      from public.comun_relata_case_memberships m
     where m.individual_case_id = v_context.case_id
       and m.active
  ) into v_grouping_ready;

  return query select
    v_available,
    coalesce(v_active, false),
    case when v_available then v_context.category else null end,
    v_context.location_ready,
    v_grouping_ready,
    case when v_available
      then 'RELATA_PUBLIC_OPT_IN_STATUS_READY'
      else 'RELATA_PUBLIC_OPT_IN_NOT_AVAILABLE'
    end;
end;
$$;


ALTER FUNCTION public.comun_relata_public_projection_consent_status(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_relata_public_projection_owned_location(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_public_projection_owned_location(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(protocol text, category text, urgency text, privacy_class text, case_state text, report_withdrawn_at timestamp with time zone, captured_at timestamp with time zone, encrypted_value bytea, nonce bytea, auth_tag bytea, key_version text, evidence_state text, approximation_level text, geographic_risk text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  select
    c.protocol, c.category, c.urgency, r.privacy_class, c.state,
    r.withdrawn_at, l.captured_at, l.encrypted_value, l.nonce, l.auth_tag,
    l.key_version, l.evidence_state, l.approximation_level, l.geographic_risk
    from private.comun_participation_wallets w
    join private.comun_participation_wallet_items wi
      on wi.wallet_id=w.id
     and wi.id=p_wallet_item_id
     and wi.item_type='relata_report'
     and wi.archived_at is null
    join public.comun_relata_cases c on c.id::text=wi.subject_ref
    join private.comun_relata_reports r on r.id=c.report_id
    join private.comun_relata_private_locations l on l.report_id=r.id
   where p_token_hash_hex ~ '^[0-9a-f]{64}$'
     and w.token_hash=pg_catalog.decode(p_token_hash_hex,'hex')
     and w.status='active'
     and c.state<>'withdrawn'
     and r.withdrawn_at is null
     and l.evidence_state='added_private'
     and l.withdrawn_at is null;
$_$;


ALTER FUNCTION public.comun_relata_public_projection_owned_location(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_relata_reject_attachment(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_reject_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_rejection_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ begin update private.comun_relata_attachments a set state='rejected',rejection_code=left(p_rejection_code,80),updated_at=now() where a.id=p_attachment_id and a.report_id=(select report_id from private.comun_relata_authorized_context(p_protocol,p_receipt_secret)) and a.state in ('quarantine','validating'); return found; end; $$;


ALTER FUNCTION public.comun_relata_reject_attachment(p_protocol text, p_receipt_secret text, p_attachment_id uuid, p_rejection_code text) OWNER TO postgres;

--
-- Name: comun_relata_withdraw(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_relata_withdraw(p_protocol text, p_receipt_secret text) RETURNS TABLE(protocol text, state text, category text, urgency text, rule_version text, created_at timestamp with time zone, withdrawn_at timestamp with time zone, timeline jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_case public.comun_relata_cases%rowtype;
  v_report private.comun_relata_reports%rowtype;
  v_collective uuid;
begin
  if p_protocol !~ '^COMUN-RELATA-[A-F0-9]{16}$'
     or p_receipt_secret !~ '^[A-Za-z0-9_-]{32,160}$' then
    return;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_protocol,4801)
  );
  select * into v_case
    from public.comun_relata_cases
   where public.comun_relata_cases.protocol=p_protocol;
  if not found then return; end if;
  select * into v_report
    from private.comun_relata_reports report
   where report.id=v_case.report_id
     and report.receipt_hash=extensions.digest(
       'relata-receipt-v1:'||p_receipt_secret,'sha256'
     );
  if not found then return; end if;
  if v_case.state<>'withdrawn' then
    select collective_case_id into v_collective
      from public.comun_relata_case_memberships
     where individual_case_id=v_case.id and active
     for update;

    update public.comun_relata_cases
       set state='withdrawn',withdrawn_at=pg_catalog.now(),updated_at=pg_catalog.now()
     where id=v_case.id
     returning * into v_case;
    update private.comun_relata_reports
       set withdrawn_at=v_case.withdrawn_at,retention_class='withdrawn',
           review_after=v_case.withdrawn_at+interval '30 days'
     where id=v_report.id;
    update private.comun_relata_private_locations
       set evidence_state='withdrawn',withdrawn_at=v_case.withdrawn_at
     where report_id=v_report.id and evidence_state<>'withdrawn';
    update private.comun_relata_attachments attachment
       set state='withdrawn',withdrawn_at=v_case.withdrawn_at,
           retention_class='withdrawn_evidence',
           updated_at=pg_catalog.now()
     where attachment.report_id=v_report.id
       and attachment.state not in ('withdrawn','rejected');

    -- Memberships and match keys were reconciled by the AFTER trigger.  Do
    -- not update their count again here.
    if v_collective is not null then
      insert into public.comun_relata_case_match_events(
        individual_case_id,previous_collective_case_id,collective_case_id,
        decision,confidence_level,match_rule_version,result_code
      ) values(
        v_case.id,v_collective,v_collective,'withdrawn_unlinked','blocked',
        'relata-match-v1','RELATA_WITHDRAWAL_UNLINKED'
      );
    end if;
    insert into public.comun_relata_status_events(case_id,state,actor,result_code)
      values(v_case.id,'withdrawn','person','RELATA_WITHDRAWN_BY_HOLDER');
  end if;
  return query
    select receipt.*
      from public.comun_relata_get_receipt(p_protocol,p_receipt_secret) receipt;
end;
$_$;


ALTER FUNCTION public.comun_relata_withdraw(p_protocol text, p_receipt_secret text) OWNER TO postgres;

