    AS $$ declare x record; begin select * into x from private.comun_relata_authorized_context(p_protocol,p_receipt_secret); if not found then return false; end if; update private.comun_relata_private_locations set evidence_state='withdrawn',withdrawn_at=coalesce(withdrawn_at,now()) where report_id=x.report_id; return found; end; $$;


