--
-- Name: comun_request_solidarity_organization_access(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_request_solidarity_organization_access(p_organization_territory_id uuid, p_member_user_id uuid, p_request_note_private text) RETURNS TABLE(access_id uuid, requested_role text, review_scope text, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_existing private.comun_solidarity_organization_access%rowtype;
  v_role text;
  v_scope text;
  v_now timestamptz := clock_timestamp();
begin
  if p_member_user_id is null or not exists(select 1 from auth.users u where u.id = p_member_user_id) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_AUTH_REQUIRED';
  end if;
  p_request_note_private := btrim(coalesce(p_request_note_private, ''));
  if char_length(p_request_note_private) not between 10 and 600 then
    raise exception 'COMUN_SOLIDARITY_ACCESS_NOTE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('comun-solidarity-organization:' || p_organization_territory_id::text, 0));

  if not exists (
    select 1
    from public.comun_territorial_organizations organization
    join public.comun_hub_territories territory on territory.id = organization.territory_id
    where organization.territory_id = p_organization_territory_id
      and organization.status in ('active','forming')
      and organization.verification_status in ('source_checked','verified')
      and territory.visibility = 'public'
      and territory.status in ('active','monitoring')
      and territory.verification_status in ('source_checked','verified')
  ) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_ORGANIZATION_INELIGIBLE';
  end if;

  select access.* into v_existing
  from private.comun_solidarity_organization_access access
  where access.organization_territory_id = p_organization_territory_id
    and access.member_user_id = p_member_user_id
    and access.state in ('pending','active')
  order by access.requested_at desc
  limit 1;
  if found then
    return query select v_existing.id, v_existing.requested_role, v_existing.review_scope, v_existing.state, true;
    return;
  end if;

  if exists (
    select 1 from private.comun_solidarity_organization_access access
    where access.organization_territory_id = p_organization_territory_id
      and access.member_user_id = p_member_user_id
      and access.state in ('rejected','revoked')
      and access.updated_at > v_now - interval '24 hours'
  ) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_COOLDOWN';
  end if;
  if (select count(*) from private.comun_solidarity_organization_access access
      where access.member_user_id = p_member_user_id and access.state = 'pending') >= 5 then
    raise exception 'COMUN_SOLIDARITY_ACCESS_PENDING_LIMIT';
  end if;
  if (select count(*) from private.comun_solidarity_organization_access access
      where access.member_user_id = p_member_user_id and access.requested_at >= v_now - interval '24 hours') >= 10 then
    raise exception 'COMUN_SOLIDARITY_ACCESS_DAILY_LIMIT';
  end if;

  if exists (
    select 1 from private.comun_solidarity_organization_access access
    where access.organization_territory_id = p_organization_territory_id
      and access.state = 'active' and access.role = 'facilitator'
  ) then
    v_role := 'editor';
    v_scope := 'organization';
  else
    v_role := 'facilitator';
    v_scope := 'platform';
  end if;

  insert into private.comun_solidarity_organization_access(
    organization_territory_id,
    member_user_id,
    requested_role,
    review_scope,
    request_note_private,
    transition_history_private
  ) values (
    p_organization_territory_id,
    p_member_user_id,
    v_role,
    v_scope,
    p_request_note_private,
    jsonb_build_array(jsonb_build_object(
      'event', 'requested',
      'actorUserId', p_member_user_id,
      'requestedRole', v_role,
      'reviewScope', v_scope,
      'at', v_now
    ))
  ) returning id into access_id;
  requested_role := v_role;
  review_scope := v_scope;
  state := 'pending';
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_request_solidarity_organization_access(p_organization_territory_id uuid, p_member_user_id uuid, p_request_note_private text) OWNER TO postgres;

--
-- Name: comun_review_solidarity_connection_v1(text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_review_solidarity_connection_v1(p_subject_kind text, p_interest_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_decision text) RETURNS TABLE(connection_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_access private.comun_solidarity_organization_access%rowtype;
  v_org uuid;
  v_subject_archived boolean;
  v_now timestamptz:=clock_timestamp();
begin
  if p_subject_kind not in ('offer','need') or p_decision not in ('accept','reject') then raise exception 'COMUN_SOLIDARITY_CONNECTION_REVIEW_INVALID'; end if;
  select * into v_access from private.comun_solidarity_organization_access
    where organization_territory_id=p_expected_organization_territory_id and member_user_id=p_actor_user_id and state='active' and role in ('editor','facilitator')
    order by activated_at desc limit 1;
  if not found then raise exception 'COMUN_SOLIDARITY_CONNECTION_REVIEW_FORBIDDEN'; end if;
  if p_subject_kind='offer' then
    select interest.organization_territory_id,(offer.status='archived') into v_org,v_subject_archived
      from private.comun_solidarity_offer_interests interest join public.comun_solidarity_offers offer on offer.id=interest.offer_id
      where interest.id=p_interest_id and interest.state='pending' for update of interest;
  else
    select need.organization_territory_id,(need.status='archived') into v_org,v_subject_archived
      from public.comun_territorial_need_interests interest join public.comun_territorial_needs need on need.id=interest.need_id
      where interest.id=p_interest_id and interest.status in ('pending','contacted') for update of interest;
  end if;
  if not found then raise exception 'COMUN_SOLIDARITY_CONNECTION_NOT_PENDING'; end if;
  if v_org is null or v_org<>p_expected_organization_territory_id then raise exception 'COMUN_SOLIDARITY_CONNECTION_ORGANIZATION_MISMATCH'; end if;
  if p_decision='accept' then
    if v_subject_archived then raise exception 'COMUN_SOLIDARITY_CONNECTION_SUBJECT_ARCHIVED'; end if;
    if not exists(
      select 1 from public.comun_territorial_organizations organization join public.comun_hub_territories territory on territory.id=organization.territory_id
      where organization.territory_id=v_org and organization.status in ('active','forming') and organization.verification_status in ('source_checked','verified')
        and territory.visibility='public' and territory.status in ('active','monitoring') and territory.verification_status in ('source_checked','verified')
    ) then raise exception 'COMUN_SOLIDARITY_CONNECTION_ORGANIZATION_INELIGIBLE'; end if;
    if p_subject_kind='offer' then
      update private.comun_solidarity_offer_interests set state='accepted',reviewed_by_access_id=v_access.id,reviewed_at=v_now,accepted_at=v_now where id=p_interest_id;
    else
      update public.comun_territorial_need_interests set status='accepted',reviewed_by_access_id=v_access.id,reviewed_at=v_now,accepted_at=v_now where id=p_interest_id;
    end if;
    return query select 'accepted'::text;
  else
    if p_subject_kind='offer' then
      update private.comun_solidarity_offer_interests set state='rejected',contact_private=null,consent_to_contact=false,reviewed_by_access_id=v_access.id,reviewed_at=v_now,rejected_at=v_now where id=p_interest_id;
    else
      update public.comun_territorial_need_interests set status='rejected',contact_private=null,consent_to_contact=false,reviewed_by_access_id=v_access.id,reviewed_at=v_now,rejected_at=v_now where id=p_interest_id;
    end if;
    return query select 'rejected'::text;
  end if;
end;
$$;


ALTER FUNCTION public.comun_review_solidarity_connection_v1(p_subject_kind text, p_interest_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_decision text) OWNER TO postgres;

--
-- Name: comun_review_solidarity_organization_access(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_review_solidarity_organization_access(p_access_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_decision text, p_review_note_private text DEFAULT NULL::text) RETURNS TABLE(access_id uuid, organization_territory_id uuid, state text, role text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_access private.comun_solidarity_organization_access%rowtype;
  v_now timestamptz := clock_timestamp();
  v_platform_actor boolean := false;
begin
  if p_decision not in ('approve','reject') then
    raise exception 'COMUN_SOLIDARITY_ACCESS_DECISION_INVALID';
  end if;
  p_review_note_private := nullif(btrim(coalesce(p_review_note_private, '')), '');
  if p_review_note_private is not null and char_length(p_review_note_private) > 600 then
    raise exception 'COMUN_SOLIDARITY_ACCESS_REVIEW_NOTE_INVALID';
  end if;

  select access.* into v_access
  from private.comun_solidarity_organization_access access
  where access.id = p_access_id
  for update;
  if not found or v_access.state <> 'pending' then
    raise exception 'COMUN_SOLIDARITY_ACCESS_NOT_PENDING';
  end if;
  if v_access.organization_territory_id <> p_expected_organization_territory_id then
    raise exception 'COMUN_SOLIDARITY_ACCESS_ORGANIZATION_MISMATCH';
  end if;

  select exists(
    select 1 from public.comun_admin_users admin_user
    where admin_user.user_id = p_actor_user_id
      and admin_user.is_active = true
      and admin_user.role in ('admin','editor')
  ) into v_platform_actor;

  if v_access.review_scope = 'platform' then
    if not v_platform_actor then
      raise exception 'COMUN_SOLIDARITY_ACCESS_PLATFORM_REVIEW_FORBIDDEN';
    end if;
  elsif not exists (
    select 1 from private.comun_solidarity_organization_access actor_access
    where actor_access.organization_territory_id = v_access.organization_territory_id
      and actor_access.member_user_id = p_actor_user_id
      and actor_access.state = 'active'
      and actor_access.role = 'facilitator'
  ) then
    raise exception 'COMUN_SOLIDARITY_ACCESS_ORGANIZATION_REVIEW_FORBIDDEN';
  end if;

  update private.comun_solidarity_organization_access access
  set state = case when p_decision = 'approve' then 'active' else 'rejected' end,
      role = case when p_decision = 'approve' then access.requested_role else null end,
      reviewed_by_user_id = p_actor_user_id,
      review_note_private = p_review_note_private,
      reviewed_at = v_now,
      activated_at = case when p_decision = 'approve' then v_now else null end,
      transition_history_private = access.transition_history_private || jsonb_build_array(jsonb_build_object(
        'event', case when p_decision = 'approve' then 'approved' else 'rejected' end,
        'actorUserId', p_actor_user_id,
        'at', v_now
      ))
  where access.id = p_access_id
  returning access.id, access.organization_territory_id, access.state, access.role
  into access_id, organization_territory_id, state, role;
  return next;
end;
$$;


ALTER FUNCTION public.comun_review_solidarity_organization_access(p_access_id uuid, p_expected_organization_territory_id uuid, p_actor_user_id uuid, p_decision text, p_review_note_private text) OWNER TO postgres;

--
-- Name: comun_review_solidarity_organization_onboarding_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_review_solidarity_organization_onboarding_v1(p_request_id uuid, p_onboarding_id uuid, p_actor_user_id uuid, p_decision text, p_review_message_private text) RETURNS TABLE(onboarding_id uuid, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_onboarding private.comun_solidarity_organization_onboarding%rowtype;
  v_message text;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  perform private.comun_solidarity_onboarding_assert_admin(p_actor_user_id);
  if p_decision not in ('needs_changes','reject') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_REVIEW_DECISION_INVALID';
  end if;
  v_message := pg_catalog.btrim(coalesce(p_review_message_private, ''));
  if pg_catalog.char_length(v_message) not between 3 and 600 then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_REVIEW_MESSAGE_INVALID';
  end if;
  select onboarding.* into v_onboarding
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.id = p_onboarding_id
  for update;
  if not found then raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_FOUND'; end if;
  if v_onboarding.last_mutation_request_id = p_request_id then
    return query select v_onboarding.id, v_onboarding.state, true;
    return;
  end if;
  if v_onboarding.state <> 'submitted' then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_SUBMITTED';
  end if;
  update private.comun_solidarity_organization_onboarding onboarding set
    state = case when p_decision = 'needs_changes' then 'needs_changes' else 'rejected' end,
    review_message_private = v_message, reviewed_by_user_id = p_actor_user_id,
    reviewed_at = v_now, last_mutation_request_id = p_request_id,
    transition_history_private = onboarding.transition_history_private || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('event', p_decision, 'actorUserId', p_actor_user_id, 'at', v_now)
    )
  where onboarding.id = v_onboarding.id
  returning onboarding.id, onboarding.state into onboarding_id, state;
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_review_solidarity_organization_onboarding_v1(p_request_id uuid, p_onboarding_id uuid, p_actor_user_id uuid, p_decision text, p_review_message_private text) OWNER TO postgres;

--
-- Name: comun_route_cultural_contribution_intake_v1(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_route_cultural_contribution_intake_v1(p_public_protocol text, p_route_kind text, p_resume_token_hash text DEFAULT NULL::text, p_member_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(intake_id uuid, public_protocol text, status text, route_kind text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'extensions'
    AS $$
declare v private.comun_cultural_contribution_intakes%rowtype;
begin
  if p_route_kind not in ('photo_or_document','art','oral_history','radio','unknown') then raise exception 'invalid_route'; end if;
  select i.* into v from private.comun_cultural_contribution_intakes i
   where i.public_protocol=p_public_protocol
     and ((p_resume_token_hash is not null and i.resume_token_hash=p_resume_token_hash)
       or (p_member_user_id is not null and i.member_user_id=p_member_user_id))
   limit 1 for update;
  if v.id is null then return; end if;
  if v.route_kind is not null and v.route_kind <> p_route_kind and v.route_kind <> 'unknown' then raise exception 'route_locked'; end if;
  update private.comun_cultural_contribution_intakes
     set route_kind=p_route_kind,
         status=case when p_route_kind='unknown' then 'routing' else coalesce(nullif(v.status,'draft'),'routed') end,
         routed_at=coalesce(routed_at,now()), updated_at=now()
   where id=v.id returning * into v;
  return query select v.id,v.public_protocol,v.status,v.route_kind;
end $$;


ALTER FUNCTION public.comun_route_cultural_contribution_intake_v1(p_public_protocol text, p_route_kind text, p_resume_token_hash text, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: comun_sensitive_assisted_list(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sensitive_assisted_list(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(package_id uuid, state text, category text, policy_identifier text, disclosure_manifest jsonb, subject text, institutional_text text, response_expectation text, attempts jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select p.id,p.state,c.category,p.policy_identifier,p.disclosure_manifest,
    p.subject,p.institutional_text,p.response_expectation,
    coalesce((select jsonb_agg(jsonb_build_object(
      'attemptId',a.id,'sequence',a.sequence_no,'channel',a.channel,
      'institutionalChannelId',a.institutional_channel_id,'state',a.state,
      'openedAt',a.opened_at,'declaredAt',a.declared_at,'dueAt',a.due_at,
      'officialProtocolMasked',case when a.official_protocol is null then null else left(a.official_protocol,3)||'••••' end,
      'respondedAt',a.responded_at,'resolutionOutcome',a.resolution_outcome
    ) order by a.sequence_no) from private.comun_forwarding_attempts a where a.package_id=p.id),'[]'::jsonb)
  from private.comun_forwarding_packages p
  join public.comun_relata_cases c on c.id=p.relata_case_id
  join private.comun_participation_wallet_items wi
    on wi.wallet_id=p.wallet_id and wi.subject_ref=p.relata_case_id::text
    and wi.item_type='relata_report' and wi.archived_at is null
  where p.wallet_id=private.comun_assisted_wallet_id(p_token_hash_hex)
    and wi.id=p_wallet_item_id and p.source_domain='sensitive_service'
    and p.withdrawn_at is null;
$$;


ALTER FUNCTION public.comun_sensitive_assisted_list(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_sensitive_assisted_prepare(text, uuid, boolean, boolean, text, boolean, text, boolean, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sensitive_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid, p_include_issue_type boolean, p_include_unit_label boolean, p_unit_label text, p_include_network_label boolean, p_network_label text, p_include_approximate_period boolean, p_approximate_period text, p_include_person_authored_summary boolean, p_person_authored_summary text, p_authorization_confirmed boolean) RETURNS TABLE(package_id uuid, state text, category text, policy_identifier text, disclosure_manifest jsonb, subject text, institutional_text text, response_expectation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_wallet uuid;
  v_case public.comun_relata_cases%rowtype;
  v_package private.comun_forwarding_packages%rowtype;
  v_policy text;
  v_issue_type text;
  v_issue_label text;
  v_subject text;
  v_body text;
  v_manifest jsonb;
  v_channel_only boolean;
  v_unit text:=nullif(trim(coalesce(p_unit_label,'')),'');
  v_network text:=nullif(trim(coalesce(p_network_label,'')),'');
  v_period text:=nullif(trim(coalesce(p_approximate_period,'')),'');
  v_summary text:=nullif(trim(coalesce(p_person_authored_summary,'')),'');
begin
  if p_authorization_confirmed is not true then return; end if;
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;

  select c.* into v_case
  from private.comun_participation_wallet_items wi
  join public.comun_relata_cases c on c.id=wi.subject_ref::uuid
  where wi.id=p_wallet_item_id and wi.wallet_id=v_wallet
    and wi.item_type='relata_report' and wi.archived_at is null
    and c.category in ('public_health','public_education','child_protection')
    and c.state<>'withdrawn';
  if not found then return; end if;

  if char_length(coalesce(v_unit,''))>120
    or char_length(coalesce(v_network,''))>40
    or char_length(coalesce(v_period,''))>80
    or char_length(coalesce(v_summary,''))>1000 then return; end if;

  v_policy:=case v_case.category
    when 'public_health' then 'health_minimal_v1'
    when 'public_education' then 'education_minimal_v1'
    else 'child_protection_channel_only_v1' end;
  v_channel_only:=v_case.category='child_protection';

  if v_channel_only and (
    coalesce(p_include_issue_type,false)
    or coalesce(p_include_unit_label,false)
    or coalesce(p_include_network_label,false)
    or coalesce(p_include_approximate_period,false)
    or coalesce(p_include_person_authored_summary,false)
    or v_unit is not null or v_network is not null or v_period is not null or v_summary is not null
  ) then return; end if;

  if p_include_unit_label is true and v_unit is null then return; end if;
  if p_include_network_label is true and v_network is null then return; end if;
  if p_include_approximate_period is true and v_period is null then return; end if;
  if p_include_person_authored_summary is true and v_summary is null then return; end if;
  if p_include_unit_label is not true then v_unit:=null; end if;
  if p_include_network_label is not true then v_network:=null; end if;
  if p_include_approximate_period is not true then v_period:=null; end if;
  if p_include_person_authored_summary is not true then v_summary:=null; end if;

  v_issue_type:=case v_case.category
    when 'public_health' then nullif(v_case.routing_decision->>'healthIssueType','')
    when 'public_education' then nullif(v_case.routing_decision->>'educationIssueType','')
    else null end;
  v_issue_label:=case v_case.category||':'||coalesce(v_issue_type,'')
    when 'public_health:access_or_waiting' then 'Atendimento ou demora'
    when 'public_health:exam_or_procedure' then 'Exame, procedimento ou cirurgia'
    when 'public_health:medicine_or_supply' then 'Medicamento ou insumo'
    when 'public_health:staff_or_service_availability' then 'Falta de profissional ou serviço'
    when 'public_health:facility_or_accessibility' then 'Estrutura ou acessibilidade'
    when 'public_health:care_conduct' then 'Conduta no atendimento'
    when 'public_health:transfer_or_health_transport' then 'Transferência ou transporte sanitário'
    when 'public_health:information_or_followup' then 'Informação ou acompanhamento'
    when 'public_health:other_health_service' then 'Outro problema no SUS'
    when 'public_education:staff_or_service_availability' then 'Falta de profissional ou serviço'
    when 'public_education:infrastructure_or_climate' then 'Estrutura ou climatização'
    when 'public_education:school_meals_or_supplies' then 'Merenda, material ou insumo'
    when 'public_education:school_transport_or_access' then 'Transporte ou acesso à escola'
    when 'public_education:accessibility_or_inclusion' then 'Acessibilidade ou inclusão'
    when 'public_education:enrollment_or_attendance' then 'Matrícula, vaga ou permanência'
    when 'public_education:discrimination_or_bullying' then 'Discriminação ou bullying'
    when 'public_education:information_or_management' then 'Informação ou gestão escolar'
    when 'public_education:other_education_service' then 'Outro problema na Educação'
    else null end;
  if p_include_issue_type is true and v_issue_label is null then return; end if;

  v_manifest:=jsonb_build_object(
    'policy',v_policy,
    'includeIssueType',coalesce(p_include_issue_type,false),
    'includeUnitLabel',coalesce(p_include_unit_label,false),
    'includeNetworkLabel',coalesce(p_include_network_label,false),
    'includeApproximatePeriod',coalesce(p_include_approximate_period,false),
    'includePersonAuthoredSummary',coalesce(p_include_person_authored_summary,false),
    'channelOnly',v_channel_only
  );
  v_subject:=case v_case.category
    when 'public_health' then 'Manifestação sobre Saúde pública'
    when 'public_education' then 'Manifestação sobre Educação pública'
    else 'Canal de proteção escolhido pela pessoa' end;
  v_body:=case when v_channel_only
    then 'Conteúdo será informado diretamente pela pessoa ao canal.'
    else 'Quero registrar uma manifestação sobre '
      ||case when v_case.category='public_health' then 'Saúde pública.' else 'Educação pública.' end
      ||case when p_include_issue_type is true then E'\nTipo do problema: '||v_issue_label else '' end
      ||case when v_unit is not null then E'\nUnidade informada para este encaminhamento: '||v_unit else '' end
      ||case when v_network is not null then E'\nRede informada para este encaminhamento: '||v_network else '' end
      ||case when v_period is not null then E'\nPeríodo aproximado: '||v_period else '' end
      ||case when v_summary is not null then E'\nMensagem escrita para este encaminhamento: '||v_summary else '' end
    end;

  perform pg_advisory_xact_lock(hashtextextended(v_case.id::text,4812));
  select * into v_package from private.comun_forwarding_packages
    where wallet_id=v_wallet and relata_case_id=v_case.id and withdrawn_at is null for update;
  if found then
    if v_package.source_domain<>'sensitive_service'
      or v_package.disclosure_manifest<>v_manifest
      or v_package.institutional_text<>v_body then return; end if;
    return query select v_package.id,v_package.state,v_case.category,
      v_package.policy_identifier,v_package.disclosure_manifest,v_package.subject,
      v_package.institutional_text,v_package.response_expectation;
    return;
  end if;

  insert into private.comun_forwarding_packages(
    wallet_id,relata_case_id,bus_intake_id,source_domain,state,subject,
    institutional_text,response_expectation,policy_identifier,policy_version,
    disclosure_manifest
  ) values(
    v_wallet,v_case.id,null,'sensitive_service','ready_for_forwarding',v_subject,
    v_body,'Nenhum prazo institucional foi presumido pelo COMUN.',v_policy,1,
    v_manifest
  ) returning * into v_package;
  update private.comun_participation_wallet_items set
    presentation_state='Encaminhamento preparado',
    action_required='Revisar e abrir o canal escolhido',updated_at=now()
  where id=p_wallet_item_id and wallet_id=v_wallet;
  insert into private.comun_forwarding_events(package_id,event_type,result_code)
    values(v_package.id,'package_prepared','FORWARDING_SENSITIVE_PACKAGE_PREPARED');
  return query select v_package.id,v_package.state,v_case.category,
    v_package.policy_identifier,v_package.disclosure_manifest,v_package.subject,
    v_package.institutional_text,v_package.response_expectation;
end;
$$;


ALTER FUNCTION public.comun_sensitive_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid, p_include_issue_type boolean, p_include_unit_label boolean, p_unit_label text, p_include_network_label boolean, p_network_label text, p_include_approximate_period boolean, p_approximate_period text, p_include_person_authored_summary boolean, p_person_authored_summary text, p_authorization_confirmed boolean) OWNER TO postgres;

--
-- Name: comun_sensitive_assisted_record_response(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sensitive_assisted_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_outcome text, p_response_note text, p_official_protocol text) RETURNS TABLE(attempt_id uuid, attempt_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_wallet uuid; v_attempt private.comun_forwarding_attempts%rowtype;
  v_category text; v_note text:=nullif(trim(coalesce(p_response_note,'')),'');
  v_stored_note text; v_no_return boolean:=p_response_outcome='no_return';
begin
  if p_response_outcome not in ('return_received','no_return','situation_forwarded','prefer_not_to_record_details')
    or char_length(coalesce(v_note,''))>280
    or char_length(coalesce(p_official_protocol,''))>240 then return; end if;
  v_wallet:=private.comun_assisted_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;
  select a.* into v_attempt
  from private.comun_forwarding_attempts a
  join private.comun_forwarding_packages p on p.id=a.package_id
  join public.comun_relata_cases c on c.id=p.relata_case_id
  where a.id=p_attempt_id and p.wallet_id=v_wallet and p.source_domain='sensitive_service'
    and p.withdrawn_at is null and a.state in ('person_declared_sent','no_response') for update of a;
  if not found then return; end if;
  select c.category into v_category from private.comun_forwarding_packages p
    join public.comun_relata_cases c on c.id=p.relata_case_id where p.id=v_attempt.package_id;
  if v_category='child_protection' and v_note is not null then return; end if;
  v_stored_note:=case when v_category='child_protection' then p_response_outcome
    else coalesce(v_note,p_response_outcome) end;
  update private.comun_forwarding_attempts set
    state=case when v_no_return then 'no_response' else 'responded' end,
    resolution_outcome=case when p_response_outcome='situation_forwarded' then 'unresolved' else null end,
    response_note=v_stored_note,
    official_protocol=nullif(trim(coalesce(p_official_protocol,'')),''),
    responded_at=case when v_no_return then null else now() end,updated_at=now()
  where id=p_attempt_id;
  update private.comun_forwarding_packages set
    state=case when v_no_return then 'waiting_response' else 'responded' end,updated_at=now()
    where id=v_attempt.package_id;
  update private.comun_participation_wallet_items wi set
    presentation_state=case
      when v_no_return then 'Aguardando retorno'
      when p_response_outcome='situation_forwarded' then 'Resposta não resolveu'
      else 'Resposta registrada' end,
    action_required=case
      when v_no_return then 'Acompanhar retorno'
      when p_response_outcome='situation_forwarded' then 'Ver próximo passo'
      else 'Revise o resultado' end,
    updated_at=now()
  from private.comun_forwarding_packages p
  where p.id=v_attempt.package_id and wi.wallet_id=p.wallet_id
    and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report' and wi.archived_at is null;
  insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code)
    values(v_attempt.package_id,p_attempt_id,'response_recorded',case
      when v_no_return then 'FORWARDING_SENSITIVE_NO_RETURN'
      when p_response_outcome='situation_forwarded' then 'FORWARDING_RESPONSE_NOT_RESOLVED'
      else 'FORWARDING_SENSITIVE_RESPONSE_RECORDED' end);
  return query select p_attempt_id,case when v_no_return then 'no_response' else 'responded' end;
end;
$$;


ALTER FUNCTION public.comun_sensitive_assisted_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_outcome text, p_response_note text, p_official_protocol text) OWNER TO postgres;

--
-- Name: comun_sensitive_wallet_item_context(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sensitive_wallet_item_context(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(category text, issue_type text, immediate_danger boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select c.category,
    case c.category
      when 'public_health' then nullif(c.routing_decision->>'healthIssueType','')
      when 'public_education' then nullif(c.routing_decision->>'educationIssueType','')
      else nullif(c.routing_decision->>'childProtectionIssueType','') end,
    coalesce((c.routing_decision->>'immediateDanger')::boolean,false)
  from private.comun_participation_wallet_items wi
  join public.comun_relata_cases c on c.id=wi.subject_ref::uuid
  where wi.id=p_wallet_item_id
    and wi.wallet_id=private.comun_assisted_wallet_id(p_token_hash_hex)
    and wi.item_type='relata_report' and wi.archived_at is null
    and c.category in ('public_health','public_education','child_protection')
    and c.state<>'withdrawn';
$$;


ALTER FUNCTION public.comun_sensitive_wallet_item_context(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_sidewalk_intake_admin_list(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sidewalk_intake_admin_list(p_intake_id uuid DEFAULT NULL::uuid) RETURNS TABLE(intake_id uuid, protocol text, original_text text, condition text, problems text[], affected_groups text[], review_state text, created_at timestamp with time zone, location_origin text, location_accuracy_class text, location_captured_at timestamp with time zone, location_ciphertext bytea, location_nonce bytea, location_auth_tag bytea, location_key_version text, attachment_id uuid, attachment_derivative_object_key text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select
    i.id,
    c.protocol,
    r.original_text,
    i.condition,
    i.problems,
    i.affected_groups,
    i.review_state,
    i.created_at,
    l.origin,
    l.accuracy_class,
    l.captured_at,
    l.encrypted_value,
    l.nonce,
    l.auth_tag,
    l.key_version,
    a.id,
    a.derivative_object_key
  from private.comun_sidewalk_relata_intakes i
  join private.comun_relata_reports r on r.id = i.report_id
  join public.comun_relata_cases c on c.id = i.case_id
  join private.comun_relata_private_locations l
    on l.report_id = i.report_id
   and l.evidence_state = 'added_private'
   and l.withdrawn_at is null
  left join lateral (
    select aa.id, aa.derivative_object_key
    from private.comun_relata_attachments aa
    where aa.report_id = i.report_id and aa.state = 'sealed_private'
    order by aa.label_index
    limit 1
  ) a on true
  where i.review_state in ('pending_review','needs_information')
    and (p_intake_id is null or i.id = p_intake_id)
  order by i.created_at, i.id;
$$;


ALTER FUNCTION public.comun_sidewalk_intake_admin_list(p_intake_id uuid) OWNER TO postgres;

--
-- Name: comun_sidewalk_intake_create(text, text, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sidewalk_intake_create(p_protocol text, p_receipt_secret text, p_condition text, p_problems text[], p_affected_groups text[]) RETURNS TABLE(intake_id uuid, review_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_intake private.comun_sidewalk_relata_intakes%rowtype;
begin
  select * into v_context
    from private.comun_relata_authorized_context(p_protocol, p_receipt_secret);

  if not found
    or v_context.category <> 'sidewalk_accessibility'
    or v_context.case_state = 'withdrawn'
    or p_condition not in ('good','regular','bad','terrible')
    or not private.comun_sidewalk_validate_text_array(
      p_problems,
      array['hole','irregular','no_ramp','obstacle','narrow','no_sidewalk']::text[],
      6
    )
    or not private.comun_sidewalk_validate_text_array(
      p_affected_groups,
      array['wheelchair_users','visual_impairment','older_people','children','strollers','temporary_mobility','general_circulation']::text[],
      7
    )
  then
    return;
  end if;

  insert into private.comun_sidewalk_relata_intakes as existing(
    report_id, case_id, condition, problems, affected_groups
  ) values (
    v_context.report_id, v_context.case_id, p_condition, p_problems, p_affected_groups
  )
  on conflict (report_id) do update
    set updated_at = existing.updated_at
  returning * into v_intake;

  return query select v_intake.id, v_intake.review_state;
end;
$$;


ALTER FUNCTION public.comun_sidewalk_intake_create(p_protocol text, p_receipt_secret text, p_condition text, p_problems text[], p_affected_groups text[]) OWNER TO postgres;

--
-- Name: comun_sidewalk_intake_finalize(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sidewalk_intake_finalize(p_protocol text, p_receipt_secret text) RETURNS TABLE(intake_id uuid, review_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_context record;
  v_intake private.comun_sidewalk_relata_intakes%rowtype;
begin
  select * into v_context
    from private.comun_relata_authorized_context(p_protocol, p_receipt_secret);
  if not found or v_context.category <> 'sidewalk_accessibility' or v_context.case_state = 'withdrawn' then
    return;
  end if;

  select * into v_intake
    from private.comun_sidewalk_relata_intakes
    where report_id = v_context.report_id
    for update;
  if not found then return; end if;

  if not exists (
    select 1 from private.comun_relata_private_locations
    where report_id = v_context.report_id
      and evidence_state = 'added_private'
      and withdrawn_at is null
  ) then
    return;
  end if;

  if v_intake.review_state = 'evidence_pending' then
    update private.comun_sidewalk_relata_intakes
      set review_state = 'pending_review', updated_at = now()
      where id = v_intake.id
      returning * into v_intake;

    update private.comun_participation_wallet_items
      set presentation_state = 'Em revisão',
          action_required = null,
          metadata = metadata || jsonb_build_object(
            'sidewalkIntake', true,
            'sidewalkReviewState', 'pending_review'
          ),
          updated_at = now()
      where item_type = 'relata_report'
        and subject_ref = v_context.case_id::text
        and archived_at is null;
  end if;

  return query select v_intake.id, v_intake.review_state;
end;
$$;


ALTER FUNCTION public.comun_sidewalk_intake_finalize(p_protocol text, p_receipt_secret text) OWNER TO postgres;

--
-- Name: comun_sidewalk_intake_review(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sidewalk_intake_review(p_intake_id uuid, p_decision text, p_public_summary text DEFAULT NULL::text, p_public_geometry jsonb DEFAULT NULL::jsonb) RETURNS TABLE(intake_id uuid, review_state text, published_record_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_intake private.comun_sidewalk_relata_intakes%rowtype;
  v_pauta_id uuid;
  v_record_id uuid;
  v_slug text;
  v_wallet_state text;
  v_action text;
begin
  if p_decision not in ('publish_approximate','needs_information','reject','withdraw') then
    raise exception using errcode = '22023', message = 'COMUN_SIDEWALK_INVALID_REVIEW_DECISION';
  end if;

  select * into v_intake
    from private.comun_sidewalk_relata_intakes
    where id = p_intake_id
    for update;
  if not found or v_intake.review_state in ('rejected','published','withdrawn') then return; end if;

  if exists (
    select 1 from public.comun_relata_cases
    where id = v_intake.case_id and state = 'withdrawn'
  ) then
    p_decision := 'withdraw';
  end if;

  if p_decision = 'publish_approximate' then
    if p_public_summary is null
      or char_length(trim(p_public_summary)) not between 16 and 800
      or p_public_geometry is null
      or jsonb_typeof(p_public_geometry) <> 'object'
      or p_public_geometry->>'type' <> 'Point'
      or p_public_geometry ? 'properties'
    then
      raise exception using errcode = '22023', message = 'COMUN_SIDEWALK_INVALID_PUBLIC_PROJECTION';
    end if;
    if jsonb_typeof(p_public_geometry->'coordinates') <> 'array' then
      raise exception using errcode = '22023', message = 'COMUN_SIDEWALK_INVALID_PUBLIC_PROJECTION';
    end if;
    if jsonb_array_length(p_public_geometry->'coordinates') <> 2
      or jsonb_typeof(p_public_geometry->'coordinates'->0) <> 'number'
      or jsonb_typeof(p_public_geometry->'coordinates'->1) <> 'number'
      or abs((p_public_geometry->'coordinates'->0)::numeric) > 180
      or abs((p_public_geometry->'coordinates'->1)::numeric) > 90
    then
      raise exception using errcode = '22023', message = 'COMUN_SIDEWALK_INVALID_PUBLIC_PROJECTION';
    end if;

    select id into v_pauta_id from public.comun_pauta_spaces
      where slug = 'calcadas-em-circulacao' limit 1;
    if v_pauta_id is null then
      raise exception using errcode = '23503', message = 'COMUN_SIDEWALK_PAUTA_MISSING';
    end if;

    v_slug := 'registro-revisado-' || replace(v_intake.id::text, '-', '');
    insert into public.comun_sidewalk_records(
      pauta_id, slug, name, geometry_geojson, private_geometry_geojson,
      public_geometry_geojson, categories, impact_level, affected_groups,
      status, verification_status, visibility, public_summary,
      private_notes, public_location_level, location_source,
      location_precision, condition, submitter_is_anonymous,
      geographic_risk, forwarding_status, last_observed_at
    ) values (
      v_pauta_id, v_slug, 'Trecho de calçada revisado', null, null,
      p_public_geometry, v_intake.problems,
      case when v_intake.condition = 'terrible' then 'critical'
           when v_intake.condition = 'bad' then 'high'
           when v_intake.condition = 'regular' then 'medium'
           else 'low' end,
      v_intake.affected_groups,
      'published', 'verified', 'public', trim(p_public_summary),
      null, 'approximate', 'editorial', 'approximate', v_intake.condition,
      true, 'low', 'no_action', now()
    ) returning id into v_record_id;

    update private.comun_sidewalk_relata_intakes
      set review_state = 'published', published_record_id = v_record_id,
          reviewed_at = now(), updated_at = now()
      where id = v_intake.id;
    v_wallet_state := 'Publicado no mapa';
    v_action := null;
  elsif p_decision = 'needs_information' then
    update private.comun_sidewalk_relata_intakes
      set review_state = 'needs_information', reviewed_at = now(), updated_at = now()
      where id = v_intake.id;
    v_wallet_state := 'Precisa de complemento';
    v_action := 'Completar informações da calçada';
  elsif p_decision = 'reject' then
    update private.comun_sidewalk_relata_intakes
      set review_state = 'rejected', reviewed_at = now(), updated_at = now()
      where id = v_intake.id;
    v_wallet_state := 'Guardado';
    v_action := null;
  else
    update private.comun_sidewalk_relata_intakes
      set review_state = 'withdrawn', reviewed_at = now(), updated_at = now()
      where id = v_intake.id;
    v_wallet_state := 'Retirado';
    v_action := null;
  end if;

  update private.comun_participation_wallet_items
    set presentation_state = v_wallet_state,
        action_required = v_action,
        metadata = metadata || jsonb_build_object(
          'sidewalkIntake', true,
          'sidewalkReviewState', case
            when p_decision = 'publish_approximate' then 'published'
            when p_decision = 'reject' then 'rejected'
            when p_decision = 'withdraw' then 'withdrawn'
            else 'needs_information'
          end
        ),
        updated_at = now()
    where item_type = 'relata_report'
      and subject_ref = v_intake.case_id::text
      and archived_at is null;

  return query
    select i.id, i.review_state, i.published_record_id
    from private.comun_sidewalk_relata_intakes i
    where i.id = v_intake.id;
end;
$$;


ALTER FUNCTION public.comun_sidewalk_intake_review(p_intake_id uuid, p_decision text, p_public_summary text, p_public_geometry jsonb) OWNER TO postgres;

--
-- Name: comun_stmu_assisted_declare_sent(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_stmu_assisted_declare_sent(p_token_hash_hex text, p_attempt_id uuid, p_sent boolean) RETURNS TABLE(attempt_id uuid, attempt_state text, due_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_attempt private.comun_forwarding_attempts%rowtype; v_state text; v_due timestamptz;
begin
  v_wallet:=private.comun_p5_wallet_id(p_token_hash_hex); if v_wallet is null then return; end if;
  select a.* into v_attempt from private.comun_forwarding_attempts a join private.comun_forwarding_packages p on p.id=a.package_id where a.id=p_attempt_id and p.wallet_id=v_wallet and p.withdrawn_at is null for update of a; if not found or v_attempt.state<>'prepared' then return; end if;
  v_state:=case when p_sent then 'person_declared_sent' else 'abandoned' end; v_due:=case when p_sent then now()+interval '72 hours' else null end;
  update private.comun_forwarding_attempts set state=v_state,declared_at=now(),due_at=v_due,updated_at=now() where id=p_attempt_id;
  update private.comun_forwarding_packages set state=case when p_sent then 'waiting_response' else 'ready_for_forwarding' end,updated_at=now() where id=v_attempt.package_id;
  update private.comun_bus_relata_intakes b set state=case when p_sent then 'waiting_response' else 'forwarding_prepared' end,updated_at=now() from private.comun_forwarding_packages p where p.id=v_attempt.package_id and b.id=p.bus_intake_id;
  update private.comun_participation_wallet_items wi set presentation_state=case when p_sent then 'Aguardando retorno' else 'Encaminhamento preparado' end,action_required=case when p_sent then 'Acompanhar resposta' else 'Conferir e enviar manualmente' end,updated_at=now() from private.comun_forwarding_packages p where p.id=v_attempt.package_id and wi.wallet_id=p.wallet_id and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report' and wi.archived_at is null;
  insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code) values(v_attempt.package_id,p_attempt_id,case when p_sent then 'person_declared_sent' else 'not_sent' end,case when p_sent then 'FORWARDING_PERSON_DECLARED_SENT' else 'FORWARDING_PERSON_DID_NOT_SEND' end);
  return query select p_attempt_id,v_state,v_due;
end; $$;


ALTER FUNCTION public.comun_stmu_assisted_declare_sent(p_token_hash_hex text, p_attempt_id uuid, p_sent boolean) OWNER TO postgres;

--
-- Name: comun_stmu_assisted_list(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_stmu_assisted_list(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(package_id uuid, state text, subject text, institutional_text text, response_expectation text, attempts jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select p.id,p.state,p.subject,p.institutional_text,p.response_expectation,
    coalesce((select jsonb_agg(jsonb_build_object(
      'attemptId',a.id,'sequence',a.sequence_no,'channel',a.channel,
      'institutionalChannelId',a.institutional_channel_id,'state',a.state,
      'openedAt',a.opened_at,'declaredAt',a.declared_at,'dueAt',a.due_at,
      'officialProtocolMasked',case when a.official_protocol is null then null else left(a.official_protocol,3)||'••••' end,
      'respondedAt',a.responded_at,'resolutionOutcome',a.resolution_outcome
    ) order by a.sequence_no) from private.comun_forwarding_attempts a where a.package_id=p.id),'[]'::jsonb)
  from private.comun_forwarding_packages p
  join private.comun_participation_wallet_items wi on wi.wallet_id=p.wallet_id
    and wi.subject_ref=p.relata_case_id::text and wi.item_type='relata_report' and wi.archived_at is null
  where p.wallet_id=private.comun_p5_wallet_id(p_token_hash_hex)
    and wi.id=p_wallet_item_id and p.withdrawn_at is null;
$$;


ALTER FUNCTION public.comun_stmu_assisted_list(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_stmu_assisted_open(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_stmu_assisted_open(p_token_hash_hex text, p_package_id uuid, p_channel text) RETURNS TABLE(attempt_id uuid, attempt_state text, channel_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_attempt private.comun_forwarding_attempts%rowtype; v_sequence integer; v_url text;
begin
  if p_channel not in ('whatsapp','email','phone','in_person') then return; end if;
  v_wallet:=private.comun_p5_wallet_id(p_token_hash_hex); if v_wallet is null then return; end if;
  perform 1 from private.comun_forwarding_packages where id=p_package_id and wallet_id=v_wallet and withdrawn_at is null for update; if not found then return; end if;
  select * into v_attempt from private.comun_forwarding_attempts where package_id=p_package_id and channel=p_channel and state='prepared';
  if not found then
    select coalesce(max(sequence_no),0)+1 into v_sequence from private.comun_forwarding_attempts where package_id=p_package_id;
    insert into private.comun_forwarding_attempts(package_id,sequence_no,channel,state) values(p_package_id,v_sequence,p_channel,'prepared') returning * into v_attempt;
    insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code) values(p_package_id,v_attempt.id,'channel_opened','FORWARDING_CHANNEL_OPENED_BY_PERSON');
  end if;
  update private.comun_forwarding_packages set state='forwarding_prepared',updated_at=now() where id=p_package_id;
  v_url:=case p_channel when 'whatsapp' then 'https://wa.me/5524992958558' when 'email' then 'mailto:stmu@voltaredonda.rj.gov.br' when 'phone' then 'tel:+552435113728' else null end;
  return query select v_attempt.id,v_attempt.state,v_url;
end; $$;


ALTER FUNCTION public.comun_stmu_assisted_open(p_token_hash_hex text, p_package_id uuid, p_channel text) OWNER TO postgres;

--
-- Name: comun_stmu_assisted_prepare(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_stmu_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid) RETURNS TABLE(package_id uuid, state text, subject text, institutional_text text, response_expectation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_case public.comun_relata_cases%rowtype; v_report private.comun_relata_reports%rowtype; v_bus private.comun_bus_relata_intakes%rowtype; v_package private.comun_forwarding_packages%rowtype; v_body text;
begin
  v_wallet:=private.comun_p5_wallet_id(p_token_hash_hex); if v_wallet is null then return; end if;
  select c.* into v_case from private.comun_participation_wallet_items wi join public.comun_relata_cases c on c.id=wi.subject_ref::uuid
    where wi.id=p_wallet_item_id and wi.wallet_id=v_wallet and wi.item_type='relata_report' and wi.category='public_transport' and wi.archived_at is null and c.state<>'withdrawn';
  if not found then return; end if;
  select report.* into v_report from private.comun_relata_reports as report
    where report.id=v_case.report_id and report.withdrawn_at is null; if not found then return; end if;
  select bus.* into v_bus from private.comun_bus_relata_intakes as bus
    where bus.case_id=v_case.id and bus.state<>'withdrawn'; if not found then return; end if;
  v_body:='Olá. Gostaria de registrar uma reclamação sobre o transporte coletivo.'||E'\n\nLinha: '||coalesce(v_bus.line_label,'não informada')||E'\nSentido: '||coalesce(v_bus.direction,'não informado')||E'\nData e horário: '||to_char(v_bus.observed_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI')||E'\nNúmero de ordem do veículo: '||coalesce(v_bus.vehicle_order,'não observado')||E'\nOcorrência: '||v_bus.issue_type||E'\nDescrição: '||v_report.original_text||E'\n\nSolicito, por favor, o registro da reclamação e o número de protocolo.';
  insert into private.comun_forwarding_packages as current(wallet_id,relata_case_id,bus_intake_id,state,subject,institutional_text)
  values(v_wallet,v_case.id,v_bus.id,'ready_for_forwarding','Reclamação sobre transporte coletivo',v_body)
  on conflict(wallet_id,relata_case_id) do update set updated_at=now(),withdrawn_at=null returning * into v_package;
  update private.comun_bus_relata_intakes as bus
    set state='forwarding_prepared',updated_at=now()
    where bus.id=v_bus.id and bus.state='ready_for_forwarding';
  update private.comun_participation_wallet_items set presentation_state='Encaminhamento preparado',action_required='Conferir e enviar manualmente',updated_at=now() where id=p_wallet_item_id and wallet_id=v_wallet;
  insert into private.comun_forwarding_events(package_id,event_type,result_code) values(v_package.id,'package_prepared','FORWARDING_PACKAGE_PREPARED');
  return query select v_package.id,v_package.state,v_package.subject,v_package.institutional_text,v_package.response_expectation;
end; $$;


ALTER FUNCTION public.comun_stmu_assisted_prepare(p_token_hash_hex text, p_wallet_item_id uuid) OWNER TO postgres;

--
-- Name: comun_stmu_assisted_record_response(text, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_stmu_assisted_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_note text, p_official_protocol text, p_resolved boolean) RETURNS TABLE(attempt_id uuid, attempt_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_wallet uuid; v_attempt private.comun_forwarding_attempts%rowtype;
begin
  if char_length(trim(coalesce(p_response_note,''))) not between 1 and 600
    or char_length(coalesce(p_official_protocol,''))>240 then return; end if;
  v_wallet:=private.comun_p5_wallet_id(p_token_hash_hex);
  if v_wallet is null then return; end if;
  select a.* into v_attempt from private.comun_forwarding_attempts a
    join private.comun_forwarding_packages p on p.id=a.package_id
    where a.id=p_attempt_id and p.wallet_id=v_wallet
      and a.state in ('person_declared_sent','no_response') for update of a;
  if not found then return; end if;
  update private.comun_forwarding_attempts set
    state='responded',resolution_outcome=case when p_resolved then 'resolved' else 'unresolved' end,
    response_note=trim(p_response_note),official_protocol=nullif(trim(p_official_protocol),''),
    responded_at=now(),updated_at=now() where id=p_attempt_id;
  update private.comun_forwarding_packages set state='responded',updated_at=now()
    where id=v_attempt.package_id;
  update private.comun_bus_relata_intakes b set state='responded',updated_at=now()
  from private.comun_forwarding_packages p where p.id=v_attempt.package_id and b.id=p.bus_intake_id;
  update private.comun_participation_wallet_items wi set
    presentation_state=case when p_resolved then 'Resolvido' else 'Resposta não resolveu' end,
    action_required=case when p_resolved then null else 'Ver próximo passo' end,updated_at=now()
  from private.comun_forwarding_packages p where p.id=v_attempt.package_id
    and wi.wallet_id=p.wallet_id and wi.subject_ref=p.relata_case_id::text
    and wi.item_type='relata_report' and wi.archived_at is null;
  insert into private.comun_forwarding_events(package_id,attempt_id,event_type,result_code)
    values(v_attempt.package_id,p_attempt_id,'response_recorded',case when p_resolved
      then 'FORWARDING_RESPONSE_RESOLVED' else 'FORWARDING_RESPONSE_NOT_RESOLVED' end);
  return query select p_attempt_id,'responded'::text;
end;
$$;


ALTER FUNCTION public.comun_stmu_assisted_record_response(p_token_hash_hex text, p_attempt_id uuid, p_response_note text, p_official_protocol text, p_resolved boolean) OWNER TO postgres;

--
-- Name: comun_submit_solidarity_organization_onboarding_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_submit_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid) RETURNS TABLE(onboarding_id uuid, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_onboarding private.comun_solidarity_organization_onboarding%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  select onboarding.* into v_onboarding
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.continuation_token = p_continuation_token
  for update;
  if not found or v_onboarding.applicant_user_id <> p_applicant_user_id then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_FOUND';
  end if;
  if v_onboarding.last_mutation_request_id = p_request_id
    or (v_onboarding.state = 'submitted' and v_onboarding.applicant_user_id = p_applicant_user_id) then
    return query select v_onboarding.id, v_onboarding.state, true;
    return;
  end if;
  if v_onboarding.state not in ('draft','needs_changes') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_SUBMITTABLE';
  end if;
  if v_onboarding.organization_type_candidate is null
    or v_onboarding.presentation_candidate is null
    or v_onboarding.participation_note_private is null then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_INCOMPLETE';
  end if;
  if exists (
    select 1 from public.comun_territorial_organizations organization
    join public.comun_hub_territories territory on territory.id = organization.territory_id
    where private.comun_normalize_solidarity_organization_name(organization.public_name) = v_onboarding.normalized_name_candidate
      and organization.status in ('active','forming')
      and organization.verification_status in ('source_checked','verified')
      and territory.visibility = 'public'
      and territory.status in ('active','monitoring')
      and territory.verification_status in ('source_checked','verified')
  ) then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_EXISTING_ORGANIZATION';
  end if;

  update private.comun_solidarity_organization_onboarding onboarding set
    state = 'submitted', submitted_at = v_now, reviewed_at = null, reviewed_by_user_id = null,
    review_message_private = null, last_mutation_request_id = p_request_id,
    transition_history_private = onboarding.transition_history_private || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('event', 'submitted', 'actorUserId', p_applicant_user_id, 'at', v_now)
    )
  where onboarding.id = v_onboarding.id
  returning onboarding.id, onboarding.state into onboarding_id, state;
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_submit_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid) OWNER TO postgres;

--
-- Name: comun_sync_public_search_projection(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_sync_public_search_projection() RETURNS TABLE(documents_upserted bigint, documents_removed bigint, sections_queued bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_upserted bigint := 0;
  v_removed bigint := 0;
  v_queued bigint := 0;
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'COMUN_SEARCH_SERVER_ROLE_REQUIRED' using errcode = '42501';
  end if;

  create temporary table comun_search_candidates on commit drop as
  select 'communities'::text domain, 'comunidade'::text source_type, c.id::text source_key,
    extract(epoch from c.updated_at)::text source_version, '/comun/c/' || c.slug canonical_route,
    c.name title, c.short_description summary, coalesce(c.full_description, c.short_description, '') public_text,
    null::uuid territory_id, null::uuid pauta_id, 'active'::text process_state, c.updated_at source_date
  from public.comun_communities c where c.is_active
  union all
  select 'pautas', 'pauta', p.id::text, extract(epoch from p.updated_at)::text,
    '/comun/pautas/' || p.slug, p.title, p.summary,
    concat_ws(E'\n', p.public_synthesis, p.problem_public, p.demand_public, p.proposals_public, p.participation_public),
    p.territory_id, p.id, coalesce(p.public_status, p.status), p.updated_at
  from public.comun_pauta_spaces p where p.visibility = 'public'
  union all
  select 'territories', 'território', t.id::text, extract(epoch from t.updated_at)::text,
    '/comun/territorios/' || t.slug, t.name, t.public_summary,
    concat_ws(E'\n', t.public_summary, t.municipality, t.neighborhood, t.public_approximate_address, t.source_summary_public),
    t.id, t.pauta_id, t.status, t.updated_at
  from public.comun_hub_territories t where t.status <> 'archived' and coalesce(t.visibility, 'public') = 'public'
  union all
  select 'actions', 'ação', a.id::text, extract(epoch from a.updated_at)::text,
    '/comun/acoes/' || a.slug, a.title, a.objective_public,
    concat_ws(E'\n', a.objective_public, a.participation_public, a.guidance_public, a.expected_result_public, a.observed_result_public, a.public_record),
    a.territory_id, a.pauta_id, a.status, a.updated_at
  from public.comun_mobilization_actions a where a.visibility = 'public'
  union all
  select 'results', 'resultado', r.id::text, extract(epoch from r.updated_at)::text,
    '/comun/resultados?resultado=' || r.slug, r.title, r.public_summary,
    concat_ws(E'\n', r.public_summary, r.what_was_done_public, r.remaining_public, r.evidence_summary_public),
    r.territory_id, r.pauta_id, r.verification_status, coalesce(r.occurred_at, r.updated_at)
  from public.comun_hub_results r where r.visibility = 'public'
  union all
  select 'dossiers', 'documento', d.id::text, coalesce(d.public_version_label, extract(epoch from d.public_updated_at)::text),
    '/comun/dossies/' || d.public_slug, d.public_title, d.public_summary, coalesce(d.public_body, ''),
    null::uuid, null::uuid, 'published', coalesce(d.public_updated_at, d.published_at)
  from public.comun_pauta_dossier_publication_snapshots d where d.snapshot_status = 'active'
  union all
  select 'sidewalks', 'calçada', s.id::text, extract(epoch from s.updated_at)::text,
    '/comun/calcadas/registros/' || s.slug, s.name, s.public_summary,
    concat_ws(E'\n', s.public_summary, s.municipality, s.neighborhood, s.approximate_location, array_to_string(s.categories, ' ')),
    s.territory_id, s.pauta_id, s.status, s.updated_at
  from public.comun_sidewalk_records s where s.visibility = 'public'
  union all
  select 'archive', 'memória', i.id::text, extract(epoch from i.updated_at)::text,
    '/comun/acervo/' || i.slug, i.title, i.summary,
    concat_ws(E'\n', i.summary, i.description, i.city, i.neighborhood, i.place_name, i.approximate_date, i.genre),
    null::uuid, null::uuid, i.status, coalesce(i.published_at, i.updated_at)
  from public.comun_archive_items i where i.status = 'published' and i.visibility = 'public'
  union all
  select 'art', 'obra', a.archive_item_id::text, extract(epoch from a.updated_at)::text,
    '/comun/acervo/arte/' || i.slug, a.title_public, a.description_public,
    concat_ws(E'\n', a.subtitle_public, a.description_public, a.context_public, a.long_description_public, a.technique_public, a.creation_place_public),
    a.territory_id, null::uuid, a.publication_status, a.updated_at
  from public.comun_archive_artworks a join public.comun_archive_items i on i.id = a.archive_item_id
  where a.publication_status = 'published' and i.status = 'published' and i.visibility = 'public'
  union all
  select 'radio', 'programa', p.archive_item_id::text, extract(epoch from p.updated_at)::text,
    '/comun/radio/programas/' || p.slug_public, p.title_public, p.subtitle_public,
    concat_ws(E'\n', p.subtitle_public, p.description_public, p.frequency_public),
    p.territory_id, p.pauta_id, p.publication_status, p.updated_at
  from public.comun_radio_programs p where p.publication_status = 'published'
  union all
  select 'radio', 'episódio', e.archive_item_id::text, extract(epoch from e.updated_at)::text,
    '/comun/radio/episodios/' || e.slug_public, e.title_public, e.summary_public,
    concat_ws(E'\n', e.summary_public, e.description_public), e.territory_id, e.pauta_id,
    e.publication_status, coalesce(e.published_at, e.updated_at)
  from public.comun_radio_episodes e where e.publication_status = 'published'
  union all
  select 'archive', 'coleção', c.id::text, extract(epoch from c.updated_at)::text,
    '/comun/acervo/colecoes/' || c.slug, c.title, c.summary, concat_ws(E'\n', c.summary, c.description),
    null::uuid, null::uuid, c.status, coalesce(c.published_at, c.updated_at)
  from public.comun_archive_collections c where c.status = 'published'
  union all
  select 'memory', 'memória', m.id::text, extract(epoch from m.updated_at)::text,
    '/comun/pautas/' || p.slug || '/memoria/' || m.slug, m.title, m.public_summary,
    concat_ws(E'\n', m.public_summary, m.methodology_snapshot), m.territory_id, m.pauta_id,
    m.status, coalesce(m.published_at, m.updated_at)
  from public.comun_sidewalk_cycle_memories m join public.comun_pauta_spaces p on p.id = m.pauta_id
  where m.visibility = 'public' and m.status = 'published';

  alter table comun_search_candidates add column content_checksum text;
  update comun_search_candidates set content_checksum = md5(concat_ws(E'\x1f', domain, source_type, source_key, canonical_route, title, summary, public_text, process_state))
  where content_checksum is null;

  insert into public.comun_search_documents (
    domain, source_type, source_key, source_version, canonical_route, title, summary, public_text,
    territory_id, pauta_id, process_state, source_date, content_checksum, search_vector, indexing_state, last_synced_at
  )
  select domain, source_type, source_key, source_version, canonical_route, title, nullif(summary, ''), left(public_text, 12000),
    territory_id, pauta_id, process_state, source_date, content_checksum,
    to_tsvector('public.comun_portuguese_unaccent', concat_ws(' ', title, summary, public_text)),
    'lexical_ready', now()
  from comun_search_candidates
  on conflict (source_type, source_key) do update set
    domain = excluded.domain, source_version = excluded.source_version, canonical_route = excluded.canonical_route,
    title = excluded.title, summary = excluded.summary, public_text = excluded.public_text,
    territory_id = excluded.territory_id, pauta_id = excluded.pauta_id, process_state = excluded.process_state,
    source_date = excluded.source_date, search_vector = excluded.search_vector, last_synced_at = now(),
    indexing_state = case when public.comun_search_documents.content_checksum = excluded.content_checksum
      then public.comun_search_documents.indexing_state else 'embedding_pending' end,
    content_checksum = excluded.content_checksum,
    embedding = case when public.comun_search_documents.content_checksum = excluded.content_checksum
      then public.comun_search_documents.embedding else null end,
    embedding_model = case when public.comun_search_documents.content_checksum = excluded.content_checksum
      then public.comun_search_documents.embedding_model else null end,
    embedding_version = case when public.comun_search_documents.content_checksum = excluded.content_checksum
      then public.comun_search_documents.embedding_version else null end,
    embedded_at = case when public.comun_search_documents.content_checksum = excluded.content_checksum
      then public.comun_search_documents.embedded_at else null end;
  get diagnostics v_upserted = row_count;

  delete from public.comun_search_documents d
  where d.permission_scope = 'public' and not exists (
    select 1 from comun_search_candidates c where c.source_type = d.source_type and c.source_key = d.source_key
  );
  get diagnostics v_removed = row_count;

  insert into public.comun_search_sections (document_id, section_kind, ordinal, title_context, route_context, public_text, content_checksum)
  select d.id, s.kind, s.ordinal, d.title, d.canonical_route, s.body, md5(s.body)
  from public.comun_search_documents d
  cross join lateral (
    values
      ('title'::text, 0, left(d.title, 4000)),
      ('summary'::text, 1, left(coalesce(nullif(d.summary, ''), d.public_text), 4000)),
      ('section'::text, 2, left(d.public_text, 4000))
  ) s(kind, ordinal, body)
  where length(trim(s.body)) > 0
  on conflict (document_id, section_kind, ordinal) do update set
    title_context = excluded.title_context, route_context = excluded.route_context, public_text = excluded.public_text,
    indexing_state = case when public.comun_search_sections.content_checksum = excluded.content_checksum
      then public.comun_search_sections.indexing_state else 'embedding_pending' end,
    embedding = case when public.comun_search_sections.content_checksum = excluded.content_checksum
      then public.comun_search_sections.embedding else null end,
    embedding_model = case when public.comun_search_sections.content_checksum = excluded.content_checksum
      then public.comun_search_sections.embedding_model else null end,
    embedding_version = case when public.comun_search_sections.content_checksum = excluded.content_checksum
      then public.comun_search_sections.embedding_version else null end,
    embedded_at = case when public.comun_search_sections.content_checksum = excluded.content_checksum
      then public.comun_search_sections.embedded_at else null end,
    content_checksum = excluded.content_checksum;

  delete from public.comun_search_sections s
  using public.comun_search_documents d
  where s.document_id = d.id and not exists (
    select 1 from (values
      ('title'::text, 0, left(d.title, 4000)),
      ('summary'::text, 1, left(coalesce(nullif(d.summary, ''), d.public_text), 4000)),
      ('section'::text, 2, left(d.public_text, 4000))
    ) expected(kind, ordinal, body)
    where expected.kind = s.section_kind and expected.ordinal = s.ordinal and length(trim(expected.body)) > 0
  );

  insert into public.comun_search_embedding_jobs (section_id, content_checksum)
  select s.id, s.content_checksum from public.comun_search_sections s
  where s.embedding is null and s.indexing_state in ('embedding_pending', 'failed')
  on conflict (section_id, content_checksum) do nothing;
  get diagnostics v_queued = row_count;

  return query select v_upserted, v_removed, v_queued;
end
$$;


ALTER FUNCTION public.comun_sync_public_search_projection() OWNER TO postgres;

--
-- Name: comun_transition_pauta_action_cycle(uuid, integer, text, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_transition_pauta_action_cycle(p_cycle_id uuid, p_expected_version integer, p_idempotency_key text, p_to_stage text, p_actor_admin_id uuid, p_actor_role text, p_public_summary text, p_private_note text DEFAULT NULL::text) RETURNS TABLE(cycle_id uuid, current_stage text, state_version integer, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  current_cycle public.comun_pauta_action_cycles%rowtype;
  existing_event public.comun_pauta_action_cycle_events%rowtype;
  allowed_roles text[];
  approved_contributions integer;
  previous_stage text;
  transition_allowed boolean := false;
begin
  if p_idempotency_key !~ '^[A-Za-z0-9:_-]{12,128}$' then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_INVALID_IDEMPOTENCY_KEY';
  end if;

  select * into current_cycle
  from public.comun_pauta_action_cycles
  where id = p_cycle_id
  for update;

  if current_cycle.id is null then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_NOT_FOUND';
  end if;

  select * into existing_event
  from public.comun_pauta_action_cycle_events
  where comun_pauta_action_cycle_events.cycle_id = p_cycle_id
    and idempotency_key = p_idempotency_key;

  if existing_event.id is not null then
    if existing_event.to_stage <> p_to_stage then
      raise exception 'COMUN_PAUTA_ACTION_CYCLE_IDEMPOTENCY_CONFLICT';
    end if;
    return query
      select current_cycle.id, current_cycle.current_stage,
        current_cycle.state_version, true;
    return;
  end if;

  if current_cycle.state_version <> p_expected_version then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_VERSION_CONFLICT';
  end if;

  transition_allowed :=
    (current_cycle.current_stage = 'contribution' and p_to_stage = 'moderation')
    or (current_cycle.current_stage = 'moderation' and p_to_stage = 'conversation')
    or (current_cycle.current_stage = 'conversation' and p_to_stage = 'synthesis')
    or (current_cycle.current_stage = 'synthesis' and p_to_stage = 'decision')
    or (current_cycle.current_stage = 'decision' and p_to_stage = 'action')
    or (current_cycle.current_stage = 'action' and p_to_stage = 'tasks')
    or (current_cycle.current_stage = 'tasks' and p_to_stage = 'forwarding')
    or (current_cycle.current_stage = 'forwarding' and p_to_stage = 'protocol')
    or (current_cycle.current_stage = 'protocol' and p_to_stage = 'response')
    or (current_cycle.current_stage = 'response' and p_to_stage = 'result')
    or (current_cycle.current_stage = 'result' and p_to_stage = 'memory')
    or (current_cycle.current_stage = 'memory' and p_to_stage = 'reopened')
    or (current_cycle.current_stage = 'reopened' and p_to_stage in ('moderation', 'conversation'));

  if not transition_allowed then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_INVALID_TRANSITION';
  end if;

  allowed_roles := case p_to_stage
    when 'moderation' then array['admin', 'editor', 'curator']
    when 'conversation' then array['admin', 'editor', 'coordinator', 'facilitator']
    when 'synthesis' then array['admin', 'editor', 'curator', 'facilitator']
    when 'decision' then array['admin', 'editor', 'coordinator']
    when 'action' then array['admin', 'editor', 'coordinator']
    when 'tasks' then array['admin', 'editor', 'coordinator', 'facilitator']
    when 'forwarding' then array['admin', 'editor', 'coordinator', 'protocol_operator']
    when 'protocol' then array['admin', 'editor', 'protocol_operator']
    when 'response' then array['admin', 'editor', 'protocol_operator']
    when 'result' then array['admin', 'editor', 'coordinator', 'result_editor']
    when 'memory' then array['admin', 'editor', 'curator']
    when 'reopened' then array['admin', 'editor', 'coordinator']
    else array[]::text[]
  end;

  if not (p_actor_role = any(allowed_roles)) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_ROLE_FORBIDDEN';
  end if;

  previous_stage := current_cycle.current_stage;

  if p_to_stage in ('moderation', 'conversation') then
    select count(*) into approved_contributions
    from public.comun_pauta_contributions contribution
    where contribution.pauta_id = current_cycle.pauta_id
      and contribution.status = 'approved';
    if approved_contributions = 0 then
      raise exception 'COMUN_PAUTA_ACTION_CYCLE_APPROVED_CONTRIBUTION_REQUIRED';
    end if;
  elsif p_to_stage = 'synthesis' and not exists (
    select 1 from public.comun_construction_circles circle
    where circle.pauta_id = current_cycle.pauta_id
      and circle.status not in ('draft', 'archived')
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_CONVERSATION_REQUIRED';
  elsif p_to_stage = 'decision' and not exists (
    select 1 from public.comun_pauta_synthesis_versions synthesis
    where synthesis.pauta_id = current_cycle.pauta_id
      and nullif(trim(synthesis.new_public_synthesis), '') is not null
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_SYNTHESIS_REQUIRED';
  elsif p_to_stage = 'action' and not exists (
    select 1 from public.comun_pauta_decisions decision
    where decision.id = current_cycle.decision_id
      and decision.pauta_id = current_cycle.pauta_id
      and decision.status = 'published'
      and (
        decision.created_by_admin_id <> p_actor_admin_id
        or p_actor_role = 'admin'
      )
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_REVIEWED_DECISION_REQUIRED';
  elsif p_to_stage = 'tasks' and not exists (
    select 1 from public.comun_collective_actions action
    where action.id = current_cycle.collective_action_id
      and action.pauta_id = current_cycle.pauta_id
      and action.status <> 'draft'
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_COLLECTIVE_ACTION_REQUIRED';
  elsif p_to_stage = 'forwarding' and not exists (
    select 1 from public.comun_collective_action_tasks task
    where task.action_id = current_cycle.collective_action_id
      and task.state not in ('draft', 'archived', 'cancelled')
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_TASK_REQUIRED';
  elsif p_to_stage = 'protocol' and not exists (
    select 1 from public.comun_collective_action_forwardings forwarding
    where forwarding.id = current_cycle.forwarding_id
      and forwarding.action_id = current_cycle.collective_action_id
      and forwarding.state <> 'preparing'
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_FORWARDING_REQUIRED';
  elsif p_to_stage = 'response' and not exists (
    select 1 from public.comun_official_protocols protocol
    where protocol.id = current_cycle.official_protocol_id
      and protocol.submitted_at is not null
      and protocol.status not in ('draft', 'text_generated')
      and exists (
        select 1
        from public.comun_pauta_evidence_items evidence
        where evidence.pauta_id = current_cycle.pauta_id
          and evidence.source_type = 'official_protocol'
          and evidence.source_id = protocol.id
      )
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_SUBMITTED_PROTOCOL_REQUIRED';
  elsif p_to_stage = 'result' and not exists (
    select 1 from public.comun_collective_actions action
    where action.id = current_cycle.collective_action_id
      and action.status in ('awaiting_result', 'completed')
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_ACTIVITY_REQUIRED';
  elsif p_to_stage = 'result' and not exists (
    select 1 from public.comun_official_protocols protocol
    where protocol.id = current_cycle.official_protocol_id
      and protocol.response_received_at is not null
      and nullif(trim(protocol.public_summary), '') is not null
      and exists (
        select 1
        from public.comun_pauta_evidence_items evidence
        where evidence.pauta_id = current_cycle.pauta_id
          and evidence.source_type = 'official_protocol'
          and evidence.source_id = protocol.id
      )
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_PUBLIC_RESPONSE_REQUIRED';
  elsif p_to_stage = 'memory' and not exists (
    select 1 from public.comun_hub_results result
    where result.id = current_cycle.result_id
      and result.pauta_id = current_cycle.pauta_id
      and result.verification_status = 'verified'
      and result.visibility = 'public'
      and nullif(trim(result.evidence_summary_public), '') is not null
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_VERIFIED_RESULT_REQUIRED';
  elsif p_to_stage = 'reopened' and not exists (
    select 1 from public.comun_collective_actions action
    where action.id = current_cycle.collective_action_id
      and action.status = 'completed'
      and action.memory_published_at is not null
      and nullif(trim(action.memory_summary), '') is not null
  ) then
    raise exception 'COMUN_PAUTA_ACTION_CYCLE_REVIEWED_MEMORY_REQUIRED';
  end if;

  update public.comun_pauta_action_cycles
  set current_stage = p_to_stage,
      state_version = comun_pauta_action_cycles.state_version + 1,
      last_transition_at = now(),
      updated_at = now(),
      blocking_reason_public = null
  where id = p_cycle_id
  returning * into current_cycle;

  insert into public.comun_pauta_action_cycle_events(
    cycle_id, idempotency_key, from_stage, to_stage, actor_admin_id,
    actor_role, public_summary, private_note, public_visible, state_version
  )
  values (
    p_cycle_id, p_idempotency_key, previous_stage, p_to_stage,
    p_actor_admin_id, p_actor_role, p_public_summary, p_private_note,
    current_cycle.public_visible and current_cycle.cycle_scope = 'production',
    current_cycle.state_version
  );

  return query
    select current_cycle.id, current_cycle.current_stage,
      current_cycle.state_version, false;
end;
$_$;


ALTER FUNCTION public.comun_transition_pauta_action_cycle(p_cycle_id uuid, p_expected_version integer, p_idempotency_key text, p_to_stage text, p_actor_admin_id uuid, p_actor_role text, p_public_summary text, p_private_note text) OWNER TO postgres;

--
-- Name: comun_update_solidarity_organization_onboarding_v1(uuid, uuid, uuid, text, text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_update_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid, p_organization_name_candidate text, p_organization_type_candidate text, p_presentation_candidate text, p_service_territory_candidate text DEFAULT NULL::text, p_public_contact_candidate text DEFAULT NULL::text, p_public_contact_publication_authorized boolean DEFAULT false, p_public_source_url_candidate text DEFAULT NULL::text, p_participation_note_private text DEFAULT NULL::text) RETURNS TABLE(onboarding_id uuid, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_onboarding private.comun_solidarity_organization_onboarding%rowtype;
  v_name text;
  v_presentation text;
  v_service_territory text;
  v_public_contact text;
  v_source_url text;
  v_participation_note text;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_request_id is null then raise exception 'COMUN_SOLIDARITY_ONBOARDING_REQUEST_ID_REQUIRED'; end if;
  select onboarding.* into v_onboarding
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.continuation_token = p_continuation_token
  for update;
  if not found or v_onboarding.applicant_user_id <> p_applicant_user_id then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_FOUND';
  end if;
  if v_onboarding.last_mutation_request_id = p_request_id then
    return query select v_onboarding.id, v_onboarding.state, true;
    return;
  end if;
  if v_onboarding.state not in ('draft','needs_changes') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_EDITABLE';
  end if;

  v_name := pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_organization_name_candidate, ''), '[[:space:]]+', ' ', 'g'));
  v_presentation := nullif(pg_catalog.btrim(coalesce(p_presentation_candidate, '')), '');
  v_service_territory := nullif(pg_catalog.btrim(coalesce(p_service_territory_candidate, '')), '');
  v_public_contact := nullif(pg_catalog.btrim(coalesce(p_public_contact_candidate, '')), '');
  v_source_url := nullif(pg_catalog.btrim(coalesce(p_public_source_url_candidate, '')), '');
  v_participation_note := nullif(pg_catalog.btrim(coalesce(p_participation_note_private, '')), '');
  if pg_catalog.char_length(v_name) not between 3 and 160
    or p_organization_type_candidate not in ('cooperative','association','collective','informal_group','solidarity_enterprise','network','other')
    or v_presentation is null or pg_catalog.char_length(v_presentation) not between 10 and 1200
    or (v_service_territory is not null and pg_catalog.char_length(v_service_territory) not between 2 and 300)
    or (v_public_contact is not null and pg_catalog.char_length(v_public_contact) not between 3 and 300)
    or (v_source_url is not null and (pg_catalog.char_length(v_source_url) not between 10 and 1000 or v_source_url !~* '^https://'))
    or v_participation_note is null or pg_catalog.char_length(v_participation_note) not between 10 and 600
    or (p_public_contact_publication_authorized and v_public_contact is null) then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_DETAILS_INVALID';
  end if;

  update private.comun_solidarity_organization_onboarding onboarding set
    organization_name_candidate = v_name,
    normalized_name_candidate = private.comun_normalize_solidarity_organization_name(v_name),
    organization_type_candidate = p_organization_type_candidate,
    presentation_candidate = v_presentation,
    service_territory_candidate = v_service_territory,
    public_contact_candidate = v_public_contact,
    public_contact_publication_authorized = p_public_contact_publication_authorized,
    public_source_url_candidate = v_source_url,
    participation_note_private = v_participation_note,
    review_message_private = case when onboarding.state = 'needs_changes' then null else onboarding.review_message_private end,
    last_mutation_request_id = p_request_id,
    transition_history_private = onboarding.transition_history_private || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('event', 'details_saved', 'actorUserId', p_applicant_user_id, 'at', v_now)
    )
  where onboarding.id = v_onboarding.id
  returning onboarding.id, onboarding.state into onboarding_id, state;
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_update_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid, p_organization_name_candidate text, p_organization_type_candidate text, p_presentation_candidate text, p_service_territory_candidate text, p_public_contact_candidate text, p_public_contact_publication_authorized boolean, p_public_source_url_candidate text, p_participation_note_private text) OWNER TO postgres;

--
-- Name: comun_update_solidarity_organization_profile_by_access_v1(uuid, uuid, uuid, timestamp with time zone, text, text[], text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_update_solidarity_organization_profile_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_expected_updated_at timestamp with time zone, p_presentation_public text, p_services_public text[], p_service_territory_public text, p_public_contact_authorized text, p_public_contact_confirmed boolean) RETURNS TABLE(organization_territory_id uuid, organization_updated_at timestamp with time zone, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event private.comun_solidarity_economic_content_events%rowtype;
  v_access_id uuid;
  v_organization public.comun_territorial_organizations%rowtype;
  v_now timestamptz := clock_timestamp();
  v_presentation text;
  v_services text[] := array[]::text[];
  v_service_keys text[] := array[]::text[];
  v_service text;
  v_service_key text;
  v_services_length integer := 0;
  v_service_territory text;
  v_public_contact text;
  v_existing_public_contact text;
  v_before jsonb;
  v_after jsonb;
begin
  if p_request_id is null or p_organization_territory_id is null
    or p_actor_user_id is null or p_expected_updated_at is null then
    raise exception 'COMUN_SOLIDARITY_PROFILE_REQUEST_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('comun-economic-request:' || p_request_id::text, 0)
  );
  select event.* into v_event
  from private.comun_solidarity_economic_content_events event
  where event.request_id = p_request_id;
  if found then
    if v_event.actor_member_user_id <> p_actor_user_id
      or v_event.organization_territory_id <> p_organization_territory_id
      or v_event.subject_type <> 'organization_profile'
      or v_event.subject_id <> p_organization_territory_id
      or v_event.operation <> 'organization_profile.edit' then
      raise exception 'COMUN_SOLIDARITY_PROFILE_IDEMPOTENCY_CONFLICT';
    end if;
    select organization.updated_at into organization_updated_at
    from public.comun_territorial_organizations organization
    where organization.territory_id = p_organization_territory_id;
    return query select p_organization_territory_id, organization_updated_at, true;
    return;
  end if;

  v_access_id := private.comun_require_solidarity_economic_access(
    p_organization_territory_id,
    p_actor_user_id
  );

  if (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id
        and event.operation = 'organization_profile.edit'
        and event.occurred_at >= v_now - interval '10 minutes') >= 10
    or (select count(*) from private.comun_solidarity_economic_content_events event
      where event.actor_member_user_id = p_actor_user_id
        and event.operation = 'organization_profile.edit'
        and event.occurred_at >= v_now - interval '24 hours') >= 30 then
    raise exception 'COMUN_SOLIDARITY_PROFILE_RATE_LIMIT';
  end if;

  select organization.* into v_organization
  from public.comun_territorial_organizations organization
  where organization.territory_id = p_organization_territory_id
  for update;
  if not found then
    raise exception 'COMUN_SOLIDARITY_PROFILE_ORGANIZATION_INELIGIBLE';
  end if;
  if v_organization.updated_at <> p_expected_updated_at then
    raise exception 'COMUN_SOLIDARITY_PROFILE_CONFLICT';
  end if;

  v_presentation := nullif(pg_catalog.btrim(pg_catalog.replace(coalesce(p_presentation_public, ''), E'\r\n', E'\n')), '');
  v_service_territory := nullif(pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_service_territory_public, ''), '[[:space:]]+', ' ', 'g')), '');
  v_public_contact := nullif(pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_public_contact_authorized, ''), '[[:space:]]+', ' ', 'g')), '');

  for v_service in
    select pg_catalog.btrim(pg_catalog.regexp_replace(item, '[[:space:]]+', ' ', 'g'))
    from pg_catalog.unnest(coalesce(p_services_public, array[]::text[])) with ordinality as source(item, position)
    order by position
  loop
    if v_service = '' then continue; end if;
    v_service_key := pg_catalog.lower(v_service);
    if v_service_key = any(v_service_keys) then continue; end if;
    if pg_catalog.char_length(v_service) not between 2 and 80 then
      raise exception 'COMUN_SOLIDARITY_PROFILE_SERVICES_INVALID';
    end if;
    v_services := pg_catalog.array_append(v_services, v_service);
    v_service_keys := pg_catalog.array_append(v_service_keys, v_service_key);
    v_services_length := v_services_length + pg_catalog.char_length(v_service);
  end loop;

  if (v_presentation is not null and pg_catalog.char_length(v_presentation) not between 10 and 1200)
    or pg_catalog.cardinality(v_services) > 12
    or v_services_length > 600
    or (v_service_territory is not null and pg_catalog.char_length(v_service_territory) > 300)
    or (v_public_contact is not null and pg_catalog.char_length(v_public_contact) > 200) then
    raise exception 'COMUN_SOLIDARITY_PROFILE_FIELDS_INVALID';
  end if;

  if not private.comun_solidarity_economic_content_is_safe(
    coalesce(v_presentation, '') || E'\n' ||
    pg_catalog.array_to_string(v_services, E'\n') || E'\n' ||
    coalesce(v_service_territory, '')
  ) then
    raise exception 'COMUN_SOLIDARITY_PROFILE_PUBLIC_CONTENT_BLOCKED';
  end if;
  if v_public_contact is not null
    and not private.comun_solidarity_public_contact_is_safe(v_public_contact) then
    raise exception 'COMUN_SOLIDARITY_PROFILE_PUBLIC_CONTACT_BLOCKED';
  end if;

  v_existing_public_contact := nullif(pg_catalog.btrim(coalesce(v_organization.public_contact_authorized, '')), '');
  if v_public_contact is not null
    and v_public_contact is distinct from v_existing_public_contact
    and p_public_contact_confirmed is not true then
    raise exception 'COMUN_SOLIDARITY_PROFILE_PUBLIC_CONTACT_CONFIRMATION_REQUIRED';
  end if;

  v_before := pg_catalog.jsonb_build_object(
    'presentation_public', v_organization.presentation_public,
    'services_public', coalesce(v_organization.services_public, array[]::text[]),
    'service_territory_public', v_organization.service_territory_public,
    'public_contact_authorized', v_organization.public_contact_authorized
  );

  update public.comun_territorial_organizations organization
  set presentation_public = v_presentation,
      services_public = v_services,
      service_territory_public = v_service_territory,
      public_contact_authorized = v_public_contact,
      updated_at = v_now
  where organization.territory_id = p_organization_territory_id;

  v_after := pg_catalog.jsonb_build_object(
    'presentation_public', v_presentation,
    'services_public', v_services,
    'service_territory_public', v_service_territory,
    'public_contact_authorized', v_public_contact
  );

  insert into private.comun_solidarity_economic_content_events(
    request_id, organization_territory_id, actor_access_id, actor_member_user_id,
    subject_type, subject_id, operation, from_state, to_state, occurred_at,
    before_payload_private, after_payload_private
  ) values (
    p_request_id, p_organization_territory_id, v_access_id, p_actor_user_id,
    'organization_profile', p_organization_territory_id,
    'organization_profile.edit', 'current', 'updated', v_now, v_before, v_after
  );

  return query select p_organization_territory_id, v_now, false;
end;
$$;


ALTER FUNCTION public.comun_update_solidarity_organization_profile_by_access_v1(p_request_id uuid, p_organization_territory_id uuid, p_actor_user_id uuid, p_expected_updated_at timestamp with time zone, p_presentation_public text, p_services_public text[], p_service_territory_public text, p_public_contact_authorized text, p_public_contact_confirmed boolean) OWNER TO postgres;

--
-- Name: comun_validate_consent_template(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_validate_consent_template() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare t public.comun_archive_consent_templates;
begin
  if new.template_id is null then raise exception 'Consentimento exige template versionado'; end if;
  select * into t from public.comun_archive_consent_templates where id=new.template_id;
  if t.status <> 'approved' or t.retired_at is not null then raise exception 'Template precisa estar aprovado e ativo'; end if;
  if new.template_version is distinct from t.version then raise exception 'Versão do consentimento diverge do template'; end if;
  return new;
end $$;


ALTER FUNCTION public.comun_validate_consent_template() OWNER TO postgres;

--
-- Name: comun_withdraw_solidarity_connection_v1(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_withdraw_solidarity_connection_v1(p_subject_kind text, p_interest_id uuid, p_member_user_id uuid) RETURNS TABLE(connection_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_now timestamptz:=clock_timestamp();
begin
  if p_subject_kind='offer' then
    update private.comun_solidarity_offer_interests set state='withdrawn',contact_private=null,consent_to_contact=false,withdrawn_at=v_now
      where id=p_interest_id and member_user_id=p_member_user_id and state in ('pending','accepted');
  elsif p_subject_kind='need' then
    update public.comun_territorial_need_interests set status='withdrawn',contact_private=null,consent_to_contact=false,withdrawn_at=v_now
      where id=p_interest_id and member_user_id=p_member_user_id and status in ('pending','accepted');
  else raise exception 'COMUN_SOLIDARITY_CONNECTION_SUBJECT_INVALID'; end if;
  if not found then raise exception 'COMUN_SOLIDARITY_CONNECTION_WITHDRAW_FORBIDDEN'; end if;
  return query select 'withdrawn'::text;
end;
$$;


ALTER FUNCTION public.comun_withdraw_solidarity_connection_v1(p_subject_kind text, p_interest_id uuid, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: comun_withdraw_solidarity_organization_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_withdraw_solidarity_organization_access(p_organization_territory_id uuid, p_member_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
begin
  update private.comun_solidarity_organization_access access
  set state = 'withdrawn',
      transition_history_private = access.transition_history_private || jsonb_build_array(jsonb_build_object(
        'event', 'withdrawn', 'actorUserId', p_member_user_id, 'at', v_now
      ))
  where access.organization_territory_id = p_organization_territory_id
    and access.member_user_id = p_member_user_id
    and access.state = 'pending';
  return found;
end;
$$;


ALTER FUNCTION public.comun_withdraw_solidarity_organization_access(p_organization_territory_id uuid, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: comun_withdraw_solidarity_organization_onboarding_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comun_withdraw_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid) RETURNS TABLE(onboarding_id uuid, state text, idempotent boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_onboarding private.comun_solidarity_organization_onboarding%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  select onboarding.* into v_onboarding
  from private.comun_solidarity_organization_onboarding onboarding
  where onboarding.continuation_token = p_continuation_token
  for update;
  if not found or v_onboarding.applicant_user_id <> p_applicant_user_id then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_FOUND';
  end if;
  if v_onboarding.last_mutation_request_id = p_request_id or v_onboarding.state = 'withdrawn' then
    return query select v_onboarding.id, v_onboarding.state, true;
    return;
  end if;
  if v_onboarding.state not in ('draft','submitted','needs_changes') then
    raise exception 'COMUN_SOLIDARITY_ONBOARDING_NOT_WITHDRAWABLE';
  end if;
  update private.comun_solidarity_organization_onboarding onboarding set
    state = 'withdrawn', withdrawn_at = v_now, last_mutation_request_id = p_request_id,
    transition_history_private = onboarding.transition_history_private || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('event', 'withdrawn', 'actorUserId', p_applicant_user_id, 'at', v_now)
    )
  where onboarding.id = v_onboarding.id
  returning onboarding.id, onboarding.state into onboarding_id, state;
  idempotent := false;
  return next;
end;
$$;


ALTER FUNCTION public.comun_withdraw_solidarity_organization_onboarding_v1(p_request_id uuid, p_continuation_token uuid, p_applicant_user_id uuid) OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    begin
      if new.is_anonymous is true then
        return new;
      end if;

      insert into public.profiles (id, username, display_name)
      values (
        new.id,
        coalesce(
          new.raw_user_meta_data->>'username',
          pg_catalog.split_part(new.email, '@', 1)
        ),
        coalesce(
          new.raw_user_meta_data->>'display_name',
          pg_catalog.split_part(new.email, '@', 1)
        )
      )
      on conflict (id) do nothing;

      return new;
    end;
    $$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

