    CONSTRAINT comun_forwarding_packages_sensitive_policy_check CHECK ((((source_domain <> 'sensitive_service'::text) AND (policy_identifier IS NULL) AND (policy_version IS NULL) AND (disclosure_manifest = '{}'::jsonb) AND (content_withdrawn_at IS NULL)) OR ((source_domain = 'sensitive_service'::text) AND (policy_identifier = ANY (ARRAY['health_minimal_v1'::text, 'education_minimal_v1'::text, 'child_protection_channel_only_v1'::text])) AND (policy_version = 1) AND (jsonb_typeof(disclosure_manifest) = 'object'::text) AND ((disclosure_manifest ->> 'policy'::text) = policy_identifier) AND (jsonb_typeof((disclosure_manifest -> 'channelOnly'::text)) = 'boolean'::text) AND ((disclosure_manifest - ARRAY['policy'::text, 'includeIssueType'::text, 'includeUnitLabel'::text, 'includeNetworkLabel'::text, 'includeApproximatePeriod'::text, 'includePersonAuthoredSummary'::text, 'channelOnly'::text]) = '{}'::jsonb)))),
    CONSTRAINT comun_forwarding_packages_source_domain_check CHECK ((source_domain = ANY (ARRAY['bus'::text, 'essential_service'::text, 'sensitive_service'::text, 'civic_service'::text]))),
    CONSTRAINT comun_forwarding_packages_source_reference_check CHECK ((((source_domain = 'bus'::text) AND (bus_intake_id IS NOT NULL)) OR ((source_domain = ANY (ARRAY['essential_service'::text, 'sensitive_service'::text, 'civic_service'::text])) AND (bus_intake_id IS NULL)))),
    CONSTRAINT comun_forwarding_packages_state_check CHECK ((state = ANY (ARRAY['ready_for_forwarding'::text, 'forwarding_prepared'::text, 'person_declared_sent'::text, 'waiting_response'::text, 'responded'::text, 'withdrawn'::text]))),
    CONSTRAINT comun_forwarding_packages_subject_check CHECK (((char_length(subject) >= 8) AND (char_length(subject) <= 240)))
