    CONSTRAINT comun_solidarity_offers_availability_public_check CHECK (((availability_public IS NULL) OR (char_length(availability_public) <= 500))),
    CONSTRAINT comun_solidarity_offers_modalities_check CHECK ((((cardinality(modalities) >= 1) AND (cardinality(modalities) <= 8)) AND (modalities <@ ARRAY['sale'::text, 'exchange'::text, 'donation'::text, 'loan'::text, 'cession'::text, 'mutual_aid'::text, 'cooperation'::text, 'other'::text]) AND (array_position(modalities, NULL::text) IS NULL))),
    CONSTRAINT comun_solidarity_offers_offer_kind_check CHECK ((offer_kind = ANY (ARRAY['good'::text, 'service'::text, 'resource'::text, 'space'::text, 'skill'::text, 'support'::text, 'other'::text]))),
    CONSTRAINT comun_solidarity_offers_price_amount_cents_check CHECK (((price_amount_cents IS NULL) OR ((price_amount_cents >= 0) AND (price_amount_cents <= '9007199254740991'::bigint)))),
    CONSTRAINT comun_solidarity_offers_price_currency_check CHECK (((price_currency IS NULL) OR (price_currency = 'BRL'::text))),
    CONSTRAINT comun_solidarity_offers_price_note_public_check CHECK (((price_note_public IS NULL) OR (char_length(price_note_public) <= 300))),
    CONSTRAINT comun_solidarity_offers_price_pair CHECK ((((price_amount_cents IS NULL) AND (price_currency IS NULL)) OR ((price_amount_cents IS NOT NULL) AND (price_currency = 'BRL'::text)))),
    CONSTRAINT comun_solidarity_offers_public_summary_check CHECK (((char_length(btrim(public_summary)) >= 10) AND (char_length(btrim(public_summary)) <= 1200))),
    CONSTRAINT comun_solidarity_offers_publication_gate CHECK (((status <> 'published'::text) OR ((reviewed_at IS NOT NULL) AND (published_at IS NOT NULL) AND (valid_until IS NOT NULL) AND (valid_until > published_at)))),
    CONSTRAINT comun_solidarity_offers_slug_check CHECK (((slug = lower(slug)) AND (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text) AND ((char_length(slug) >= 3) AND (char_length(slug) <= 96)))),
    CONSTRAINT comun_solidarity_offers_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'published'::text, 'paused'::text, 'expired'::text, 'archived'::text]))),
    CONSTRAINT comun_solidarity_offers_title_check CHECK (((char_length(btrim(title)) >= 3) AND (char_length(btrim(title)) <= 140))),
    CONSTRAINT comun_solidarity_offers_validity_order CHECK (((published_at IS NULL) OR (valid_until IS NULL) OR (valid_until > published_at)))
);

