--
-- Name: comun_collective_action_task_assignments Members can claim own collective task; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Members can claim own collective task" ON public.comun_collective_action_task_assignments FOR INSERT TO authenticated WITH CHECK (((( SELECT auth.uid() AS uid) = member_user_id) AND (EXISTS ( SELECT 1
   FROM ((public.comun_collective_action_tasks task
     JOIN public.comun_collective_actions action ON ((action.id = task.action_id)))
     JOIN public.comun_collective_action_participations participation ON (((participation.action_id = action.id) AND (participation.member_user_id = ( SELECT auth.uid() AS uid)))))
  WHERE ((task.id = comun_collective_action_task_assignments.task_id) AND (task.state = ANY (ARRAY['open'::text, 'in_progress'::text])) AND (action.visibility = 'public'::text) AND (action.status = ANY (ARRAY['open'::text, 'active'::text, 'awaiting_result'::text])) AND (participation.status = ANY (ARRAY['participating'::text, 'available_for_task'::text, 'attended'::text, 'contributed'::text])))))));


--
-- Name: comun_collective_action_participations Members can create own collective participation; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Members can create own collective participation" ON public.comun_collective_action_participations FOR INSERT TO authenticated WITH CHECK (((( SELECT auth.uid() AS uid) = member_user_id) AND (EXISTS ( SELECT 1
   FROM public.comun_collective_actions action
  WHERE ((action.id = comun_collective_action_participations.action_id) AND (action.visibility = 'public'::text) AND (action.status = ANY (ARRAY['open'::text, 'active'::text, 'awaiting_result'::text])))))));


--
-- Name: comun_collective_action_participations Members can read own collective participation; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Members can read own collective participation" ON public.comun_collective_action_participations FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = member_user_id));


--
-- Name: comun_collective_action_task_assignments Members can read own collective task assignment; Type: POLICY; Schema: public; Owner: postgres
