CREATE POLICY "Members can read own collective task assignment" ON public.comun_collective_action_task_assignments FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = member_user_id));


--
-- Name: comun_collective_action_task_assignments Members can release own collective task; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Members can release own collective task" ON public.comun_collective_action_task_assignments FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = member_user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = member_user_id));


--
-- Name: comun_collective_action_participations Members can update own collective participation; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Members can update own collective participation" ON public.comun_collective_action_participations FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = member_user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = member_user_id));


