-- Name: comun_archive_relations Public reads public archive relations; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads public archive relations" ON public.comun_archive_relations FOR SELECT TO authenticated, anon USING (((internal_note IS NULL) AND (EXISTS ( SELECT 1
   FROM public.comun_archive_items i
  WHERE ((i.id = comun_archive_relations.source_item_id) AND (i.status = 'published'::text) AND (i.visibility = 'public'::text)))) AND (EXISTS ( SELECT 1
   FROM public.comun_archive_items i
  WHERE ((i.id = comun_archive_relations.target_item_id) AND (i.status = 'published'::text) AND (i.visibility = 'public'::text))))));


--
-- Name: comun_archive_collections Public reads published archive collections; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads published archive collections" ON public.comun_archive_collections FOR SELECT TO authenticated, anon USING (((status = 'published'::text) AND (published_at IS NOT NULL)));


--
-- Name: comun_archive_items Public reads published archive items; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads published archive items" ON public.comun_archive_items FOR SELECT TO authenticated, anon USING (((status = 'published'::text) AND (visibility = 'public'::text) AND (published_at IS NOT NULL)));


--
-- Name: comun_archive_collection_items Public reads published collection links; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads published collection links" ON public.comun_archive_collection_items FOR SELECT TO authenticated, anon USING (((EXISTS ( SELECT 1
   FROM public.comun_archive_collections c
  WHERE ((c.id = comun_archive_collection_items.collection_id) AND (c.status = 'published'::text)))) AND (EXISTS ( SELECT 1
   FROM public.comun_archive_items i
  WHERE ((i.id = comun_archive_collection_items.archive_item_id) AND (i.status = 'published'::text) AND (i.visibility = 'public'::text))))));


--
-- Name: comun_archive_assets Public reads safe approved archive assets; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads safe approved archive assets" ON public.comun_archive_assets FOR SELECT TO authenticated, anon USING (((bucket_scope = 'public_safe'::text) AND (review_status = 'approved'::text) AND (public_url IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.comun_archive_items i
  WHERE ((i.id = comun_archive_assets.archive_item_id) AND (i.status = 'published'::text) AND (i.visibility = 'public'::text))))));


--
-- Name: comun_community_work_group_tasks Public reads tasks linked to visible work groups; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Public reads tasks linked to visible work groups" ON public.comun_community_work_group_tasks FOR SELECT TO authenticated, anon USING ((EXISTS ( SELECT 1
   FROM public.comun_community_work_groups g
  WHERE ((g.id = comun_community_work_group_tasks.group_id) AND (g.state = ANY (ARRAY['active'::text, 'completed'::text]))))));


--
-- Name: knowledge_pages Páginas publicadas são visíveis publicamente; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Páginas publicadas são visíveis publicamente" ON public.knowledge_pages FOR SELECT USING ((is_published = true));


--
-- Name: knowledge_pages Qualquer autenticado pode editar página publicada; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Qualquer autenticado pode editar página publicada" ON public.knowledge_pages FOR UPDATE USING ((auth.uid() IS NOT NULL));


--
-- Name: comments Usuário autenticado pode comentar; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode comentar" ON public.comments FOR INSERT WITH CHECK ((auth.uid() = author_id));


--
-- Name: communities Usuário autenticado pode criar comunidade; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode criar comunidade" ON public.communities FOR INSERT WITH CHECK ((auth.uid() = created_by));


--
-- Name: posts Usuário autenticado pode criar post; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode criar post" ON public.posts FOR INSERT WITH CHECK ((auth.uid() = author_id));


--
-- Name: knowledge_pages Usuário autenticado pode criar página; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode criar página" ON public.knowledge_pages FOR INSERT WITH CHECK ((auth.uid() = created_by));


--
-- Name: reactions_as_actions Usuário autenticado pode registrar ação; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode registrar ação" ON public.reactions_as_actions FOR INSERT WITH CHECK ((auth.uid() = actor_id));


--
-- Name: project_links Usuário autenticado pode submeter link; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário autenticado pode submeter link" ON public.project_links FOR INSERT WITH CHECK ((auth.uid() = submitted_by));


--
-- Name: profiles Usuário pode editar seu próprio perfil; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário pode editar seu próprio perfil" ON public.profiles FOR UPDATE USING ((auth.uid() = id));


--
-- Name: reactions_as_actions Usuário pode remover sua própria ação; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Usuário pode remover sua própria ação" ON public.reactions_as_actions FOR DELETE USING ((auth.uid() = actor_id));


--
-- Name: comun_actions Visitors can insert lightweight actions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Visitors can insert lightweight actions" ON public.comun_actions FOR INSERT WITH CHECK ((action_type = ANY (ARRAY['confirm'::text, 'similar_report'::text, 'follow'::text, 'needs_check'::text, 'useful_material'::text, 'support'::text])));


--
-- Name: comun_reports Visitors can insert reports; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Visitors can insert reports" ON public.comun_reports FOR INSERT WITH CHECK (((raw_text IS NOT NULL) AND (status = 'received'::text) AND (public_text IS NULL) AND (internal_notes IS NULL)));


